  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    val n, M = ni()
    val MAX = isDebug(100, 1e5.toInt)
    val x = Array.ofDim[Int](MAX + 1)
    REP(n) { i =>
      x(ni()) += 1
    }
    val cntByM = Array.ofDim[Int](M)
    val pairsByM = Array.ofDim[Int](M)
    REP(MAX, 1) { i =>
      cntByM(i % M) += x(i)
      pairsByM(i % M) += x(i) / 2
    }

    debug(cntByM)
    debug(pairsByM)

    var ans = 0
    REP((M - 1) / 2, 1) { i =>
      val c = min(cntByM(i), cntByM(M - i))
      ans += c
      val single1 = cntByM(i) - pairsByM(i) * 2
      val single2 = cntByM(M - i) - pairsByM(M - i) * 2
      val usedPairs1 = (c - single1 + 1) / 2
      val usedPairs2 = (c - single2 + 1) / 2
      pairsByM(i) -= max(0, usedPairs1)
      pairsByM(M - i) -= max(0, usedPairs2)
    }

    ans += cntByM(0) / 2
    pairsByM(0) = 0
    if (M % 2 == 0) {
      ans += cntByM(M/2) / 2
      pairsByM(M/2) = 0
    }

    ans += pairsByM.sum
    out.println(ans)
  }
}

