signed main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	int n, m;
	cin >> n >> m;
	map<int, int> mp;
	map<int, int> mp2;

	rep(i, n) {
		int x;
		cin >> x;
		mp2[x]++;
	}

	int ans = 0;
	int oldans = -1;

	while (ans != oldans) {
		oldans = ans;
		each(i, mp2) {
			if (i.second % 2) {
				mp[i.first % m]++;
				i.second--;
			}
		}
		each(i, mp) {
			int x = i.first;
			int tm = min(mp[m - x], i.second);
			if (x == m - x) {
				tm /= 2;
				i.second -= tm * 2;
				ans += tm;
				continue;
			}
			i.second -= tm;
			mp[m - x] -= tm;
			ans += tm;
		}
		ans += mp[0] / 2;
		mp[0] -= (mp[0] / 2) * 2;

		each(i, mp2) {
			int t = min(i.second, mp[m - i.first % m]);
			i.second -= t;
			mp[m - i.first % m] -= t;
			ans += t;
		}
	}

	each(i, mp2) {
		ans += i.second / 2;
	}

	cout << ans << endl;

	return 0;
}

