        int y = m * k;
        cnt0 += mp[y];
    }
    ans += cnt0 / 2;
    for(int i = 1; i <= m; ++i) {
        int j = m - i;
        if(i > j) continue;
        else if(i < j) {
            int cnti = 0, cntj = 0;
            for(int k = 0; m * k + i <= 100000; ++k) {
                int y = m * k + i, z = m * k + j;
                cnti += mp[y];
                cntj += mp[z];
            }
            if(cnti <= cntj) {
                ans += cnti;
                int cnt = cntj - cnti; //同じカードのペアとして使えるカードの数
                for(int k = 0; m * k + j <= 100000; ++k) {
                    int z = m * k + j;
                    int c = mp[z];
                    if(cnt == 0) break;
                    if(c >= 2) {
                        int d = c / 2;
                        if(cnt >= d) {
                            ans += d; cnt -= 2 * d;
                        } else {
                            ans += cnt / 2; cnt = 0;
                        }
                    }
                    if(cnt == 0) break;
                }
            }

            if(cnti > cntj) {
                ans += cntj;
                int cnt = cnti - cntj; //同じカードのペアとして使えるカードの数
                for(int k = 0; m * k + i <= 100000; ++k) {
                    int z = m * k + i;
                    int c = mp[z];
                    if(cnt == 0) break;
                    if(c >= 2) {
                        int d = c / 2;
                        if(cnt >= 2 * d) {
