void solve(long long N, long long M, vector<long long> X){
	map<int,int> v;
	map<int,map<int,int> > v2;

	for(int i : X){
		v2[i%M][i]++;
		c[i%M]++;
	}
	for( auto &i : v2){
		int val = 0;
		for( auto &j : i.second ){
			val += j.second / 2;
		}
		up[i.first] = val;
	}

	long long ans = 0;
	//for(int i = 0 ; i < M ; i++) cout << i << " " << c[i] << endl;

	for(int i = 0 ; i <= M / 2 ; i++){
		if( i == 0 ){
			ans += c[i] / 2;
		}else if( i == M - i ){
			ans += c[i] / 2;
		}else{
			int u = min(c[i],c[M-i]);
			int p1 = min(up[i],(c[i]-u) / 2) + min((c[M-i]-u) / 2,up[M-i]) + u;

			int p2 = 0;
			if( u > 0 ){
				u--;
				p2 = min(up[i],(c[i]-u) / 2) + min((c[M-i]-u) / 2,up[M-i]) + u;
			}
