      if (a != -1 && b != -1) {
        ans++;
        qeven[i].emplace(a - 1);
        qeven[j].emplace(b - 1);
      } else if (a != -1) {
        int c = -1;
        if (qeven[j].size()) c = qeven[j].front(), qeven[j].pop();
        if (c != -1) {
          ans++;
          qodd[j].emplace(c - 1);
