void solve()
{
	ll Q=100000;
	ll n,m;  cin >> n >> m;
	vector<ll> x(n);  rep(i,0,n-1){ ll x_; cin>>x_; x[i]=x_; }

	vll cnt(Q+1);
	each(e,x){
		cnt[e]++;
	}

	vll re(m+1);
	each(e,x){
		re[e%m]++;
	}

	ll ans=0;
	rep(i,0,m/2){
		if (i==0 or (m%2==0 and i==m/2)){
			ans+=re[i]/2;
			re[i]%=2;
			continue;
		}

		ll v=min(re[i],re[m-i]);
		ans+=v;
		re[i]-=v;
		re[m-i]-=v;
	}

	rep(i,1,m-1){
		if (re[i]<=1) continue;

		ll sm=0;
		rep(j,0,Q){
			ll ii=i+j*m;
			if (ii>Q) break;

			sm+=cnt[ii]/2;
		}

		ans+=min(re[i]/2,sm);
	}
	cout << ans << '\n';
}


