// key = %m
struct da{
  int sum;
  int bulk;
  map<int,int> sames;
};
da data[125252];

int main(){
  scanf("%d%d",&n,&m);
  REP(i,n)scanf("%d",x+i);
  REP(i,n){
    int v = x[i];
    int key = v%m;
    data[key].sum += 1;
    data[key].sames[v]++;
  }
  REP(i,m){
    map<int,int>::iterator iter = data[i].sames.begin();
    while(iter != data[i].sames.end()){
      int key = iter->first;
      if(iter->second == 1){
        data[i].sames.erase(iter++);
        data[i].bulk++;
      }else{
        if(iter->second % 2 == 1){
          data[i].sames[key]--;
          data[i].bulk++;
        }
        iter++;
      }
    }
  }
  int ans = 0;
  REP(i,m/2+1){
    if(i == (m-i)%m){
      // same
      ans += data[i].sum/2;
    }else{
      // different
      int p = i;
      int q = m-i;
      int add = min(data[p].sum, data[q].sum);
      ans += add;
      {
        int y = p;
        int rest = add;
        rest -= data[y].bulk;
        for(auto P:data[i].sames){
          int num = P.second;
          int mn = min(rest,num);
          num -= mn;
          rest -= mn;
          ans += num/2;
        }
      }
    }
  }
  printf("%d\n",ans);
  return 0;
}

