                int now = sp + ujs;
                ans += now;
            } else {
                int p = count_pair(u[j]);
                int sp = min((ujs - uis) / 2, p);

                int now = sp + uis;
                ans += now;
            }

        }
    }

    cout << ans << endl;
}

