typedef map<int,int>::iterator IT;
int N,M,cnt;
map<int,int> tool[MAXM];
int odd[MAXM],pir[MAXM];
void solve(int a,int b)
{
	if(odd[a]>odd[b])
	{
		swap(odd[a],odd[b]);
		swap(pir[a],pir[b]);
	}
	int left=odd[b]-odd[a];
	int k=min(left>>1,pir[a]);
	odd[a]+=k<<1;
	pir[a]-=k;
	cnt+=odd[a];
	cnt+=pir[b]+pir[a];
}
void solve(int x)
{
	cnt+=pir[x];
	cnt+=odd[x]>>1;
}

