#include <vector>
namespace copr {
template <typename T>
struct Edge {
  using value_type = T;
  int from, to;
  value_type val;
  Edge(int from, int to, value_type val = 1) : from(from), to(to), val(val) {}
  bool operator<(const Edge& rhs) const {
    if (val != rhs.val) return val < rhs.val;
    if (from != rhs.from) return from < rhs.from;
    return to < rhs.to;
  }
  bool operator>(const Edge& rhs) const { return rhs < *this; }
};
template <typename T>
using Edges = std::vector<Edge<T>>;
} // namespace copr
namespace copr {
template <typename CapacityType>
struct ResidualGraph {
  struct REdge {
    using value_type = CapacityType;
    value_type cap;
    int to, rev;
    const bool is_rev;
    REdge(int to, value_type cap, int rev, bool is_rev)
        : to(to), cap(cap), rev(rev), is_rev(is_rev) {}
  };
  using value_type = std::vector<std::vector<REdge>>;

  const int V;
  value_type G;

  ResidualGraph(int V) : V(V), G(V) {}
  inline REdge& rev(const REdge& e) { return G[e.to][e.rev]; }
  void add_edge(int from, int to, CapacityType cap) {
    G[from].emplace_back(to, cap, G[to].size(), false);
    G[to].emplace_back(from, 0, G[from].size() - 1, true);
  }
};
} // namespace copr
namespace copr {
ResidualGraph<int> build_bipartite_graph(int X, int Y, const Edges<int>& edge) {
  ResidualGraph<int> G(X + Y + 2);
  for (int i = 0; i < X; i++) {
    G.add_edge(0, 1 + i, 1);
  }
  for (int i = 0; i < Y; i++) {
    G.add_edge(1 + X + i, 1 + X + Y, 1);
  }
  for (auto&& e : edge) {
    G.add_edge(1 + e.from, 1 + X + e.to, 1);
  }
  return G;
}
} // namespace copr
namespace copr {
template <typename GraphType>
struct graph_traits {
  using value_type = typename GraphType::value_type;
  using vertex_type = typename value_type::value_type;
  using edge_type = typename vertex_type::value_type;
  using cost_type = typename edge_type::value_type;
  using path_type = vertex_type;
};
