#include <algorithm>
#include <limits>
#include <queue>
namespace copr {
template <typename GraphType>
struct Dinic {
  using graph_type = GraphType;
  using edge_type = typename graph_traits<graph_type>::edge_type;
  using capacity_type = typename edge_type::value_type;

  static constexpr auto inf = std::numeric_limits<capacity_type>::max();
  const int UNREACHABLE = -1;

  graph_type& Gf;
  std::vector<int> level, iter;
  Dinic(graph_type& Gf) : Gf(Gf), level(Gf.V), iter(Gf.V) {}

  capacity_type max_flow_value(int s, int t) {
    capacity_type value = 0;
    while (labeling(s), level[t] != UNREACHABLE) {
      std::fill(iter.begin(), iter.end(), 0);
      capacity_type bf;
      while (bf = blocking_flow(s, t, inf), bf > 0) {
        value += bf;
      }
    }
    return value;
  }
  bool labeling(int s) {
    std::fill(level.begin(), level.end(), UNREACHABLE);
    level[s] = 0;
    static std::queue<int> Q;
    Q.push(s);
    for (; not Q.empty(); Q.pop()) {
      auto v = Q.front();
      for (auto& e : Gf.G[v]) {
        if (level[e.to] != UNREACHABLE) continue;
        if (e.cap == 0) continue;
        level[e.to] = level[v] + 1;
        Q.push(e.to);
      }
    }
    return true;
  }
  capacity_type blocking_flow(int v, int t, capacity_type f) {
    if (v == t) return f;
    auto& V = Gf.G[v];
    for (int& i = iter[v]; i < V.size(); ++i) {
      auto& e = V[i];
      if (e.cap == 0) continue;
      if (level[v] >= level[e.to]) continue;
      auto bf = blocking_flow(e.to, t, std::min(f, e.cap));
      if (bf > 0) {
        e.cap -= bf;
        Gf.rev(e).cap += bf;
        return bf;
      }
    }
    return 0;
  }
};
template <typename T, typename GraphType = ResidualGraph<T>>
Dinic<GraphType> dinic(ResidualGraph<T>& Gf) {
  return Dinic<GraphType>(Gf);
}
} // namespace copr
namespace copr {
int bipartite_matching(int X, int Y, const Edges<int>& edge) {
  auto graph = copr::build_bipartite_graph(X, Y, edge);
  return copr::dinic(graph).max_flow_value(0, 1 + X + Y);
}
} // namespace copr
namespace copr {
template <typename CostType>
struct Graph {
  using value_type = std::vector<Edges<CostType>>;
  const int V;
  value_type G;
  Graph(int V) : V(V), G(V) {}
  void add_edge(int from, int to, CostType cost, bool undirected = true) {
    G[from].emplace_back(from, to, cost);
    if (undirected) G[to].emplace_back(to, from, cost);
  }
};
} // namespace copr
namespace copr {
template <typename T>
Graph<T> build_flow(ResidualGraph<T>& Gf) {
  Graph<T> flow(Gf.V);
  for (int v = 0; v < Gf.V; v++) {
    for (auto& e : Gf.G[v]) {
      if (not e.is_rev) continue;
      if (e.cap == 0) continue;
      flow.add_edge(e.to, v, e.cap, false);
    }
  }
  return flow;
}
