#include <map>
using namespace std;

const int N = (int) 1e5;
map<int, int> num[N];
int cnt[N];

int tryPairing(const map<int, int> &num) {
    int res = 0;
    for (auto x : num) res += x.second / 2;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    int n; cin >> n;
    int m; cin >> m;
    for (int i = 0; i < n; ++i) {
        int x; cin >> x;
        ++num[x % m][x];
        ++cnt[x % m];
    }
    int res = 0;
    for (int i = 0; i < m; ++i) {
        int oldres = res;
        int j = (m - i) % m;
        if (i > j) continue;
        if (i == j) {
            res += cnt[i] / 2;
        } else {
            int ni = tryPairing(num[i]);
            int nj = tryPairing(num[j]);
            int lefti = cnt[i] - 2 * ni;
            int leftj = cnt[j] - 2 * nj;
            int best = ni + nj + min(lefti, leftj);
            for (int cross = 1; cross <= min(cnt[i], cnt[j]); ++cross) {
                if (lefti < cross) {
                    lefti += 2;
                    ni -= 1;
                }
                if (leftj < cross) {
                    leftj += 2;
                    nj -= 1;
                }
                best = max(best, ni + nj + cross);
            }
            res += best;
        }
        //cout << i << ' ' << j << ' ' << res - oldres << endl;
    }
    cout << res << endl;
    return 0;
}

