int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N, M; cin >> N >> M;
  VI xs(N);
  REP(i,N) cin >> xs[i];
  SORT(xs);

  VI s(M), d(M);
  int prv = 0, c = 0;
  REP(i,N){
	if(xs[i] == prv) ++c;
	else{
	  s[prv%M] += c/2;
	  d[prv%M] += c%2;
	  prv = xs[i];
	  c = 1;
	}
