	int sj = s[j]*2 + d[j];
	if(si < sj){
	  swap(si, sj);
	  swap(ii,j);
	}
	int m = min(si, sj);
	ans += m;
	ans += (s[ii] * 2 - max(0, m - d[ii])) / 2;

	//cout << j << " - " << ii << " -> " << m << " , " << (s[ii] * 2 +d[ii] - m) / 2 << endl;
  }

