        for(auto p : v[i]) {
            mp[p]++;
        }
        ll cnt = 0;
        for(auto p : mp) {
            ll nokori = U - 2*cnt;
            if(p.second <= nokori) {
                cnt += p.second/2;
            }
            else {
                cnt += nokori/2;
            }
        }
        ans += cnt;
    }

    out(ans);
    re0;
