        Fr(i,(m-1)/2){
            int k=min(z[i],z[m-i]);
            ans+=k;
            z[i]-=k;z[m-i]-=k;
            ans+=min(z[i]/2,w[i]);
            ans+=min(z[m-i]/2,w[m-i]);
        }
        out<<ans<<endl;
    }
};

int main() {
    DPairCards solver;
    std::istream& in(std::cin);
    std::ostream& out(std::cout);
    solver.solve(in, out);
    return 0;
}

