    if(v.size()>w.size()) swap(v,w);
    re+=v.size()+min<int>((w.size()-v.size())/2,same(w));
  }
  //cout<<re<<endl;
  if(m%2==0){
    //cout<<vs[m/2]<<endl;
    re+=vs[m/2].size()/2;
  }
  cout<<re<<endl;
  return 0;
}

