int kind[100100];

int main(){
  int N,M; cin >> N >> M;

  vector<int> vec(M,0); // vec[i]はMで割ってi余る要素の個数
  vector<int> same(M,0); // same[i]はMで割ってi余るグループのうち同一なものの個数


  for(int i = 0; i < N; i++){
    int X; cin >> X; kind[X]++;
    vec[X%M]++;
  }

  for(int i = 0; i < 100100; i++){
    if( kind[i] >= 2){
    same[i%M] += kind[i];
    }
  }
  int cnt = 0;

  // == 0 or == M/2は特別扱い
  cnt += vec[0]/2;
  if( M%2 == 0 ){ cnt += vec[(M/2)]/2;}

  for(int x = 1; x <= (M-1)/2; x++){
    // x と M-xについてみる
    int r1 = vec[x];
    int r2 = vec[M-x];

    int res = min(r1,r2); //両方の組みからできるペアの数は以下の通り

    cnt += res;

    same[x] -= max(0,res-(vec[x]-same[x])); //ここがおかしい
    same[M-x] -= max(0,res-(vec[M-x]-same[M-x]));

  }


  //残りは同じグループ同士で、同じ数をくっつけあう
  for(int x = 1; x <= M-1; x++){

    if( x == M/2 && M%2 == 0){ continue;}

    cnt += max(0,same[x])/2;

  }

  cout << cnt << endl;


  return 0;
}

