int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<int> x(n);
	int memo[100010] = {};
	for (int i = 0; i < n; i++) {
		cin >> x[i];
		memo[x[i]]++;
	}

	vector< vector<int> > a(m);
	for (int i = 1; i <= 100000; i++) {
		a[i % m].push_back(memo[i]);
	}

	vector< vector<int> > as(m);
	for (int i = 0; i < m; i++) {
		if (a[i].size() == 0) continue;
		as[i] = vector<int>(a[i].size());
		as[i][0] = a[i][0];

		for (int j = 1; j < (int)a[i].size(); j++) {
			//cout << a[i][j] << endl;
			as[i][j] = as[i][j - 1] + a[i][j];
		}
		//cout << as[i].back() << endl;
	}

	int ans = as[0].back() / 2;
	if (m % 2 == 1) {
		for (int i = 1; i <= m / 2; i++) {
			int c = min(as[i].back(), as[m - i].back());
			//cout << as[i].back() << " " << as[m - i].back() << endl;
			if (c == 0) continue;
			ans += c;
			if (as[i].back() > as[m - i].back()) {
				int idx = upper_bound(as[i].begin(), as[i].end(), c) - as[i].begin();
				as[i][idx] -= c;
				a[i][idx] = as[i][idx];
				for (int j = idx; j < (int)a[i].size(); j++) {
					ans += a[i][j] / 2;
				}
			} else if (as[i].back() < as[m - i].back()) {
				int idx = upper_bound(as[m - i].begin(), as[m - i].end(), c) - as[m - i].begin();
				as[m - i][idx] -= c;
				a[m - i][idx] = as[m - i][idx];
				for (int j = idx; j < (int)a[m - i].size(); j++) {
					ans += a[m - i][j] / 2;
				}
			}
		}
	} else {
		for (int i = 1; i < m / 2; i++) {
			int c = min(as[i].back(), as[m - i].back());
			if (c == 0) continue;
			ans += c;
			if (as[i].back() > as[m - i].back()) {
				int idx = upper_bound(as[i].begin(), as[i].end(), c) - as[i].begin();
				as[i][idx] -= c;
				a[i][idx] = as[i][idx];
				for (int j = idx; j < (int)a[i].size(); j++) {
					ans += a[i][j] / 2;
				}
			} else if (as[i].back() < as[m - i].back()) {
				int idx = upper_bound(as[m - i].begin(), as[m - i].end(), c) - as[m - i].begin();
				as[m - i][idx] -= c;
				a[m - i][idx] = as[m - i][idx];
				for (int j = idx; j < (int)a[m - i].size(); j++) {
					ans += a[m - i][j] / 2;
				}	
			}
		}
		ans += as[m / 2].back() / 2;
	}
	cout << ans << endl;
	return 0;
}

