bool multicase = false;

ll n,m,num,a,b,c,d,e,h,q;
ll w, k, ans;
ll x[500005], y[500005];
ll dp[15][500005];
string s;
ll query = 0;

vector<ll> G[500005];

ll calc(ll idx){
    ll sum = 0;
    for(ll i=0;i<G[idx].size();i++){
        sum += G[idx][i];
    }
    return sum / 2;
}

void solve(){
    cin >> n >> m;
    // x: 数列そのまま
    // y: 出現回数をメモ
    for(ll i=0;i<n;i++){
        cin >> x[i];
        y[x[i]] ++;
    }
    for(ll i=1;i<100000;i++){
        if(y[i] == 0)continue;
        G[i % m].pb(y[i]);
    }
    /// G[あまり]=出現回数のベクター
    ll ans = 0;
    for(ll i=1;i<m;i++){
        ll a = i, b = m - a;
        if(a == b)continue;
        ll even1 = 0, even2 = 0;
        ll odd1 = 0, odd2 = 0;
        for(ll j=0;j<G[a].size();j++){
            if(G[a][j] % 2 == 0)even1 += G[a][j] / 2;
            if(G[a][j] % 2 == 1){
                even1 += G[a][j] / 2;
                odd1 ++;
            }
        }
        for(ll j=0;j<G[b].size();j++){
            if(G[b][j] % 2 == 0)even2 += G[b][j] / 2;
            if(G[b][j] % 2 == 1){
                even2 += G[b][j] / 2;
                odd2 ++;
            }
        }
        ll res = min(odd1, odd2);
        odd1 -= res; odd2 -= res;
        ans += res;
        if(odd2 != 0){
            swap(odd1, odd2);
            swap(even1, even2);
        }
        if(odd1 != 0){
            ans += even1;
            if(even2 * 2 >= odd1){
                ans += odd1 + (even2 - (odd1 + 1) / 2);
            }else{
                ans += even2 * 2;
            }
        }else{
            ans += even1 + even2;
        }
        G[a].clear(); G[b].clear();
    }
    ans += calc(0);
    if(m % 2 == 0)ans += calc(m/2);
    p(ans);
    return;
}


