// 最大マッチング

// 考察スペース
// 7 5
// 3 1 4 1 5 9 2
// group[0] := 5
// group[1] := 1, 1
// group[2] := 2
// group[3] := 3
// group[4] := 4, 9

// 15 10
// 1 5 6 10 11 11 11 20 21 25 25 26 99 99 99
//
// group[0] := 10, 20
// group[1] := 1, 11, 11, 11, 21
// group[2] := 
// group[3] :=
// group[4] := 
// group[5] := 5, 25, 25
// group[6] := 6, 26
// group[7] :=
// group[8] :=
// group[9] := 99, 99, 99

int main() {

  int n, m; cin >> n >> m;
  vector<int> x(n);
  for(int i = 0; i < n; i++) {
    cin >> x[i];
  }

  // m で割った余りによるグループ分け
  vector<vector<int>> group(m);
  sort(ALL(x));
  for(int i = 0; i < n; i++) {
    group[x[i] % m].push_back(x[i]);
  }

  int ans = 0;
  // 割って余り 0 のグループは自分らでマッチング
  ans += group[0].size() / 2;
  // 同様に, 割って余りが m / 2 のグループは自分らでマッチング
  // m = 4 の時は 2 + 2 とか
  if(m % 2 == 0) ans += group[m / 2].size() / 2;
  // 後はグループ i と グループ n - i とのマッチング
  for(int i = 1; i < m / 2 + (m % 2); i++) {
    vector<int> S;
    vector<int> T;
    if(group[i].size() < group[m - i].size()) {
      S = group[i];
      T = group[m - i];
    } else {
      S = group[m - i];
      T = group[i];
    }

    // |S| <= |T|
    assert(S.size() <= T.size());

    // T の要素を, |T| - |S| を超えない範囲でマッチングさせる.
    int cnt = 0;
    for(int i = 0; i < T.size() - 1 and cnt < T.size() - S.size(); i++) {
      if(T[i] == T[i + 1]) {
        i++;
        cnt++;
      }
    }
    // cerr << "i : " << i << ", cnt : " << cnt << ", |S| = " << S.size() << endl;
    ans += cnt;

    // |S| と |T| の残りをマッチングさせる
    ans += S.size();
  }

  cout << ans << endl;
  return 0;
}

