void solve() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> cards(m);
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        cards[x % m].push_back(x);
    }
    vector<int> sum(m), odd(m);
    for (int i = 0; i < m; ++i) {
        sum[i] = cards[i].size();
        sort(all(cards[i]));
        for (int j = 0; j < cards[i].size(); ) {
            int r = j;
            while (r < cards[i].size() && cards[i][j] == cards[i][r]) {
                ++r;
            }
            int cnt = r - j;
            if (cnt & 1) {
                ++odd[i];
            }
            j = r;
        }
    }

    int dp = 0;
    for (int i = 1; i < (m + 1) / 2; ++i) {
        int j = m - i;
        int new_dp = -1;
        for (int x = 0; x <= sum[i] && x <= sum[j]; ++x) {
            int even_i;
            if (x <= odd[i]) {
                even_i = sum[i] - odd[i];
            }
            else {
                even_i = sum[i] - x;
            }
            int even_j;
            if (x <= odd[j]) {
                even_j = sum[j] - odd[j];
            }
            else {
                even_j = sum[j] - x;
            }
            new_dp = max(new_dp, dp + x + even_i / 2 + even_j / 2);
            //cout << i << ' ' << j << ' ' << even_i << ' ' << even_j << ' ' << x << "\n";
        }
        //cout << new_dp << "\n";
        dp = new_dp;
    }

    dp += sum[0] / 2;
    if (m % 2 == 0) {
        dp += sum[m / 2] / 2;
    }

    cout << dp << "\n";

}

