const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll N, M;
vector<ll> X;
void solve(){
  vector<ll> E[100010];
  rep(i, N) E[X[i] % M].pb(X[i]);

  rep(i, M){
    sort(E[i].begin(), E[i].end());
    vector<ll> EX = E[i];
    vector<ll> EY = E[i];
    EX.erase(unique(EX.begin(), EX.end()), EX.end());
    revrep(j, EY.size()){
      if(j == 0){
        EY[j] = -1;
        continue;
      }
      if(EY[j] != EY[j-1]){
        EY[j] = -1;
      }
    }
    rep(j, EY.size()){
      if(EY[j] != -1){
        EX.pb(EY[j]);
      }
    }
    E[i] = EX;
  }

  ll ans = 0;
  ans += E[0].size() / 2;
  if(M % 2 == 0){
    ans += E[M/2].size() / 2;
  }
  for(ll i = 1; i <= (M-1) / 2; i++){
    ll a = i;
    ll b = M - i;
    ll al = E[a].size();
    ll bl = E[b].size();
    ans += min(al, bl);
    if(al < bl){
      for(ll j = al; j < bl - 1; j++){
        if(E[b][j] == E[b][j+1]){
          ans++;
          j++;
        }
      }
    }else{
      for(ll j = bl; j < al - 1; j++){
        if(E[a][j] == E[a][j+1]){
          ans++;
          j++;
        }
      }
    }
  }
  cout << ans << endl;
}

