			pr[a[i] % m] += 2;
			a[i] *= -1;
			a[i-1] *= -1;
		}
	}

	ans += mod[0] / 2;
	for(int i = 1; i < (m+1) / 2; i++){
		int tmp = min(mod[i], mod[m - i]);
		ans += tmp;
		mod[i] -= tmp;
		mod[m - i] -= tmp;
	}
	if(m % 2 == 0){
		ans += mod[m / 2] / 2;
		mod[m / 2] /= 2;
	}

	for(int i = 1; i < m; i++){
		ans += min(mod[i] / 2, pr[i] / 2);
	}

