			res += min(num[i], same[i] * 2) / 2;
			num[i] -= min(num[i], same[i] * 2) / 2;
			res += min(num[(M - i) % M], same[(M - i) % M] * 2) / 2;
			num[(M - i) % M] -= min(num[(M - i) % M], same[(M - i) % M] * 2) / 2;
		}
	}
	cout << res << endl;
	return 0;
}

