int main() {
    int n, m;
    in(n, m);

    auto x = vin<int>(n);
    sort(x.begin(), x.end());

    auto y = x;
    auto c = vector<int>(m);
    auto d = vector<int>(m);

    map<int, int> ma;
    for (int &i : y) {
        ma[i]++;
        i %= m;
        c[i]++;
    }

    for (auto &a : ma) {
        d[a.first % m] += a.second / 2;
    }

    int ans = 0;
    for (int i : rep(0, m)) {
        if (i > m - i) continue;
        if (i == 0) {
            ans += c[0] / 2;
        } else if (i == m - i) {
            ans += c[i] / 2;
        } else {
            if (c[i] == c[m - i]) {
                ans += c[i];
            } else if (c[i] < c[m - i]) {
                int dif = c[m - i] - c[i];
                ans += min(dif / 2, d[m - i]);
                ans += min(c[i], c[m - i]);
            } else if (c[i] > c[m - i]) {
                int dif = c[i] - c[m - i];
                ans += min(dif / 2, d[i]);
                ans += min(c[i], c[m - i]);
            }
        }
    }

    out(ans);
}

