	cin.tie(nullptr);

	int N, M;
	cin >> N >> M;
	vector<int>X(N);
	map<int, int>mp;
	priority_queue<pair<ll, ll>>q[101010];
	for (int i = 0; i < N; i++) {
		cin >> X[i];
		mp[X[i]]++;
	}
	int ans = 0;
	fore(x, mp)q[x.first % M].push({x.second % 2,x.first});

	for (int i = 1; i <= M - 1; i++) {
		if (M - i == i)continue;
		while (q[i].size() && q[M - i].size()) {
			pair<ll,ll>tp1 = q[i].top();
			pair<ll, ll>tp2 = q[M - i].top();
			q[i].pop();
			q[M - i].pop();
			ll x1 = tp1.second;
			ll m1 = tp1.first;
			ll x2 = tp2.second;
			ll m2 = tp2.first;
			ans++;
			mp[x1]--;
			mp[x2]--;
			if (mp[x1] != 0)q[i].push({1-m1,x1});
			if (mp[x2] != 0)q[M - i].push({1-m2,x2});
		}
	}

	ll cntdiv = 0;
	ll cnthalf = 0;
	fore(x, mp) {
		ll num = x.first;
		ll cnt = x.second;
		if (num % M == 0)cntdiv += cnt;
		else if(M%2 == 0 && M/2 == num%M)cnthalf += cnt;
		else ans += cnt / 2;
	}
	ans += (cntdiv / 2) + (cnthalf / 2);
	puts(ans);

	return 0;
}

