        input[i] = 0;
        c[i] = 0;
    }
    for(int i=0;i<N;i++){
        cin >> x;
        input[x]++;
    }
    for(int i=1;i<=100000;i++){
        if(input[i] != 0){
            mod[i%M].push_back(input[i]);
            c[i%M] += input[i];
        }
    }
    for(int i=0;i<M;i++){
        sort(mod[i].begin(),mod[i].end());
    }
    ll ans = 0;
    ans += c[0]/2;
    if(M % 2 == 0) ans += c[M/2] / 2; 
    for(int i=1;i<=M/2;i++){
        if(M%2 == 0 && i == M/2) continue;
        ll b = min(c[i],c[M-i]);
        ans += b;
        if(b < c[i]){
            ll d = b;
            for(int j=0;j<mod[i].size();j++){
                if(d > 0){
                    if(d >= mod[i][j]){
                        d -= mod[i][j];
                        continue;
                    }
                    mod[i][j] -= d;
                    d = 0;
                }
                ans += mod[i][j] / 2;
            }
        }
        if(b < c[M-i]){
            ll d = b;
            for(int j=0;j<mod[M-i].size();j++){
                if(d > 0){
                    if(d >= mod[M-i][j]){
                        d -= mod[M-i][j];
                        continue;
                    }
                    mod[M-i][j] -= d;
                    d = 0;
                }
                ans += mod[M-i][j] / 2;
            }
        }
    }
