                cnt += que[a].top().second;
                que[a].pop();
            }
            ans += cnt / 2;
            continue;
        }
        while(!que[a].empty() && !que[b].empty()){
            auto p = que[a].top();
            que[a].pop();
            auto q = que[b].top();
            que[b].pop();
            p.second--;
            q.second--;
