		used[X]++;
		if (used[X] % 2 == 0) {
			same[X % M]++;
		}
	}
	int res = 0;
	for (int i = 0; i < M && i <= (M + 1) / 2; i++) {
		if (i == (M - i) % M) {
			res += num[i] / 2;
			num[i] %= 2;
		}
		else {
			int val = min(num[i], num[(M - i) % M]);
			if ((num[i] - val) % 2 && (num[(M - i) % M] - val) % 2 && same[i] * 2 > val && same[(M - i) % M] * 2 > val) val--;
			res += val;
			num[i] -= val;
			num[(M - i) % M] -= val;
			res += min(num[i], same[i] * 2) / 2;
			res += min(num[(M - i) % M], same[(M - i) % M] * 2) / 2;
		}
	}
