		}
		sort(tmp.begin(), tmp.end());

		int pointer = 0;
		use[i] -= binaryed;
		while (pointer < tmp.size() && use[i] > 0) {
			if (use[i] >= tmp[pointer]) {
				use[i] -= tmp[pointer];
				tmp[pointer] = 0;
			}
			else {
				tmp[pointer] -= use[i];
				use[i] = 0;
			}
			pointer++;
		}
		for (int j = 0; j < tmp.size(); j++) {
			ans += (tmp[j] / 2);
		}
	}
