    container[x[i] % m].push_back(x[i]);
  }

  for (auto &e : container) {
    map<int, int> cnt;

    for (auto &d : e.second) {
      cnt[d] += 1;
    }

    for (auto &d : e.second) {
      container_pair[e.first].push_back(make_pair(-1 * cnt[d], d));
    }
  }

  for (auto &e : container_pair) {
    sort(e.second.begin(), e.second.end());  // duplicate comes first
  }

  ans = 0;

  for (auto &e : container_pair) {
    int key = e.first;
    int size = e.second.size();

    int opposite_key = m - key;

    if (opposite_key == key) {
      int pop_size = container_pair[key].size() / 2;

      for (int i = 0; i < pop_size; ++i) {
        container_pair[key].pop_back();
      }
      ans += pop_size;
    } else {
      int pop_size =
          min(container_pair[key].size(), container_pair[opposite_key].size());

      for (int i = 0; i < pop_size; ++i) {
        container_pair[key].pop_back();
      }

      for (int i = 0; i < pop_size; ++i) {
        container_pair[opposite_key].pop_back();
      }

      ans += pop_size;
    }
  }

  for (auto &e: container_pair) {
    for (int i = e.second.size() - 1; i > 0; --i) {
      if (e.second[i].second == e.second[i - 1].second) {
        ans += 1;
        i -= 1;
      }
