    Int func(Int m) {
        if ((m + m) % M == 0) {
            Int ret = static_cast<Int>(Y[m].size() / 2);
            return ret;
        }

        Int ret = 0ll;
        Int n = M - m;
        if (Y[m].size() == Y[n].size()) {
            return static_cast<Int>(Y[m].size());
        } else if (Y[m].size() < Y[n].size()) {
            ret += Y[m].size();
            map<Int, Int> neri;
            for (int i = 0; i < Y[n].size(); ++i) {
                neri[Y[n][i]]++;
            }

            Int tmp = 0;
            for (auto e : neri) {
                tmp += e.second / 2;
            }
            ret += min<Int>(tmp, static_cast<const Int &>((Y[n].size() - Y[m].size()) / 2));
        } else {
            swap(n, m);
            ret += Y[m].size();
            map<Int, Int> neri;
            for (int i = 0; i < Y[n].size(); ++i) {
                neri[Y[n][i]]++;
            }

            Int tmp = 0;
            for (auto e : neri) {
                tmp += e.second / 2;
            }
            ret += min<Int>(tmp, static_cast<const Int &>((Y[n].size() - Y[m].size()) / 2));
        }

        return ret;
    }

