namespace tree {
struct union_find {
  vector<int> par, rank, size;
  int compnum;

  union_find(int N) {
    compnum = N;
    par.resize(N), rank.resize(N), size.resize(N);
    for(int i=0; i<N; i++) {
      par[i] = i;
      rank[i] = 0;
      size[i] = 1;
    }
  }

  int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]);
  }

  void unite(int x, int y) {
    x = root(x), y = root(y);
    if(x == y) return;
    if(rank[x] < rank[y]) {
      par[x] = y, size[y] += size[x];
    } else {
      par[y] = x, size[x] += size[y];
      if(rank[x] == rank[y]) rank[x]++;
    }
    compnum--;
  }

  int operator[](int x) { return root(x); }
  void operator()(int x, int y) { return unite(x, y); }

  bool same(int x, int y) { return root(x) == root(y); }
  int size_of(int x) { return size[root(x)]; }
  int num_of_comps() { return compnum; }
};
}

int main() {

  int N, M; cin >> N >> M;
  vector<int> X(N);
  rep(i, N) {
    cin >> X[i];
  }

  sort(all(X));

  tree::union_find uf(N);

  // 元のindexが同じUFをする
  rep(i, N - 1) {
    if(X[i] == X[i + 1]) {
      uf(i, i + 1);
    }
  }

  map<int, int> st;

  // MODが同じ数で、元の値ごとに、数の総数が奇数かどうかを調べる。
  unordered_map<int, unordered_map<int, bool>> odd;
  rep(i, N) {
    odd[X[i] % M][X[i]] ^= 1;
    // Mでmodをとり
    X[i] %= M;
    // 端数の一致する対称を詰める
    st[(M - X[i]) % M] ++;
  }

  unordered_map<int, int> oddcnt;
  for(auto const& e: odd) {
    int ocnt = 0;
    for(auto const& u: e.second) {
      if(u.second) ocnt++;
    }
    oddcnt[e.first] = ocnt;
  }

  ll ans = 0;

  unordered_map<int, int> selectedXCnt;

  rep(i, N) {
    auto tmp = (M - X[i]) % M;

    if(st[tmp] == 0) continue;

    // 自分は選んだので消す
    st[tmp]--;

    // 自分の端数対称が一致するものを見つけては消す
    if(st[X[i]] > 0) {
      selectedXCnt[X[i]]++;
      st[X[i]]--;
      ans ++;
    }
    else {
      // 復活
      st[tmp]++;
    }
  }

  for(auto const& e: st) {
    auto x = e.first;
    auto a = oddcnt[x];
    auto b = selectedXCnt[x];
    ans += (e.second - max(0, b*2 - a)) / 2;
  }

  cout << ans << endl;

