int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(m);
    vector<pair<int, int>> dat(m, make_pair(0, 0));
    for (int i = 0; i < n; i++) {
        int e; cin >> e;
        a[e%m].emplace_back(e);
    }
    for (int i = 0; i < m; i++) sort(a[i].begin(), a[i].end());
    for (int i = 0; i < m; i++) {
        const auto &v = a[i];
        const int k = (int)v.size();
        for (int j = 0; j < k; j++) {
            if (j+1 < k and v[j] == v[j+1]) dat[i].first++, j++;
            else dat[i].second++;
        }
    }

    int ans = 0;
    for (int i = 0; i < m; i++) {
        int j = (m - i) % m;
        if (j < i) continue;
        if (i == j) { ans += dat[i].first + dat[i].second / 2; continue; }
        pair<int, int> s = dat[i], t = dat[j];
        if (s.first > t.first and s.second > t.second) {
            ans += s.first + t.first + t.second; continue;
        }
        if (s.first < t.first and s.second < t.second) {
            ans += s.first + t.first + s.second; continue;
        }
        if (s.first >= t.first and s.second <= t.second) swap(s, t);
        ans += s.first + t.second; s.second -= t.second;
        if (s.second & 1) s.second--;
        t.first *= 2;
        ans += min(t.first, s.second);
        t.first = max(0, t.first - s.second);
        ans += t.first / 2;
    }
    cout << ans << endl;
    return 0;
}

