			{
				pL++;
				j++;
			}
		for (int j = 0; j + 1 < (int) v[m - i].size(); j++)
			if (v[m - i][j] == v[m - i][j + 1] )	
			{
				pR++;
				j++;
			}
		int p = min(v[i].size(), v[m - i].size() );
		int bst = 0;
