			swap(memo[a][1], memo[b][1]);
		}
		ans += memo[b][0];
		memo[a][0] -= memo[b][0];
		ans += min(memo[a][0], memo[b][1] * 2) + memo[a][1] + max(memo[b][1] - memo[a][0], 0) / 2;
	}
