      if (pq2.first - cnt > 0)
      {
        pque[m2].push(make_pair(pq2.first - cnt, pq2.second));
      }
    }
    for (auto idx : {m1, m2})
    {
      while (!pque[idx].empty())
      {
        auto pq = pque[idx].top();
        pque[idx].pop();
        ll cnt = pq.first / 2;
        ans += cnt;
      }
    }
  }

  vector<ll> rest;
  rest.push_back(0);
  if (m % 2 == 0)
    rest.push_back(m / 2);
  for (auto idx : rest)
  {
    ll cnt = 0;
    while (!pque[idx].empty())
    {
      auto pq = pque[idx].top();
      pque[idx].pop();
      cnt += pq.first;
    }
    ans += cnt / 2;
  }

  cout << ans << endl;

  return 0;
}

ll mod_pow(ll x, ll r)
{
  if (r == 0)
    return 1;
  else if (r == 1)
    return x % mod;
  else if (r % 2 == 0)
  {
    ll t = mod_pow(x, r / 2) % mod;
    return mod_mul(t, t);
  }
  else
  {
    ll t = mod_pow(x, r / 2) % mod;
    ll k = mod_mul(t, t);
    return (k % mod) * (x % mod);
  }
}
ll mod_add(ll a, ll b)
{
  return ((a % mod) + (b % mod)) % mod;
}

ll mod_mul(ll a, ll b)
{
  return ((a % mod) * (b % mod)) % mod;
}

ll mod_div(ll a, ll b)
{
  return mod_mul(a, mod_pow(b, mod - 2));
}

