void solve() {
  int n, m;
  cin >> n >> m;
  vi32 cnt(100001);
  vi32 x(n);
  rep(i, n) {
    int x;
    cin >> x;
    cnt[x]++;
  }
  vector<queue<int>> qodd(m);
  vector<queue<int>> qeven(m);
  rep(i, 100001) {
    if (cnt[i] == 0) continue;
    if (cnt[i] % 2 == 1) {
      qodd[i % m].emplace(cnt[i]);
    } else {
      qeven[i % m].emplace(cnt[i]);
    }
  }
  int ans = 0;
  repc(i, m / 2) {
    int j = (m - i) % m;
    while (true) {
      int a = -1, b = -1;
      if (qodd[i].size()) a = qodd[i].front(), qodd[i].pop();
      if (qodd[j].size()) b = qodd[i].front(), qodd[j].pop();
      if (a != -1 && b != -1) {
        ans++;
        if (a - 1 != 0) qeven[i].emplace(a - 1);
        if (b - 1 != 0) qeven[j].emplace(b - 1);
      } else if (a != -1) {
        int c = -1;
        if (qeven[j].size()) c = qeven[j].front(), qeven[j].pop();
        if (c != -1) {
          ans++;
          qodd[j].emplace(c - 1);
        }
        if (a - 1 != 0) {
          qeven[i].emplace(a - 1);
        }
      } else if (b != -1) {
        int c = -1;
        if (qeven[i].size()) c = qeven[i].front(), qeven[i].pop();
        if (c != -1) {
          ans++;
          qodd[i].emplace(c - 1);
        }
        if (b - 1 != 0) {
          qeven[j].emplace(b - 1);
        }
      } else {
        break;
      }
    }
    while (qeven[i].size()) ans += qeven[i].front() / 2, qeven[i].pop();
    while (qeven[j].size()) ans += qeven[j].front() / 2, qeven[j].pop();
  }
  cout << ans << endl;
}

