            int rest = smallsz - bigsz;
            ans += min(rest / 2, maxmatch);
        }
        else{
            int maxmatch = 0;
            for(int j=0; j<bigsz; j++){
                int cnt = 1, cur = modM[big][j];
                while(j + 1 < bigsz && cur == modM[big][j+1]){
                    j++;
                    cnt++;
                }
                maxmatch += cnt / 2;
            }

            ans += smallsz;

            int rest = bigsz - smallsz;
            ans += min(rest / 2, maxmatch);
        }
    }

    cout << ans << endl;

    return 0;
}

