  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  int N, M;
  cin>>N>>M;
  vector<int> X(N);
  cin>>X;

  map<int, int> cnt[M];
  for(int x:X) cnt[x%M][x]++;

  auto calc = [&](int a, int b){
    if(a == b){
      int sum = 0;
      for(auto p:cnt[a]) sum += p.second;
      return sum / 2;
    }

    int res = 0;    
    deque<P> A, B;
    for(auto p:cnt[a]) A.emplace_back(p.second, p.first);
    for(auto p:cnt[b]) B.emplace_back(p.second, p.first);
    sort(A.begin(), A.end(), [](auto &p, auto &q){
	return p.first%2 > q.first%2;
      });

    sort(B.begin(), B.end(), [](auto &p, auto &q){
	return p.first%2 > q.first%2;
      });

    while(1){
      if(A[0].first == 0) A.pop_front();
      if(B[0].first == 0) B.pop_front();
      if(A.empty() || B.empty()) break;
      if(A[0].first % 2 == 0 || B[0].first % 2 == 0) break;
      res++;
      A[0].first--;
      B[0].first--;
      A.push_back(A[0]), A.pop_front();
      B.push_back(B[0]), B.pop_front();
    }

    while(!A.empty()) res += A[0].first / 2, A.pop_front();
    while(!B.empty()) res += B[0].first / 2, B.pop_front();
    return res;
  };

  int ans = 0;
  for(int i=0;i<M;i++){
    int a = i;
    int b = (M - i) % M;
    if(a <= b) ans += calc(a, b);
  }

  cout<<ans<<endl;

  return 0;
}

