    if(a[i].size() < a[m - i].size()) swap(a[i], a[m - i]);
    int s = a[i].size();
    for(int j = 0; j < a[i].size(); j++){
      if(s <= a[m - i].size()) break;
      if(j+1 < a[i].size() && a[j] == a[j+1]){
        ans++;
        j++;
        s -= 2;
      }
    }
    ans += min(s, (int)a[m - i].size());
  }
  cout << ans << endl;

  return 0;
}

