int main() {
	cin >> N >> M;
	X.resize(N);
	mod.resize(M,0);
	for (int n = 0; n < N; n++) {
		cin >> X[n];
		mod[X[n] % M]++;
	}
	sort(X.begin(), X.end());
	mods.resize(M);
	pii cur = pii(1,X[0]);
	for (int n = 1; n < N; n++) {
		if (X[n] == X[n - 1])cur.first++;
		else {
			mods[X[n - 1] % M].push_back(cur);
			cur = pii(1,X[n]);
		}
	}
	mods[X[N - 1] % M].push_back(cur);
	for (int m = 0; m < M; m++) {
		sort(mods[m].begin(), mods[m].end());
	}
	long long ans = 0;
	for (int i = 0; i < M; i++) {
		int j = (M - i) % M;
		if (i > j)continue;
		//自分自身とマッチング
		if (i == j)ans += mod[i] / 2;
		else {
			ans += min(mod[i], mod[j]);
			if (mod[i] > mod[j]) {
				int left = mod[j];
				for (int l = 0; l < mods[i].size(); l++) {
					int d = min(mods[i][l].first, left);   //減らす分
					mods[i][l].first -= d;
					left -= d;
					if (left == 0)break;
				}
				for (int l = 0; l < mods[i].size(); l++)ans += mods[i][l].first / 2;
			}
			else if (mod[i] < mod[j]) {
				int left = mod[i];
				for (int l = 0; l < mods[j].size(); l++) {
					int d = min(mods[j][l].first, left);   //減らす分
					mods[j][l].first -= d;
					left -= d;
					if (left == 0)break;
				}
				for (int l = 0; l < mods[j].size(); l++)ans += mods[j][l].first / 2;

			}
		}
	} 
	cout << ans << endl;
	return 0;
}

