int calc(int a, int b, int c, int d){
  int e = min(a,c);
  a -= e;
  c -= e;
  b *= 2;
  d *= 2;
  if(a != 0){
    int x = min(a,d);
    e += x;
    a -= x;
    d -= x;
  }
  else if(c != 0){
    int x = min(c,b);
    e += x;
    c -= x;
    b -= x;
  }
  e += b/2;
  e += d/2;
  return e;
}


