      // p[r]枚すべて使ってペアをつくる
      ans += p[r]/2;
      X -= p[r];
      p[r2] += X-(X%2);
      m[r2] += X % 2;
    }
  }
  rep(i, M)
    ans += p[i] / 2;
  rep(i, M) {
    if (i != (M-i)%M)
      ans += min(m[i], m[(M-i)%M]);
    else
      ans += m[i] / 2;
    m[i] = 0;
  }
  cout << ans << endl;

  return 0;
}

