using namespace std;

#define MAX 100010
int N,M,X[MAX],used_counter[MAX], mod_counter[MAX];
set<int> freq_set[MAX];

// TODO :: 1 のときバグらないかチェック
void compute() {
  map<int,int> freq;
  rep(i,N) {
    ++mod_counter[X[i]%M];
    freq_set[X[i]%M].insert(X[i]);
    ++freq[X[i]];
  }
  map<int,bool> is_odd;
  rep(i,N) {
    if( freq[X[i]] % 2 == 1 ) is_odd[X[i]] = true;
    else                      is_odd[X[i]] = false;
  }
  int answer = 0;
  rep(i,(int)(M/2)+1) {
    if( i == 0 ) {
      answer += (int)(mod_counter[i]/2);
      continue;
    }
    int half = M - i;
    if( half == i ) {
      int use = (int)(mod_counter[i]/2);
      used_counter[half] += use * 2;
      answer             += use;
      //cout << half << " :MID: use = " << use << endl;
    } else {
      int use = min(mod_counter[half],mod_counter[i]);
      used_counter[half] += use;
      used_counter[i]    += use;
      answer             += use;
      //cout << half << " :half: use = " << use << endl;
      //cout << i    << " :i   : use = " << use << endl;
    }
    //puts("");
  }
  //cout << "中間発表 :: " << answer << endl;
  REP(i,1,M) {
    if( used_counter[i] == 0 ) continue;
    int remain = used_counter[i];
    for(set<int>::iterator it=freq_set[i].begin();it!=freq_set[i].end();++it) {
      if( remain <= 0 ) break;
      int v = *it;
      if( is_odd[v] ) {
	--remain;
	--freq[v];
      }
    }  
    for(set<int>::iterator it=freq_set[i].begin();it!=freq_set[i].end();++it) {
      int v = *it;
      int cnt = freq[v];
      if( remain ) {
	int sub = min(remain,cnt);
	cnt -= sub;
	remain -= sub;
      }
      answer += (int)(cnt/2);
    }
    assert(remain == 0);
  }
  cout << answer << endl;
}

int main(){
  cin >> N >> M;
  rep(i,N) cin >> X[i];
  compute();
  return 0;
}

