void solve(void)
{
  int n,m;
  cin>>n>>m;
  map<int,int> mp1,mp2;
  for (int i = 0; i < n; i++)
  {
    int x;cin>>x;
    mp1[x] ++ ;
    mp2[x%m]++;
  }
  int res = 0;
  for (auto &&x : mp1)
  {
    if(x.second > 2)
    {
      res += x.second/2;
      mp2[x.first%m] -= x.second/2*2;
    }
  }
  for (auto &&x : mp2)
  {
    int y = mp2[m - x.first];
    int a = min(y,x.second);
    x.second -= a;
    mp2[m-x.first] -= a;
    res += a;
  }
  cout<<res<<endl;





  return;
}


