class Unionfind
{
    vector<int> p;

public:
    int find(int x);
    void unite(int x, int y);
    Unionfind(int n);
};

Unionfind::Unionfind(int n)
{
    for (int i = 0; i < n; i++)
    {
        p.push_back(i);
    }
}
int Unionfind::find(int x)
{
    while (p[x] != x)
    {
        p[x] = p[p[x]];
        x = p[x];
    }
    return x;
}

void Unionfind::unite(int x, int y)
{
    x = Unionfind::find(x);
    y = Unionfind::find(y);
    if (x != y)
    {
        p[x] = y;
    }
}

void getpair(int &ans, const int m, vector<int> &v)
{
    int a;
    rep(i, m)
    {
        if (i == 0)
        {
            ans += v[i] / 2;
            v[i] = v[i] % 2;
        }
        else if (m % 2 == 0 && i == m / 2)
        {
            ans += v[i] / 2;
            v[i] = v[i] % 2;
        }
        else
        {
            a = min(v[i], v[m - i]);
            ans += a;
            v[i] -= a;
            v[m - i] -= a;
        }
    }
}

