set<int> a[100005];

void f(int s) {
    int sum = 0;
    for(auto itr = a[s].begin(); itr != a[s].end(); ++itr) {
      sum += num[*itr];
    }
    ans += sum / 2;
}

int main() {
  int n,m;
  cin >> n >> m;
  for(int i = 0; i < n; i++) {
    int x;
    cin >> x;
    a[x % m].insert(x);
    num[x]++;
  }

  int l = 1;
  int r = m-1;

  while(l < r) {
    //   cout << l <<"  "<<r<<endl;
    int lsum = 0;
    int X = 0;
    int Y;
    for(auto itr = a[l].begin(); itr != a[l].end(); ++itr) {
      lsum += num[*itr];
      X += num[*itr] / 2;
    }
    Y = lsum - 2 * X;
    int rsum = 0;
    int XX = 0;
    int YY;
    for(auto itr = a[r].begin(); itr != a[r].end(); ++itr) {
      rsum += num[*itr];
      XX += num[*itr] / 2;
    }
    YY = rsum - 2 * XX;
    //  cout << lsum <<"  "<<rsum << endl;
    if(rsum < lsum) {
      int L = 0;
      int R = X + 1;
      while(R - L > 1) {
	int mid = (L + R) / 2;
	if(2*X + Y >= lsum - rsum) R = mid;
	else L = mid;
      }
      ans += rsum;
      ans += X - L;
    }
    else {
      int L = 0;
      int R = XX + 1;
      while(R - L > 1) {
	int mid = (L + R) / 2;
	if(2*XX + YY >= rsum - lsum) R = mid;
	else L = mid;
      }
      ans += lsum;
      ans += XX - L;
    }
    l++;
    r--;
    //   cout << "ans = "<<ans << endl;
  }
  if(l == r) {
    f(m/2);
  }
  f(0);

  cout << ans << endl;

}

