                if (us[a[i]]) {
                        db[a[i] % m] += (us[a[i]] - (us[a[i]] % 2));
                        sn[a[i] % m] += us[a[i]] % 2;
                        us[a[i]] = 0;
                }
        }
        for (int i = 1; i < (m + 1) / 2; i ++) {
                int f = u[i];
                int s = u[m - i];
                if (f < s) {
                        ans += f;
                        int p = min(0,sn[m - i] - f);
                        db[m - i] += p;
                        ans += (db[m - i] / 2);
                }
                else {
                        ans += s;
                        int p = min(0,sn[i] - s);
                        db[i] += p;
                        ans += (db[i] / 2);
                }
        }
        if (m % 2 == 0) {
                ans += (u[m / 2] / 2);
        }
        ans += (u[0] / 2);

        cout << ans << endl;
}

