template<typename T>
vector<pair<T, int>> RUN_LENGTH(const vector<T> &v) {
    vector<pair<T, int>> ret;
    int len = v.size();
    for (int i = 0, j = 0; i < len; i = j) {
        while (j < len && v[i] == v[j]) j++;
        ret.push_back(make_pair(v[i], j - i));
    }
    return ret;
}

pair<vector<int>, vector<int>> f(vector<pair<int, int>> v) {
    vector<int> odd, even;
    for (int i = 0; i < v.size(); i++) {
        if (v[i].second % 2 == 0) even.push_back(v[i].second);
        else odd.push_back(v[i].second);
    }
    return make_pair(odd, even);
}

