				a[z].erase(a[z].begin());
				cnt[x]--;
				cnt[v]--;
				continue;
			}
			while(!b[z].empty())
			{
				int v = b[z].back();
				b[z].pop_back();
				if (v != x && cnt[v] != 0)
				{
					if (cnt[v] & 1) throw;
					a[z].insert(v);
					cnt[x]--;
					cnt[v]--;
					b[y].push_back(x);
					x = -1;
					break;
				}
			}
			if (x != -1)
			{
				a[y].insert(x);
				break;
			}
		}
	}
	int ans = n;
	for (int i = 0; i < m; i++)
		ans -= (int)a[i].size();
	if (ans & 1) throw;
	printf("%d\n", ans / 2);

	return 0;
}

