int main(){
    int N,M;cin>>N>>M;
    vector<int> X(N);
    REP(i, N) cin >> X[i];
    vector<int> cnt(M);
    REP(i,N) cnt[X[i]%M]++;
    sort(All(X),[&](int x,int y){if(x==y) return x<y;return x%M<y%M;});
    int ans=0;
    REP(i,N){
        if(X[i]%M>=(M+1)/2||X[i]%M==0) continue;
        if(i+1<N&&X[i+1]==X[i]){
            if(cnt[(M-X[i]%M)%M]){
                if(i+2<N&&X[i+2]%M==X[i]%M){
                    ans++;
                    cnt[X[i]%M]-=2;
                    ++i;
                }
                else{
                    ans++;
                    cnt[X[i]%M]--;
                    cnt[(M-X[i]%M)%M]--;
                }
            }
            else{
                ans++;
                cnt[X[i]%M]-=2;
                ++i;
            }
        }
        else if(cnt[(M-X[i]%M)%M]){
            ans++;
            cnt[X[i]%M]--;
            cnt[(M-X[i]%M)%M]--;
        }
    }
    ans+=cnt[0]/2;
    if(M%2==0) ans+=cnt[M/2]/2;
    cout<<ans<<endl;
}

