int calc(int a, int b) {
  if (X[a].size() > X[b].size()) {
    swap(a, b);
  }
  int res = X[a].size();
  int rem = X[b].size() - X[a].size();
  int pr = 0;
  for (int i = 0; i + 1 < X[b].size(); ++i) {
    if (X[b][i] == X[b][i + 1]) {
      ++pr;
      ++i;
    }
  }
  return res + min(rem, pr);
}

