    for (int j = 0; j < N; ++j) {
        int v;
        cin >> v;
        X[v] ++;
    }

    int ret = 0;

    int count_0 = 0;
    for (int k = 0; k <= 100000; k += M) {
        count_0 += X[k];
    }
    ret += count_0 / 2;
    int rest = count_0 / 2;
    for (int k = 0; k <= 100000 && rest > 0; k += M) {
        if (X[k] % 2 == 1) {
            --X[k];
            --rest;
        }
    }
    for (int k = 0; k <= 100000 && rest > 0; k += M) {
        int dec = min(X[k], rest);
        X[k] -= dec;
        rest -= dec;
    }
    for (int j = 1; j <= M/2; ++j) {
        int rj = M - j;


        int count_j = 0;
        for (int k = j; k <= 100000; k += M) {
            count_j += X[k];
        }

        int count_rj = 0;
        for (int k = rj; k <= 100000; k += M) {
            count_rj += X[k];
        }


        int inc = min(count_j, count_rj);
        if (j == rj) {
            ret += inc / 2;
        } else {
            ret += inc;
        }
        int rest = inc;
        for (int k = j; k <= 100000 && rest > 0; k += M) {
            if (X[k] % 2 == 1) {
                --X[k];
                --rest;
            }
        }
        for (int k = j; k <= 100000 && rest > 0; k += M) {
            int dec = min(X[k], rest);
            X[k] -= dec;
            rest -= dec;
        }
        rest = inc;
        if (j != rj) {
            for (int k = rj; k <= 100000 && rest > 0; k += M) {
                if (X[k] % 2 == 1) {
                    --X[k];
                    --rest;
                }
            }
            for (int k = j; k <= 100000 && rest > 0; k += M) {
                int dec = min(X[k], rest);
                X[k] -= dec;
                rest -= dec;
            }
        }
    }

