int main(void) {
    int N, M, x;
    cin >> N >> M;
    map<int, int> cnt, paired;
    REP(i, N) {
        cin >> x;
        cnt[x] += 1;
    }
    int biggest = cnt.rbegin()->first;
    int ans=0;

    // 同じ数のペア
    for(auto it = cnt.begin(); it != cnt.end(); ++it) {
        paired[it->first] = it->second / 2;
        ans += paired[it->first];
        cnt[it->first] = it->second % 2;
    }
    // 余りもの同士
    for(auto it = cnt.begin(); it != cnt.end(); ++it) {
        if(it->second % 2 == 1) {
            int t = it->first;
            for(auto it2 = next(it); it2 != cnt.end(); ++it2) {
                if(it2->second > 0 && (t + it2->first)%M == 0) {
                    ans++;
                    cnt[t] -= 1;
                    cnt[it2->first] -= 1;
                }
            }
        }
    }
    // ペアの解体
    for(auto it = cnt.begin(); it != cnt.end(); ++it) {
        if(it->second % 2 == 1) {
            int t = it->first;
            for(auto it2 = next(it); it2 != cnt.end(); ++it2) {
                if(it2->second > 0 && (it2->first - t)%M == 0) {
                    int t2 = it2->first;
                    for(auto it3 = cnt.begin(); it3 != cnt.end(); ++it3) {
                        int t3 = it3->first;
                        if((t3 + t) % M == 0 && paired[t3] > 0) {
                            cnt[t2]--;
                            cnt[t]--;
                            ans += 1;
                            paired[t3] -= 1;
                            break;
                        }
                    }
                    break;
                }
            }
        }
    }
    cout << ans << endl;
}

