template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<ll> X(N); for(auto& in:X) cin >> in;
    map<ll,ll> Xcnt;
    for(auto& v:X) Xcnt[v]++;

    map<ll,ll> SameGroup;
    for(auto& v:X) SameGroup[v%M]++;
    map<ll,ll> PairCnt;
    for(auto& p:Xcnt) PairCnt[p.first%M] += p.second/2;

    ll T1 = 0; // 重複しない個数
    ll T2 = 0; // 重複する個数
    for(ll x = 0; x < M; x++){
        ll y = M-x;
        if(x == 0 || x == y){ // この場合はどんな組み合わせでも条件を満たす
            T1 += SameGroup[x]/2;
            continue;
        }

        ll s1 = SameGroup[x], s2 = SameGroup[y];
        ll p1 = PairCnt[x],p2 = PairCnt[y];

        ll add_T2 = 0;
        for(ll p = 0; p <= p1; p++){
            ll T = 0;
            // p1のうちp個のペアを使う
            T += p;

            // s1 - p*2 個をs2とのペア候補
            ll left_x = s1 - p*2;

            // y側は
            // ペアが最大p2個、 s2 - p2*2個が余り
            ll left_y = s2 - p2*2;


            ll min_left = min(left_x,left_y);
            T += min_left;

            left_x -= min_left;
            left_y -= min_left;

            if(left_x == 0){ // xの残りがなくなるようであれば
                T += p2; // p2は全て選ぶ
            }else{ // xのまだ残っているようであれば
                // left_x と p2の個数を見て

                // left_xのうち何個をp2*2の個数からペアにすれば最大となるのかを計算
                // よくよく考えると
                // left_xとペアにできる分だけペアにした方がいい
                // p2の1ペアで left_xを使えば最大2ペアできる為

                ll p_left_p2 = min(left_x,p2*2);
                T += p_left_p2;

                // 後は、残ったp2の個数を加算
                T += (p2*2 - p_left_p2)/2;
            }


            add_T2 = max(add_T2,T);
        }

        T2 += add_T2;
    }

    res = T1 + T2/2;
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    // solve(0);
    cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

