        cnts[a]++;
    }
    int ans = 0;
    for (int q = 0; q < m; ++q) {
        if ((q + q) % m == 0) {
            int cnt = 0;
            for (int j = 0; j * m + q <= 1e5; ++j) {
                cnt += cnts[j];
            }
            ans += cnt / 2;
            continue;
        }
        int l = 0;
        int r = 0;
        int left_l = 0;
        int left_r = 0;
        for (int j = 0; j * m + q <= 1e5; ++j) {
            l += cnts[j * m + q] / 2;
            left_l += cnts[j * m + q] % 2;
            cnts[j * m + q] = 0;
        }
        q = m - q;
        for (int j = 0; j * m + q <= 1e5; ++j) {
            r += cnts[j * m + q] / 2;
            left_r += cnts[j * m + q] % 2;
            cnts[j * m + q] = 0;
        }
        q = m - q;
        ans += l + r;
        int hoge = min(left_l, left_r);
        ans += hoge;
        left_l -= hoge;
        left_r -= hoge;
        if (left_l > 0) {
            int hoge = min(left_l, r * 2);
            ans += hoge / 2;
        }
        else {
            int hoge = min(left_r, l * 2);
            ans += hoge / 2;
        }
    }
    ans /= 2;
    cout << ans << endl;
}

