#define N 100010
int arr[ N ] , removes[ N ] , hashe[ N ];
multiset < pair < int , int > > hasheset[ N ] ;

int main() 
{
	int n , x , m ;
	cin >> n >> m ;

	for( int i = 0 ; i < n ; i++ ) {
		cin >> x ;
		arr[ x%m ]++ ;
		hashe[ x ]++;
	}

	int ans = ( arr[0] )/2 ;
	for( int i = 0 ; i < N ; i++ ) {
		if( hashe[ i ] ) 
			hasheset[ i%m ].insert( make_pair( 1 - hashe[i]%2 , hashe[ i ] ) );
	}

	for( int i = 1 , j = m - 1 ; i <= j ; i++,j-- ) {

		if( i == j ) {
			ans += arr[ i ]/2;
			arr[ i ] = 0 ;
			continue ;
		}
		int y = min( arr[ i ] , arr[ j ] );
		arr[ i ] -= y ;
		arr[ j ] -= y ;
		removes[ i ] = y ;
		removes[ j ] = y ; 
		ans += y ;
	}

	//cout << ans << endl ;

	//cout << 
	for( int i = 1 ; i < m ; i++ ) {
		if( arr[ i ] == 0 )
			continue ;

		while( removes[ i ] ) {
			pair < int , int > element = *hasheset[ i ].begin() ;
			hasheset[ i ].erase( hasheset[ i ].begin() );

			if( element.second == 0 ) continue ;
			removes[ i ]-- ;
			element.second-- ;
			element.first = 1 - element.first ;
			hasheset[ i ].insert( element );
		}

		for( multiset < pair < int , int > > :: iterator it = hasheset[ i ].begin() ; it != hasheset[ i ].end() ; it++ )
		{
			//cout << it -> second << " " << i << endl ;
