    vector<int> X(N);
    rep(i,N) cin >> X[i];

    vector<int> A(100001);
    rep(i,N) A[X[i]]++;
    vector<ll> B(M),C(M);
    rep(i,100001) {
        B[i%M] += A[i];
        C[i%M] += A[i]/2;
    }

    ll ans = 0;
    for (int i = 1; i <= M/2; i++) {
        if (M%2==0 && i == M/2) {
            ans += B[M/2]/2LL;
        } else {
            if (B[i] >= B[M-i]) {
                ans += B[M-i];
                B[i] -= B[M-i];
                ans += min(B[i]/2LL,C[i]);
            } else {
                ans += B[i];
                B[M-i] -= B[i];
                ans += min(B[M-i]/2LL,C[i]);
            }
        }
    }
    ans += B[0]/2LL;

    cout << ans << endl;
