void solve() {
	int N, M; cin >> N >> M;
	vector<int> X(N); for (auto& a : X) cin >> a;
	vector<int> MX(M);
	REP(i, N) {
		MX[X[i] % M]++;
	}
	unordered_map<int, int> cnt;
	for (auto& a : X) {
		cnt[a]++;
	}
	vector<int> tsugai(M);
	for (auto& a : cnt) {
		size_t index = (a.first % M);
		tsugai[index] += a.second - (a.second % 2);
	}

	int res = 0;

	int ma = MX.size() / 2 + (MX.size() % 2);
	FOR(i, 1, ma) {
		int j = M - i;
		int num = min(MX[i], MX[j]);
		MX[i] -= num;
		MX[j] -= num;
		res += num;
	}
	int num = MX[0] / 2;
	res += num;
	MX[0] -= num * 2;

	if(MX.size() % 2 == 0){
		int tar = MX.size() / 2;
		int num = MX[tar]/2;
		res += num;
		MX[tar] -= num * 2;
	}

	REP(i, MX.size()) {
		res += min(MX[i], tsugai[i]) / 2;
	}

	cout << res << endl;
}

