	for(int i = 1; i < (M+1)/2; i++){
		if(sum[i] <= sum[M-i]){
			rem += max(odd[M-i] - sum[i], 0); 
			if(odd[M-i] % 2 != sum[i] % 2) rem ++;  
		}
		else{
			rem += max(odd[i] - sum[M-i], 0); 
			if(odd[i] % 2 != sum[M-i] % 2) rem ++;  
		}
	}
	cout << (N - rem) / 2 << endl; 
}

