    for(set<int>::iterator it=freq_set[i].begin();it!=freq_set[i].end();++it) {
      int v = *it;
      int cnt = freq[v];
      if( remain ) {
	assert( cnt % 2 == 0 );
	int sub = min(remain,cnt);
	cnt    -= sub;
	remain -= sub;
      }
      assert( cnt >= 0 );
      answer += (int)(cnt/2);
    }
    assert(remain == 0);
  }
assert( answer >= 0);
  cout << answer << endl;
}

