void solv() {
	int m;
	cin >> n >> m;
	int p[100010];
	memset(p, 0, sizeof(p));
	for (size_t i = 0; i < n; i++)
	{
		int a;
		cin >> a;
		p[a]++;
	}
	priority_queue<pll,vector<pll>,greater<pll>> mo[100010];
	memset(mo, 0, sizeof(mo));
	priority_queue<int,vector<int>,greater<int>> ods;
	for (int i = 0; i < 100010; i++)
	{
		if (p[i] == 0) continue;
		int od = p[i] % 2;
		mo[i % m].push(make_pair(od ? 0 : 1, i));
		if (od) ods.push(i);
	}

	ll res = 0;
	while (!ods.empty())
	{
		int v = ods.top();
		ods.pop();
		if (p[v] % 2 == 0)continue;
		int rm = m - (v % m);
		if (rm == m) rm = 0;
		pii sel;
		sel.first = -1;
		while (!mo[rm].empty())
		{
			auto mp = mo[rm].top();
			mo[rm].pop();
			if (p[mp.second] == 0) continue; //既に処理されている
			if (mp.first != ((p[mp.second] % 2) ? 0 : 1)) {
				mp.first = ((p[mp.second] % 2) ? 0 : 1);
				mo[rm].push(mp);
				continue;
			}

			if (mp.second == v) {
				sel = mp;
				continue;
			}
			if (p[mp.second] > 1) {
				mp.first++; mp.first %= 2;
				mo[rm].push(mp);
				if (mp.first % 2 == 0)
					ods.push(mp.second);
			}
			p[mp.second]--;
			res++;
			break;
		}

		p[v]--;

		if (sel.first != -1 && p[v] > 0) {
			sel.first = (p[v] % 2) ? 0 : 1;
			mo[sel.second % m].push(sel);
		}
	}

	for (int i = 0; i < 100010; i++)
	{
		res += p[i] / 2;
	}
	cout << res << endl;
}


