	cin >> N >> M;
	vector<int> X(N);
	REP(i,N){
	    cin >> X[i];
	}

	sort(ALL(X));

	vector<int> pairnum(M);
	vector<int> count(M);

	int index = 0;
	REP(i,100001){
		int nownum = 0;
		int m = i % M;

		while(1){
			if (index >= N) break;
			if (X[index] == i){
				nownum++;
				index++;
				continue;
			}else{
				break;
			}
		}

		count[m] += nownum;
		pairnum[m] += nownum / 2;

	}

	ll ans = 0;

	ans += count[0] / 2;
	count[0] = count[0] % 2;

	if (M % 2 == 0){
		ans += count[M/2] / 2;
		count[M/2] = count[M/2] % 2;
	}

	FORq(i,1,M/2){
		if ((M % 2 == 0) and (i == M / 2)) break;
		//cout << "i = " << i << ", " << count[i] << ", " << count[M-i] << "\n";
		int pairmin = min(count[i],count[M-i]);
		ans += pairmin;
		count[i] -= pairmin;
		count[M-i] -= pairmin;
	}

	REP(i,M){
	    ans += min(count[i] , pairnum[i] * 2) / 2;
	}


