struct Bipartite_Matching
{
  vector< vector< int > > graph;
  vector< int > match;
  vector< bool > used;

  Bipartite_Matching(int n)
  {
    graph.resize(n);
  }

  void add_edge(int u, int v)
  {
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  bool dfs(int v)
  {
    used[v] = true;
    for(int i = 0; i < graph[v].size(); i++) {
      int u = graph[v][i], w = match[u];
      if(w == -1 || (!used[w] && dfs(w))) {
        match[v] = u;
        match[u] = v;
        return (true);
      }
    }
    return (false);
  }

  int bipartite_matching()
  {
    int ret = 0;
    match.assign(graph.size(), -1);
    for(int i = 0; i < graph.size(); i++) {
      if(match[i] == -1) {
        used.assign(graph.size(), false);
        ret += dfs(i);
      }
    }
    return (ret);
  }
};

int main()
{
  int N, M;
  int xs[100001] = {};
  cin >> N >> M;

  int ret = 0;
  for(int i = 0; i < N; i++) {
    int X;
    cin >> X;
    X %= M;
    xs[X]++;
  }

  for(int i = 0; i < M; i++) {
    if(i == M - i) {
      while(xs[i] - 2 >= 0) {
        xs[i] -= 2;
        ++ret;
      }
      continue;
    }
    while(xs[i] > 0 && xs[M - i] > 0) {
      ++ret;
      --xs[i];
      --xs[M - i];
    }
    while(xs[i] - 2 >= 0) {
      xs[i] -= 2;
      ++ret;
    }
  }
  cout << ret << endl;
}

constexpr int MAX_SIZE = 1e5 + 1;
std::vector<int> A;
std::vector<int> Count(MAX_SIZE, 0);


int main(void){
    int n, m; scanf("%d%d", &n, &m);
    A.resize(m, 0);
    REP(i, n) {
        int a; scanf("%d", &a);
        A[a % m]++;
        Count[a]++;
    }
    REP(x, MAX_SIZE) A[x % m] += (Count[x] >> 1);
    // x個あって, aペア作れる <~> y個あって, bペア作れる

    int cnt = 0;
    REP(i, m){
        int j = (m - i) % m;
        if(j < i) break;
        if(i == j) {cnt += Count[i]; continue;}
        int p = std::min(A[i], A[j]);
        cnt += p; A[i] -= p; A[j] -= p;
        int q1 = std::min(A[i] / 2, Count[i]);
        int q2 = std::min(A[j] / 2, Count[j]);
        cnt += q1 + q2;
    }
    printf("%d\n", cnt);


    return 0;
}

