void Main() {
    ll N, M;
    cin >> N >> M;
    vector<ll> X(N);
    rep(i, N) cin >> X[i];
    map<ll, vector<ll>> cnt;
    rep(i, N) {
        cnt[X[i] % M].push_back(X[i]);
    }
    ll ans = 0;
    set<ll> used;
    for (auto p : cnt) {
        if (used.count(p.first)) continue;
        used.insert(p.first);
        used.insert(M - p.first);
        vector<ll> S = p.second;
        vector<ll> T = cnt[M - p.first];
        if (p.first == 0) {
            ans += S.size() / 2;
            continue;
        }
        if (M % 2 == 0 && p.first == M / 2) {
            ans += S.size() / 2;
            continue;
        }
        if (T.empty()) continue;
        if (S.size() >= T.size()) swap(S, T);
        ll over = T.size() - S.size();
        if (over <= 1) {
            ans += S.size();
        } else {
            ans += S.size();
            map<ll, ll> C;
            for (ll t : T) {
                C[t]--;
            }
            for (P c : C) {
                if (c.second <= -2) {
                    ll tmp = -c.second;
                    while (over - 2 >= 0 && tmp - 2 >= 0) {
                        over -= 2;
                        tmp -= 2;
                        ans++;
                    }
                }
            }
        }
    }
    cout << ans << '\n';
}

