    cin >> x[i];
    mp[x[i]%m][x[i]]++;
    cnt[x[i]%m]++;
  }
  for(int i=0;i<=m/2;i++){
    if(i!=0&&!(m%2==0&&i==m/2)){
      tmp0 = cnt[i];
      tmp1 = cnt[m-i];
      if(tmp0<tmp1){
        val = tmp0;
        t_mp = mp[m-i];
        lv = tmp1-tmp0;
      }else{
        val = tmp1;
        t_mp = mp[i];
        lv = tmp0-tmp1;
