      for(auto j:t_mp){
        if(lv<2){
          break;
        }
        if(j.second>=2){
          tmp = min(j.second,lv);
          val += tmp/2;
          lv -= (tmp/2)*2;
        }
      }
      ans += val;
//      cout << i<<" "<<val<<endl;
    }else{
      ans += cnt[i]/2;
    }
  }
  cout << ans <<endl;
}

