int freq[100005], rem[100005];
vector<int> nums[100005];

int main(){

    cin.sync_with_stdio(0); cin.tie(0); cout.tie(0);

    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int n, m, a; cin >> n >> m;

    // greedy match between the two

    for(int i = 0; i < n; ++i){
        cin >> a;
        if(freq[a] == 0){
            nums[a % m].push_back(a);
        }
        ++freq[a]; ++rem[a % m];
    }

    long long tot = 0;

    if(m % 2 == 0)
        tot = rem[0] + rem[m >> 1] >> 1;
    else
        tot = rem[0] >> 1;

    for(int i = 1; i + i < m; ++i){
        int a = i, b = m - i;
        if(rem[a] < rem[b]){
            int sw = a;
            a = b; b = sw;
        }
        for(int j : nums[a]){
            if(rem[a] - 2 < rem[b]) break;
            while(rem[a] - 2 >= rem[b] && freq[j] > 1){
                freq[j] -= 2;
                ++tot;
                rem[a] -= 2;
            }
        }
        tot += min(rem[a], rem[b]);
    }

    cout << tot << "\n";

    return 0;

}

