constexpr int X_MAX = 100'000;

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int N, M;
	scanf( "%d%d!", &N, &M );

	VI X( N );
	for_each( ALL( X ), [=]( int &x ){ scanf( "%d", &x ); } );

	VI counts( X_MAX + 1 );
	for_each( ALL( X ), [&]( const int &x ){ ++counts[x]; } );

	int res = 0;
	VI pairs( M ), singles( M );
	REP( i, 1, X_MAX + 1 )
	{
		REP( counts[i] / 2 )
		{
			++res;
			++pairs[ i % M ];
		}
		if ( counts[i] % 2 )
		{
			++singles[ i % M ];
		}
	}

	res += singles[0] / 2;
	REP( i, 1, M )
	{
		const int a = singles[i] / 2;
		const int b = pairs[ M - i ];
		const int r = min( a, b );
		res += r;
		singles[i] -= r * 2;
	}
	REP( i, 1, M )
	{
		if ( i * 2 == M )
		{
			continue;
		}

		const int a = singles[i];
		const int b = singles[ M - i ];
		const int r = min( a, b );
		res += r;
		singles[i] -= r;
		singles[ M - i ] -= r;
	}

	printf( "%d\n", res );
