        cin >> x.at(i);
    }

    sort(x.begin(), x.end());
    vector<vector<int>> modM(m);
    vector<int> cnt(m);
    int tmp = 0;
    for (int i=0; i<n; ++i) {
        if (i > 0 && x.at(i) != x.at(i-1)) {
            modM.at(x.at(i-1)%m).push_back(tmp);
            cnt.at(x.at(i-1)%m) += tmp;
            tmp = 1;
        } else {
            ++tmp;
        }
    }
