        //data[i]には a%M の数が最初いくつ存在したかが入っている
        //data[i]とcnt[i]を比較して使用した数を割り出せる
        int now = x.first;
        int nown= x.second;
        //cout << "now = " << now << " nown = " << nown << " now left num = " << cnt[now%M] << endl;
        if(cnt[now%M]>=2 && nown >=2){
            int t = min(cnt[now%M]/2,nown/2);
            ans += t;
            cnt[now%M]-=t;
        }
    }

    cout << ans << endl;
}

