int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n, m;
    cin >> n >> m;

    vector<int> x(n);
    map<int, int> cnt;
    rep(i, m + 1){
        cnt[i] = 0;
    }
    rep(i, n){
        cin >> x[i];
        ++cnt[x[i] % m];
    }

    map<int, int> mp;
    rep(i, n - 1){
        int p = x[i] % m;
        if(p == 0){
            continue;
        }else if(x[i] == x[i + 1]){
            ++mp[p];
            ++i;
        }
    }

    int ans = 0;
    for(auto x : cnt){
        if(x.first > m / 2){
            break;
        }
        if(x.first == 0 || (m % 2 == 0 && x.first == m / 2)){
            ans += x.second / 2;
        }else{
            auto it = cnt.lower_bound(m - x.first);
            ans += min(x.second, (*it).second);
            int tmp;
            if(x.second < (*it).second){
                tmp = (*it).second - x.second;
                ans += min(tmp / 2, mp[(*it).first]);
            }else if(x.second > (*it).second){
                tmp = x.second - (*it).second;
                ans += min(tmp / 2, mp[x.first]);
            }
        }
    }

    cout << ans << endl;

    return 0;
}

