    for (int i = 0; i < n; i++) cin >> a[i], cnt[a[i] % m]++, amount[a[i]]++, nums[a[i] % m].push_back(a[i]);
    int ans = 0;
    for (int i = 0; i <= m - i; i++)
    {
        if (i == (m - i) % m)
        {
            ans += cnt[i] / 2;
        }
        else
        {
            ans += min(cnt[i], cnt[m - i]);
            if (cnt[i] < cnt[m - i])
