            if (need <= 0)
            {
                for (int j = 0; j < nums[i].size(); j++) ans += amount[nums[i][j]] / 2, amount[nums[i][j]] = 0;
            }
            else
            {
                for (int j = 0; j < nums[i].size(); j++)
                {
                    while (need > 0 && amount[nums[i][j]] > 0)
                    {
                        need -= 2, amount[nums[i][j]] -= 2;
                    }
                    ans += amount[nums[i][j]] / 2, amount[nums[i][j]] = 0;
                }
            }
        }
