    { return Container< std::pair< Value, int > >{}; }
  auto pos = Container< int >{};
  for (auto i = 1; i < n; i++) {
    if (v.at(i - 1) != v.at(i))
      { pos.emplace_back(i); }
  }
  pos.emplace_back(n);
  auto m = (int)pos.size();
  auto len = Container< int >(m);
  std::adjacent_difference(pos.begin(), pos.end(), len.begin());
  auto ret = Container< std::pair< Value, int > >(m);
  for (auto i = 0; i != m; i++)
    { ret.at(i) = {v.at(pos.at(i) - 1), len.at(i)}; }
  return ret;
}

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n, m; std::cin >> n >> m;
  auto a = make_vector< 2, int >(m, 0);
  loop(n){
    int x; std::cin >> x;
    a.at(x % m).emplace_back(x);
  }
  for (auto & v : a) std::sort(all(v));
  auto b = std::vector< std::pair< int, int >>(m); // cnt, pairing
  rep(i, 0, m) {
    auto const & v = a.at(i);
    auto rle = runlength(v);
    auto pairing = std::accumulate(all(rle), 0, [](auto acc, auto p){
      return acc += p.second / 2;
    });
    b.at(i) = { v.size(), pairing };
  }
  auto cal = [&] (auto&& p, auto&& q) {
    int a, b, c, d;
    std::tie(a, b) = p;
    std::tie(c, d) = q;
    if (a > c) {
      std::swap(a, c);
      std::swap(b, d);
    }
    return a + std::min(c - a, d);
  };
  auto dal = [&] (auto&& p)
    { return p.first / 2; };
  auto ret = 0LL;
  rep(i, 0, m) {
    auto j = m - i;
    if (i > j) break;
    else if (i == 0 || i == j) ret += dal(b.at(i));
    else ret += cal(b.at(i), b.at(j));
  }
