	rep(i, 0, m / 2 + 1) {
		int k = (m - i) % m;
		int a = accumulate(num[i].begin(), num[i].end(), 0);
		int b = accumulate(num[k].begin(), num[k].end(), 0);
		if (i == k) {
			ans += a / 2;
			continue;
		}
		sort(num[i].begin(), num[i].end());
		sort(num[k].begin(), num[k].end());
		ans += min(a, b);
		if (a > b) {
			swap(num[i], num[k]);
