void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::map<int, int> tmp;
	for (auto _ : boost::irange(0, N))
	{
		int v;
		std::cin >> v;
		++tmp[v];
	}
	std::vector<int> sames(M);
	std::vector<int> ones(M);
	int count = 0;
	for (auto&& p : tmp)
	{
		int s, v;
		std::tie(v, s) = p;
		sames[v % M] += s / 2;
		count += s / 2;
		if (s % 2 == 1)
		{
			++ones[v % M];
		}
	}
	for (auto i : boost::irange(0, M))
	{
		auto rev = (M - i) % M;
		auto s = std::min(sames[rev], ones[i] / 2);
		count += s;
		ones[i] -= 2 * s;
		sames[rev] -= s;
	}
	for (auto i : boost::irange(0, M))
	{
		auto rev = (M - i) % M;
		if (i != rev)
		{
			auto s = std::min(ones[i], ones[rev]);
			count += s;
			ones[i] -= s;
			ones[rev] -= s;
		}
		else
		{
			count += ones[i] / 2;
		}
	}
	std::cout << count << std::endl;
}

