int modsum[100000];
int main(){
  cin >> N >> M;

  REP(i,N){
    cin >> X[i];
    v[ X[i] ]++;
  }
  REP(i, 100000){
    if( v[i] > 0 ){
      mod[ i % M ].emplace_back( v[i], i );
      modsum[ i % M ] += v[i];
    }
  }
  int ans = 0;
  ans += modsum[0] / 2;
  if( M % 2 == 0 ){
    ans += modsum[ M / 2 ] / 2;
  }
  for(int i = 1; i < M - i; i++ ){
    int j = M - i;
    ans += min( modsum[i] , modsum[j] );
    int d = abs( modsum[i] - modsum[j] );
    if( d == 0 ) continue;
    if( modsum[j] < modsum[i] ){
      // modsum[j] の方が大きくなるようにする
      j = i;
    }
    sort( mod[j].begin(), mod[j].end() );
    reverse( mod[j].begin(), mod[j].end() ); // 個数の多い順番に並べる．
    int e = 0;
    int k = 0;
    while( 1 ){
      if( e + mod[j][k].first < d ){
	ans += mod[j][k].first / 2;
	e += mod[j][k].first;
      }else{
	ans += (d - e) / 2;
	break;
      }
      k++;
    }
  }
  cout << ans << endl;
}

