const int N = 1234567;

int a[N], cnt[N], pairs[N], lonely[N];

int main() {
  int n, m;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < n; i++) {
    scanf("%d", a + i);
    cnt[a[i] % m]++;
    if (lonely[a[i]]) {
      pairs[a[i] % m]++;
    }
    lonely[a[i]] ^= 1;
  }
  int ans = 0;
  for (int r = 0; r < m; r++) {
    int other = (m - r) % m;
    if (other < r) {
      continue;
    }
    if (other == r) {
      ans += cnt[r] / 2;
      continue;
    }
    int x = r, y = other;
    if (cnt[x] < cnt[y]) {
      swap(x, y);
    }
    int overhead = cnt[x] - cnt[y];
    if (2 * pairs[x] >= overhead) {
      ans += (cnt[x] + cnt[y]) / 2;
    } else {
      ans += pairs[x] + cnt[y];
    }
  }
  cout << ans << endl;
  return 0;
}

