{
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; i++)
    {
        int x;
        scanf("%d", &x);
        kv[x]++;
    }
    for (auto t : kv) if (t.se % 2 == 1)
    {
        cnt[t.fi % m].pb(t.fi);
    }
    for (auto t : kv)
    {
        for (int i = 0; i < t.se - t.se % 2; i++) cnt[t.fi % m].pb(t.fi);
    }
    int answer = 0;
    for (int i = 0; i * 2 <= m; i++)
    {
        if (i + i == m || i == 0)
        {
            int k = cnt[i].size() / 2;
            for (auto t = 0; t < 2 * k; t++) kv[cnt[i][t]]--;
            answer += k;
        }
        else
        {
            int k = min(cnt[i].size(), cnt[m - i].size());
            for (auto t = 0; t < k; t++) kv[cnt[i][t]]--;
            for (auto t = 0; t < k; t++) kv[cnt[m - i][t]]--;
            answer += k;
        }
    }
    for (auto t : kv)
    {
        answer += t.se / 2;
    }
    printf("%d\n", answer);
    return 0;
