int main(void){
    ll n, m;
    cin >> n >> m;
    vector<ll> x(n);
    rep(i, n) cin >> x[i];

    map<ll,ll> rem;
    map<ll,ll> mp;
    rep(i, n){
        rem[x[i] % m]++;
        mp[x[i]]++;
    }
    map<ll,map<ll,ll>> mp2;
    for(auto &i : mp){
        mp2[i.first % m][i.first] = i.second;
    }

    ll ans = 0;
    ll M;
    if(m % 2 == 0){
        M = m / 2;
    } else {
        M = (m - 1) / 2;
    }
    for(int i = 0; i <= M; i++){
        if(i == 0){
            ans += rem[i] / 2;
        } else if(m % 2 == 0 && i == m / 2){
            ans += rem[i] / 2;
        } else {
            ans += min(rem[i], rem[m - i]);
            ll rest = abs(rem[i] - rem[m - i]);
            //cout << i << " " << rest << endl;
            ll plus = 0;
            if(rem[i] > rem[m - i]){
                for(auto &j : mp2[rem[i]]){
                    if(rest <= 1) break;
                    if(j.second > 1){
                        if(j.second > rest){
                            plus += rest / 2;
                            rest -= rest / 2 * 2;
                        } else {
                            plus += j.second / 2;
                            rest -= (j.second / 2) * 2;
                        }
                    }
                }
            } else if(rem[i] < rem[m - i]) {
                for(auto &j : mp2[rem[m - i]]){
                    if(rest <= 1) break;
                    if(j.second > 1){
                        if(j.second > rest){
                            plus += rest / 2;
                            rest -= rest / 2 * 2;
                        } else {
                            plus += j.second / 2;
                            rest -= (j.second / 2) * 2;
                        }
                    }
                }
            }

            ans += plus;
        }
    }

    cout << ans << endl;


