bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> a[i];

    return true;
}

void solve() {
    auto ans = 0;
    map<int, int> f, g, h;

    for (int i = 0; i < n; ++i)
        if (a[i] % m == 0)
            ++ans;
        else
            ++f[a[i]];

    ans /= 2;

    for (auto p : f) {
        ans += p.second / 2;

        if (p.second >= 2)
            h[p.first % m] += p.second / 2;

        if (p.second & 1)
            ++g[p.first % m];
    }

    vector<int> keys;

    for (auto p : g)
        keys.emplace_back(p.first);

    for (auto k : keys)
        for (; g[k] >= 2 && h[k] >= 1; g[k] -= 2, --h[k], ++ans) { }

    for (auto k : keys)
        if (k + k < m)
            ans += min(g[k], g[m - k]);

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

