signed main() {
	int n, m; cin >> n >> m;

	VV mods(m);
	rep(i, n) {
		int x; cin >> x;
		mods[x % m].push_back(x);
	}
	rep(i, m) sort(all(mods[i]));

	int ans = mods[0].size() / 2;
	if (m != 1 && m % 2 == 0) ans += mods[m / 2].size() / 2;
	rep(i, 1, (m + 1) / 2) {
		auto& a = mods[i];
		auto& b = mods[m - i];
		if (a.size() > b.size()) swap(a, b);
		int rem = b.size() - a.size();
		ans += a.size();
		rep(j, (signed)b.size() - 1) breakif(rem <= 1) if(b[j] == b[j + 1]) {
			ans++;
			rem -= 2;
			j++;
		}
	}
	cout << ans << endl;

	system("pause");
}

