	sort(&x[0], &x[N]);

	vvi a(M);
	vi v;
	for(int i=0;i<M;i++) a[i] = v;
	int cnt = 0;
	for(int i=0;i<=N;i++){
		if (i==N || (i>0 && x[i-1]!=x[i])){
			a[x[i-1]%M].pb(cnt);
