	for(int i=0;i<M;i++){
		for(int j=0;j<a[i].size();j++){
			cout << " " << a[i][j];
		}cout << endl;
	}*/

	int ans = 0;
	for(int i=0;i<M;i++){
		int i1 = i;
		int i2 = (M - i1)%M;
		if (i2 < i1) break;
		if (i2==i1){
			int sum = 0;
			for(int j=0;j<a[i].size();j++) sum += a[i][j];
			ans += sum/2;
		}else{
			int sum1 = 0;
			for(int j=0;j<a[i1].size();j++) sum1 += a[i1][j];			
			int sum2 = 0;
			for(int j=0;j<a[i2].size();j++) sum2 += a[i2][j];			
			if (sum1 < sum2) swap(i1, i2);
			ans += min(sum1, sum2) + solve(a[i1], min(sum1, sum2));
