using namespace std;

class TaskD {
public:
	void solve(std::istream& in, std::ostream& out) {
		int n, m;
		in >> n >> m;
		vector<vector<int>> v(m);
		for (int i: range(n)) {
			int x;
			in >> x;
			//x = rand();
			v[x % m].push_back(x);
		}

		int64_t ans = 0;
		ans += v[0].size() / 2;
		if (m % 2 == 0) {
			ans += v[m / 2].size() / 2;
		}
		for (int i = 1; i * 2 < m; ++i) {
			ans += min(v[i].size(), v[m - i].size());
			if (v[i].size() > v[m - i].size()) {
				ans += cnt(v[i], v[i].size() - v[m - i].size());
			} else {
				ans += cnt(v[m - i], v[m - i].size() - v[i].size());
			}
		}

		out << ans << "\n";
	}

	int64_t cnt(vector<int>& v, int x) {
		sort(v);
		int64_t ans = 0;
		for (int i = 0; i + 1 < (int)v.size();) {
			if (v[i] == v[i + 1]) {
				i = i + 2;
				++ans;
			} else {
				i = i + 1;
			}
		}
		//cerr << x << ' ' << ans << endl;
		return min(int64_t(x / 2), ans);
	}
};


int main() {
	std::ios_base::sync_with_stdio(false);
	TaskD solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
	out << std::fixed;
	out.precision(20);
	solver.solve(in, out);
	return 0;
}

