      swap(x, y);
    }
    count[x] += odd[x];
    if (count[x] <= odd[y]) {
      ans += count[x] + count[y] / 2;
      continue;
    }
    count[y] -= count[x] - odd[y];
    ans += count[x] + count[y] / 2;
  }
