    ll ans = 0;
    for(ll i=1;i<m;i++){
        ll a = i, b = m - a;
        if(a == b)continue;
        ll even1 = 0, even2 = 0;
        ll odd1 = 0, odd2 = 0;
        for(ll j=0;j<G[a].size();j++){
            if(G[a][j] % 2 == 0)even1 += G[a][j] / 2;
