			while(!pque[a].empty())
			{
				int y = pque[a].top();
				pque[a].pop();
				if(x<=y)
				{
					res += x;
					y-=x;
					pque[a].push(y);
					break;
				}
				x-=y;
				res += y;
			}
		}
		else
		{
			res += cnt2[b];
			int x = cnt2[a] - cnt2[b];
			while(!pque[b].empty())
			{
				int y = pque[b].top();
				pque[b].pop();
				if(x<=y)
				{
					res += x;
					y-=x;
					pque[b].push(y);
					break;
				}
				x-=y;
				res += y;
			}			
		}
	}

	for(int i=1;i<m;i++)
	{
		while(!pque[i].empty())
		{
			int now = pque[i].top();
			pque[i].pop();
			res += (now/2);
		}
	}

