int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);
    int n, m; cin >> n >> m;
    vector<int> X(n); cin >> X;
    map<int, int> cnt, cnt2;
    REP(i, n) {
        cnt[X[i]%m]++;
        cnt2[X[i]]++;
    }
    map<int, int> self;
    EACH(p, cnt2) {
        // cout << p.first << " " << p.second << endl;
        self[p.first%m] += p.second/2;
    }
    set<int> used;
    ll ans = 0;
    EACH(p, cnt) {
        int x, c; tie(x, c) = p;
        if ( used.count(x) > 0 ) continue;
        int y = m-x;
        used.insert(x);
        used.insert(y);
        if (x == y) {
            ans += c/2;
            // cout << c << endl;
        }
        else if (x == m || y == m) {
            ans += (cnt[x]+cnt[y])/2;
        }
        else {
            int c1 = c, c2 = cnt[y];
            int l1 = self[x], l2 = self[y];
            int M = 0;
            REP(i, min(c1, c2)+1) {
                int a = i;
                a += min<int>((c1-i)/2, l1);
                a += min<int>((c2-i)/2, l2);
                M = max(M, a);
            }
            ans += M;
        }
    }
    cout << ans << endl;
}

