void solve() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    rep(i, n) cin >> a[i];

    vector<map<int, int>> cnt(m);
    for (int x: a) ++cnt[x % m][x];
    vector<int> d(m), s(m);
    rep(i, m) {
        int dou = 0, sum = 0;
        for (auto p: cnt[i]) {
            dou += p.second / 2;
            sum += p.second;
        }
        d[i] = dou;
        s[i] = sum;
    }

    int ans = 0;
    rep(i, m / 2 + 1) {
        int j = (m - i) % m;
        if (i == j) {
            ans += s[i] / 2;
        } else {
            if (s[i] > s[j]) ans += s[j] + min((s[i] - s[j]) / 2, d[i]);
            else if (s[i] == s[j]) ans += s[i];
            else ans += s[i] + min((s[j] - s[i]) / 2, d[j]);
        }
    }

    cout << ans << "\n";
    return;
}

