signed main(){
  srand((unsigned)time(NULL));
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  int N, M;
  cin>>N>>M;
  vector<int> X(N);
  cin>>X;

  map<int, int> cnt[M];
  for(int x:X) cnt[x%M][x]++;

  auto calc = [&](int a, int b){

    if(a == b){
      int sum = 0;
      for(auto p:cnt[a]) sum += p.second;
      return sum / 2;
    }

    vector<P> A, B;
    for(auto p:cnt[a]) A.emplace_back(p.second, p.first);
    for(auto p:cnt[b]) B.emplace_back(p.second, p.first);
    sort(A.begin(), A.end());
    sort(B.begin(), B.end());

    int N = A.size(), M = B.size();
    int res = 0;
    int i = 0, j = 0;
    while(i < N && j < M){
      if(A[i].first == 0) i++;
      if(B[j].first == 0) j++;
      if(i == N || j == M) break;
      res++;
      A[i].first--;
      B[j].first--;
    }
    while(i < N) res += A[i].first / 2, i++;
    while(j < M) res += B[j].first / 2, j++;
    return res;
  };

  int ans = 0;
  for(int i=0;i<M;i++){
    int a = i;
    int b = (M - i) % M;
    if(a <= b) ans += calc(a, b);
  }

  cout<<ans<<endl;

  return 0;
}

