void solve() {
	int N, M; cin >> N >> M;
	vector<int> X(N); for (auto& a : X) cin >> a;
	vector<int> MX(M);
	REP(i, N) {
		MX[X[i] % M]++;
	}
	unordered_map<int, int> cnt;
	for (auto& a : X) {
		cnt[a]++;
	}
	vector<int> tsugai(M);
	for (auto& a : cnt) {
		tsugai[a.first % M] = a.second - (a.second % 2);
	}

	int res = 0;

	FOR(i, 1, MX.size() / 2+1) {
		int j = M - i;
		int num = min(MX[i], MX[j]);
		MX[i] -= num;
		MX[j] -= num;
		res += num;
	}
	res += MX[0] / 2;

	if(MX.size() % 2 == 0){
		int tar = MX.size() / 2;
		res += MX[tar]/2;
	}

	REP(i, MX.size()) {
		res += min(MX[i], tsugai[i]) / 2;
	}

	cout << res << endl;
}

