int calc(int a, int b) {
  if (X[a].size() > X[b].size()) {
    swap(a, b);
  }
  int as = X[a].size(), bs = X[b].size();
  int res = 0;
  for (int i = 0; i <= as; ++i) {
    chmax(res, i + min(P[a], (as - i) / 2) + min(P[b], (bs - i) / 2));
  }
  return res;
}

