		cin >> X[i];
		cnt[X[i]]++;
	}
	rep(i,100100) {
		r[i%M] += cnt[i]%2;
		q[i%M] += cnt[i]/2;
	}
	int res = 0;
	for(int i = 1; ; i++) {
		int j = M-i;
		if(i >= j) break;
		int qa, qb, ra, rb;
		if(r[i] < r[j]) {
			ra = r[i];
			rb = r[j];
			qa = q[i];
			qb = q[j];
		}
		else {
			ra = r[j];
			rb = r[i];
			qa = q[j];
			qb = q[i];
		}
		// a < b
		res += ra;
		rb -= ra;
		ra = 0;
		res += min(rb, qa*2);
		qa = max(0, (qa*2 - rb)/2);
		res += qa;
		res += qb;
	}
	if(M % 2 == 0) {
		res += q[M/2];
		res += r[M/2]/2;
	}
	res += (q[0]*2+r[0])/2;
	cout << res << endl;
