    rep(i,100001){
        if(count[i]%2==1){
            kisuu[i%m]++;
        }
    }

    int ans = 0;

    rep(i,m){
        if(i==0){
            int now = 0;
            int sum = 0;
            while(now*m<100001){
                sum += count[now*m];
                now++;
            }
            ans += sum/2;
        }else if(i*2==m){
            int now = 0;
            int sum = 0;
