template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<ll> X(N); for(auto& in:X) cin >> in;
    map<ll,ll> Xcnt;
    for(auto& v:X) Xcnt[v]++;

    map<ll,ll> SameGroup;
    for(auto& v:X) SameGroup[v%M]++;
    map<ll,ll> PairCnt;
    for(auto& p:Xcnt) PairCnt[p.first%M] += p.second/2;

    ll T1 = 0; // 重複しない個数
    ll T2 = 0; // 重複する個数
    for(ll x = 0; x < M; x++){
        ll y = M-x;
        if(x == 0 || x == y){ // この場合はどんな組み合わせでも条件を満たす
            T1 += SameGroup[x]/2;
            continue;
        }

        ll s1 = SameGroup[x], s2 = SameGroup[y];
        ll p1 = PairCnt[x],p2 = PairCnt[y];

        ll add_T2 = 0;
        for(ll p = 0; p <= p1; p++){
            ll T = 0;
            // p1のうちp個のペアを使う
            T += p;

            // s1 - p*2 個をs2とのペア候補
            ll left_x = s1 - p*2;

            T += min(left_x,s2);
            T += min((s2-left_x)/2,p2);

            add_T2 = max(add_T2,T);
        }

        T2 += add_T2;
    }

    res = T1 + T2/2;
    return res;
}
