  for(i=0; i<M; i++) {
    for(j=0; j<v[i].size(); j++) {
      ll t=1;
      while(v[i][j]==v[i][j+1]) {
        t++;
        j++;
      }
      cnt[i].push_back(t);
    }
    sort(cnt[i].begin(), cnt[i].end());
  }

  //INFの分を取り除く
  for(i=0; i<M; i++) cnt[i].erase(cnt[i].begin());

  ll s[MAX]={};
  ll odd[MAX]={};
  for(i=0; i<M; i++) {
    ll t=0;
    for(j=0; j<cnt[i].size(); j++) {
      t+=cnt[i][j];
      if(cnt[i][j]&1) odd[i]++;
    }
    s[i]=t;
  }

  ll ans=s[0]/2;
