			if(i1 % 2 == 0)
				dame += max(0, i1 - modEqual[i]);
			else
				dame += max(1, i1 - modEqual[i]);
			if(i2 % 2 == 0)
				dame += max(0, i2 - modEqual[counterpart]);
			else
				dame += max(1, i2 - modEqual[counterpart]);

		}
