            if (cur-2 > 0) modM.at(0).push(cur-2);
        } else if (!modM.at(0).empty()) {
            int nx = modM.at(0).top(); modM.at(0).pop();
            ++res;
            if (nx-1 > 0) modM.at(0).push(nx-1);
        }
    }
    if (m%2 == 0) {
        while (!modM.at(m/2).empty()) {
            int cur = modM.at(m/2).top(); modM.at(m/2).pop();
            if (cur > 1) {
                ++res;
                if (cur-2 > 0) modM.at(m/2).push(cur-2);
            } else if (!modM.at(m/2).empty()) {
                int nx = modM.at(m/2).top(); modM.at(m/2).pop();
                ++res;
                if (nx-1 > 0) modM.at(m/2).push(nx-1);
            }
        }
    }
    for (int i=1; i<m; ++i) {
        int i0 = i, i1= m-i;
        if (i0 == i1) continue;
        while (!modM.at(i0).empty() && !modM.at(i1).empty()) {
            int cur0 = modM.at(i0).top(); modM.at(i0).pop();
            int cur1 = modM.at(i1).top(); modM.at(i1).pop();
            ++res;
            if (cur0 > 1) modM.at(i0).push(cur0-1);
            if (cur1 > 1) modM.at(i1).push(cur1-1);
        }
        if (!modM.at(i0).empty()) {
            while (!modM.at(i0).empty()) {
                int cur = modM.at(i0).top(); modM.at(i0).pop();
                if (cur > 1) {
                    ++res;
                    if (cur-2 > 1) modM.at(i0).push(cur-2);
                }
            }
        }
        if (!modM.at(i1).empty()) {
            while (!modM.at(i1).empty()) {
                int cur = modM.at(i1).top(); modM.at(i1).pop();
                if (cur > 1) {
                    ++res;
                    if (cur-2 > 1) modM.at(i1).push(cur-2);
                }
            }
        }
    }
    cout << res << '\n';
}

