template<class T>using priority_queue_rev = priority_queue<T, vector<T>, greater<T>>;
int main() {
  int N, M;
  ins(N, M);
  map<int, int> m, count;
  map<int, priority_queue<int>> m2;
  map<int, priority_queue_rev<int>> q;

  rep(i, N) {
    int X; cin >> X;
    ++m[X];
  }
  for (const auto& [x, c] : m) {
    m2[x % M].push(c);
    count[x % M] += c;
  }
  ll ans = 0;
  for (const auto& e : m2) {
    int x = e.first, y = M-x;
    auto c = e.second, c2 = m2[y];
    if (x == 0 || 2 * x == M) {
      ans += count[x] / 2;
      continue;
    }
    if (count[x] > count[y]) {
      swap(x, y);
      swap(c, c2);
    }
    // xのほうが少ない
    if (count[x] == 0) {
      while (!c2.empty()) {
        ans += c2.top() / 2; c2.pop();
      }
      continue;
    }
    while (count[y] > count[x]) {
      if (count[y] - c2.top() > count[x]) {
        int p = c2.top(); c2.pop();
        ans += p / 2;
        if (p % 2 > 0)
          c2.push(p % 2);
      } else {
        ans += (count[y] - count[x] - 1) / 2;
        break;
      }
    }
    ans += count[x];
    count[x] = 0;
  }
  cout << ans << endl;
  return 0;
}

