typedef long long ll;
int main(){
  ll n,m;
  cin >> n >> m;
  map<ll,ll> a;
  for(int i = 0;i < n;i++){
    ll in;
    cin >> in;
    a[in]++;
  }
  vector<pair<ll,ll>> mo(m,make_pair(0,0));//要素数,同じ中のペア数
  for(auto i:a){
    mo[i.first % m].first += i.second;
    mo[i.first % m].second += i.second / 2;
  }
  ll res = 0;
  //res += mo[0].first / 2;
  for(int i = 0;i <= m / 2;i++){
    if((i + i) % m == 0)res += mo[0].first / 2;
    else{
      pair<ll,ll> a = {mo[i].first,mo[i].second};
      pair<ll,ll> b = {mo[m - i].first,mo[m - i].second};
      if(a.first > b.first || (a.first == b.first && a.second > b.second))swap(a,b);
      if((b.first - a.first) < b.second * 2){//bの中のペアが余る
        res += (b.first - a.first) / 2;
        res += a.first;
      } 
      else{//bの中のペアを使い切る
        res += b.second;
        res += a.first;
      }
    }
    //cout << i << " " << res << endl;
  }
  //cout << mo[4].first << " " << mo[4].second << endl;
  //cout << mo[6].first << " " << mo[6].second << endl;
  cout << res << endl;
}

