signed main() {
  int N, M;
  cin >> N >> M;
  vector<int> v[101010];
  for (int i = 0; i < N; i++) {
    int x;
    cin >> x;
    v[x % M].push_back(x);
  }

  static bool vis[101010];
  m0(vis);

  int ans = v[0].size() / 2;
  vis[0] = true;

  if (M % 2 == 0) {
    ans += v[M / 2].size() / 2;
    vis[M / 2] = true;
  }

  for (int i = 1; i <= M; i++) {
    if (vis[i]) continue;
    vis[i] = vis[M - i] = true;

    int a = i, b = M - i;
    if (v[a].size() > v[b].size()) swap(v[a], v[b]);
    vec x = v[a], y = v[b];

    ans += x.size();

    map<int, int> mp;
    for (auto tmp : y) mp[tmp]++;

    int sum = 0;
    for (auto tmp : mp) sum += tmp.second / 2;

    ans += min(sum, (int)y.size() - (int)x.size());
  }

  cout << ans << endl;
  return 0;
}

