	for(int i=0;i<M;i++){
		if(i==0){
			ans += mod_count[i]/2;
			mod_count[i] %= 2;
		}else{
			if(i!=M-i) ans += min(mod_count[i],mod_count[M-i]);
			else ans += mod_count[i]/2;
			if(mod_count[i]>=mod_count[M-i]){
				mod_count[i] -= mod_count[M-i];
				mod_count[M-i] = 0;
			}else{
				mod_count[M-i] -= mod_count[i];
