    cin >> X[i];
  }
  vector<int> box(M);
  vector<int> box2(MAX_X);
  vector<int> used(M);
  REP(i, N) {
    box[X[i] % M]++;
    box2[X[i]]++;
  }
  used[0] = box[0];
  SREP(1, i, (M + 1) / 2) {
