  SREP(1, i, (M + 1) / 2) {
    count += used[i];
  }
  if (M % 2 == 0) {
    int idx = M / 2;
    count += used[idx] / 2;
  }
  vector<int> rest(M);
  REP(i, M) {
    rest[i] = box[i] - used[i];
  }
  vector<int> pair_count(M);
  REP(i, MAX_X) {
    int m = i % M;
    pair_count[m] += box2[i] / 2;
  }
  REP(i, M) {
