using namespace std;

vector<vector<int>> edge;
vector<int> match;
vector<int> used;

void add_edge(int u, int v) {
	edge[u].push_back(v);
	edge[v].push_back(u);
}

bool dfs(int v) {
	used[v] = true;
	int i;
	for (i = 0; i < (int)edge[v].size(); ++i) {
		int u = edge[v][i];
		int w = match[u];
		if (w < 0 || !used[w] && dfs(w)) {
			match[v] = u;
			match[u] = v;
			return true;
		}
	}
	return false;
}

int main(int argc, char* argv[]) {
#ifdef _MSC_VER
	while (true)
#endif
	{
		int n = -1, m = -1;
		cin >> n >> m;
		if (n < 0) return 0;
		vector<int> x(n);
		map<int, vector<int>> same;
		vector<vector<int>> mods(m);
		for (int i = 0; i < n; ++i) {
			cin >> x[i];
			same[x[i]].push_back(i);
			mods[x[i] % m].push_back(i);
		}
		edge.clear();
		edge.resize(n);
		match.clear();
		match.resize(n, -1);
		for (int i = 0; i < n; ++i) {
			for (int j : same[x[i]]) {
				if (j != i) {
					add_edge(i, j);
				}
			}
			for (int j : mods[(m - (x[i] % m)) % m]) {
				if (j != i) {
					add_edge(i, j);
				}
			}
		}
		int matched = 0;
		for (int i = 0; i < n; ++i) {
			if (match[i] < 0) {
				used = vector<int>(n, 0);
				matched += dfs(i);
			}
		}
		int ans = n - 1 - matched;
		cout << ans << endl;
	}
	return 0;
}

