map<int, vector<int>> container;
map<int, int> consume;
map<int, int> whole;
set<int> visited;

int ans;

int main(void) {
  // Here your code !
  scanf("%d %d", &n, &m);

  for (int i = 0; i < n; ++i) {
    scanf("%d", &(x[i]));
  }

  for (int i = 0; i < n; ++i) {
    container[x[i] % m].push_back(x[i]);
  }

  for (auto &e : container) {
    whole[e.first] = e.second.size();

    map<int, int> cnt;

    for (auto &d : e.second) {
      cnt[d] += 1;
    }

    for (auto &d : cnt) {
      consume[e.first] += d.second / 2;
    }
  }

  ans = 0;

  for (auto &e : whole) {
    int key = e.first;
    int opposite_key = (m - key) % m;

    if (visited.find(key) != visited.end() ||
        visited.find(opposite_key) != visited.end())
      continue;

    visited.insert(key);
    visited.insert(opposite_key);

    if (opposite_key == key) {
      ans += whole[key] / 2;
    } else {
      if (whole.find(opposite_key) == whole.end()) {
        ans += consume[key];
        continue;
      }

      int x = key;           // bigger
      int y = opposite_key;  // smaller

      if (whole[x] < whole[y]) {
        swap(x, y);
      }

      int diff = abs(whole[x] - whole[y]);
      int actual_consumed_pair = min(diff / 2, consume[x]);

      ans += actual_consumed_pair;  // duplicate pair consume
      ans += whole[y];
    }
  }

  printf("%d\n", ans);

  return 0;
}

