		int x=i,y=m-x;
		int nx=div[x].size(),ny=div[y].size();
		if(nx>ny)swap(x,y);
		ret+=nx;
		int pr=0;
		for(int j=0;j<y-1;j++){
			sort(begin(div[y]),end(div[y]));
			if(div[y][j]==div[y][j+1]){pr++;j++;}
		}
		ret+=min(ny-nx,pr);
	}
	cout<<ret<<endl;

}

