                    sum += vsum2[m - i][j];
                }
                if (odd < add) {
                    res += sum / 2;
                }
                else {
                    for (Int j = 0; j < (Int)vsum2[m - i].size(); j++) {
                        res += vsum2[m - i][j] / 2;
                    }
                }
            }
        }
    }
    dump(res);
    return 0;
}

