int main(int argc, char* argv[]) {
#ifdef _MSC_VER
	while (true)
#endif
	{
		int n = -1, m = -1, ans = 0;
		cin >> n >> m;
		if (n < 0) return 0;
		vector<int> x(n);
		vector<vector<int>> mods(m);
		for (int i = 0; i < n; ++i) {
			cin >> x[i];
			mods[x[i] % m].push_back(x[i]);
		}
		for (int i = 0; i <= m / 2; ++i) {
			if (i == 0 || i * 2 == m) {
				ans += (int)mods[i].size() / 2;
