void greedy_decf(i32 cnt, VI& v) {
    for (auto&& e: v) {
        if (cnt == 0) return;
        if (e % 2 == 1) {
            e--;
            cnt--;
        }
    }
    while (cnt > 0) {
        i32& tail = v.back();
        if (tail <= cnt) {
            v.pop_back();
            cnt -= tail;
        } else {
            tail -= cnt;
            cnt = 0;
        }
    }
}



void Main() {
    i32 n, m;
