        vec.at(i) = num;
        counter.at(num)++;
    }
    VVI modcnt(m, VI{});
    REP(i, 100001) {
        i32 cnt = counter.at(i);
        if (cnt) {
            modcnt.at(i % m).push_back(cnt);
        }
    }

    i32 ans{};
    REP(i, m / 2 + 1) {
        i32 j = (m - i) % m;
        i32 i_group_size = accumulate(ALL(modcnt.at(i)), 0);
        i32 j_group_size = accumulate(ALL(modcnt.at(j)), 0);
        // debug(i);
        // debug(j);
        // debugvec(modcnt.at(i));
        if (i == j) {
            ans += i_group_size / 2;
        } else {
            if (i_group_size < j_group_size) {
                ans += i_group_size;
                greedy_decf(i_group_size, modcnt.at(j));
                for (auto e: modcnt.at(j)) ans += e / 2;
            } else {
                ans += j_group_size;
                greedy_decf(j_group_size, modcnt.at(i));
                for (auto e: modcnt.at(i)) ans += e / 2;
            }
        }
    }
    print(ans);
}


