    ans += m[r];
    X -= m[r];
    m[r] = 0;
    if (p[r] >= X) {
      int n = p[r] - X;
      ans += X;
      p[r] = n - (n%2);
      m[r] = n % 2;
    } else {
      // p[r]枚すべて使ってペアをつくる
      ans += p[r]/2;
      X -= p[r];
      p[r2] += X-(X%2);
      m[r2] += X % 2;
    }
  }
  rep(i, M)
    ans += p[i] / 2;
  cout << ans << endl;

