        //other
        reps(i,1,M/2){
            int a = (int)A[i].size();
            int b = (int)A[M-i].size();

            if(a < b){
                b -= a;
                map<int,int> B;
                int c = 0;
                rep(j,(int)A[M-i].size()) B[A[M-i][j]]++;
                for (pii p : B) c += p.se/2;

                chmin(b,c);

                ans += a + b;

            }else if(a > b){
                a -= b;
                map<int,int> B;
                int c = 0;
                rep(j,(int)A[i].size()) B[A[i][j]]++;
                for (pii p : B) c += p.se/2;

                chmin(a,c);

                ans += b + a;

            }else{
                ans += a;
            }
        }

    }



    cout << ans << endl;



    return 0;
}

