  rep(i, n) {
    cin >> x[i];
    chmax(maxX, x[i]);
  }

  vector<ll> cnts(maxX + 1); // cnts[i] .. counts of i
  rep(i, n) {
    ++cnts[x[i]];
  }

  vector<vector<ll>> mp(m); // { x MOD m => <cnts> }
  rep(i, maxX + 1) {
    if (cnts[i] > 0) {
      mp[i%m].push_back(cnts[i]);
    }
  }

  // For Debug
  // rep(i, m) {
