    for(int i = 1; i <= m; ++i) {
        int j = m - i;
        if(i > j) continue;
        else if(i < j) {
            int cnti = 0, cntj = 0;
            for(int k = 0; m * k + i <= 10000; ++k) {
                int y = m * k + i, z = m * k + j;
                cnti += mp[y];
                cntj += mp[z];
