int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n,m;
  cin >> n >> m;
  int x[n];
  rep(i,n) cin >> x[i];
  sort(x,x+n);
  int c[m],kumi[m];
  rep(i,m){
    c[i]=0;
    kumi[i]=0;
  }
  rep(i,n){
    c[x[i]%m]++;   
  }
  rep(i,n-1){
    if(x[i]==x[i+1]){
      kumi[x[i]%m]++;
      i++;
    }
  }
  //  rep(i,m) cout << i << " " << c[i] << endl;
  int ans=0;
  rep(i,m/2+1){//0と半分
    if(i==0){
      ans+=c[i]/2;
    }
    else if(m%2==0 && i==m/2){
      ans+=c[i]/2;
    }
    else if(c[i]>=c[m-i]){
      ans+=c[m-i];
      ans+=min(kumi[i],(c[i]-c[m-i])/2);
    }else{
      ans+=c[i];
      ans+=min(kumi[m-i],(c[m-i]-c[i])/2);
    }
    //    cout << ans << endl;
  }
  cout << ans << endl;

  return 0;


}

#include<bits/stdc++.h>
using namespace std ;
#define N 100010
int arr[ N ] , removes[ N ] , hashe[ N ];
multiset < pair < int , int > > hasheset[ N ] ;

int main() 
{
	int n , x , m ;
	cin >> n >> m ;

	for( int i = 0 ; i < n ; i++ ) {
		cin >> x ;
		arr[ x%m ]++ ;
		hashe[ x ]++;
	}

	int ans = ( arr[0] )/2 ;
	for( int i = 0 ; i < N ; i++ ) {
		if( hashe[ i ] ) 
			hasheset[ i%m ].insert( make_pair( 1 - i%2 , hashe[ i ] ) );
	}

	for( int i = 1 , j = m - 1 ; i <= j ; i++,j-- ) {

		if( i == j ) {
			if( i + j != m ) 
				continue ;
			ans += arr[ i ]/2;
			arr[ i ] = 0 ;
			continue ;
		}
		int y = min( arr[ i ] , arr[ j ] );
		arr[ i ] -= y ;
		arr[ j ] -= y ;
		removes[ i ] = y ;
		removes[ j ] = y ; 
		ans += y ;
	}

		//cout << ans << endl ;

	//cout << 
	for( int i = 1 ; i < m ; i++ ) {
		if( arr[ i ] == 0 )
			continue ;

		while( removes[ i ] ) {
			pair < int , int > element = *hasheset[ i ].begin() ;
			hasheset[ i ].erase( hasheset[ i ].begin() );

			if( element.second == 0 ) continue ;
			removes[ i ]-- ;
			element.second-- ;
			element.first = 1 - element.first ;
			hasheset[ i ].insert( element );
		}

		for( multiset < pair < int , int > > :: iterator it = hasheset[ i ].begin() ; it != hasheset[ i ].end() ; it++ )
		{

			ans += ( it->second )/2;
		}
		//cout << ans << " " << i << "\n";
	}

	cout << ans ;

	return 0 ;
}

