signed main(){
  cin>>n>>m;
  rep(i,n){
    int x;cin>>x;
    c[x%m]++;
    t[x]++;
    if(t[x]%2 == 0)d[x%m]++;
  }
  int ans = 0;
  for(auto p : c)vec.push_back(p.first);
  for(auto md : vec){
    if(c[md] == -1)break;
    int op = (m-md)%m;
    assert(0 <= op && op < m);
    if(md == op){
      ans += c[md]/2;
      c[md] = -1;
    }else{
      int dc = min(c[md], c[op]);
      ans += dc;
      c[md] -= dc;
      c[op] -= dc;
      ans += max(min(d[op], c[op]/2), min(d[md], c[md]/2));
      c[md] = c[op] = -1;
    }
  }
  cout << ans << endl;
}

