        if(used.at(i)){ continue; }
        if(prev_notused != -1 && x.at(prev_notused) == x.at(i)){
            ans++;
            used.at(prev_notused) = true;
            used.at(i) = true;
            prev_notused = -1;
        }
        if(!used.at(i)){
            prev_notused = i;
        }
    }

    cout << ans << endl;

    return 0;
}

