	for(i=1;i<=(m-1)/2;i++){
		int cnt = 0,a = v[i].size(),b = v[m-i].size();
		ans += min(a,b);
		if(a>b){
			sort(v[i].begin(),v[i].end());
			v[i].erase(unique(v[i].begin(),v[i].end()),v[i].end());
			for(j=0;j<v[i].size();j++){
