	for(auto a:mp){
		Pnum[a.first%M] += a.second/2;
		num[a.first%M] += a.second;
	}

	int ans = 0;

	for(int i=0;i<=M/2;i++){
		if(i+i==M||i==0){
			ans += num[i]/2;
		}
		else{
			int x = min(num[i],num[M-i]);
			ans += x;
			num[i] -= x;
			num[M-i] -= x;

			ans += min(num[i]/2,Pnum[i]);
			ans += min(num[M-i]/2,Pnum[M-i]);
		}
	}

	cout<<ans<<endl;

	return 0;
}

