    else if(cnt[i] == 1 || cnt[i] % 2 == 0)
      m[i % M].pb(cnt[i]);
    else{
      m[i % M].pb(1);
      m[i % M].pb(cnt[i] - 1);
    }
  }
  each(x , m) sort(all(x.second));
  trcc(m);
  int ans = 0;


