  trc(ans);
  if(M % 2 == 0 && m.find(M / 2) != m.end()) ans += f(m.find(M / 2)->second);
  trc(ans);
  // rem = 1以上 M/2未満
  for(int rem = 1 ; rem * 2 < M ; rem++){
