int main(){
    ll n, m;
    cin >> n >> m;
    vector<ll> x(n);
    REP(i, n){
        cin >> x.at(i);
    }
    sort(ALL(x));

    ll ans = 0;
    vector<bool> used(n, false);
    vector<vector<ll>> modm(m);
    REP(i, n){
        const ll mx = x.at(i) % m;
        const ll my = (m - mx) % m;
        if(modm.at(my).size()){
            ans++;
            const ll j = modm.at(my).back();
            modm.at(my).pop_back();
            used.at(i) = true;
            used.at(j) = true;
        }else{
            modm.at(mx).push_back(i);
        }
    }

    ll prev_notused = -1;
    REP(i, n){
        if(prev_notused != -1 &&
           x.at(prev_notused) == x.at(i)){
            ans++;
            used.at(prev_notused) = true;
            used.at(i) = true;
            prev_notused = -1;
        }
        if(!used.at(i)){
            prev_notused = i;
        }
    }

    cout << ans << endl;

    return 0;
}

