int main() {
    ll N,M;
    cin >> N >> M;
    auto X = InputVec(N);
    vector<ll> sumMod(M,0);
    vector<map<ll,ll>> bucket(M,map<ll,ll>());
    for (int i = 0; i < N; ++i) {
        ll current = X[i];
        ll cMod = X[i] % M;
        sumMod[cMod]++;
        bucket[cMod][current]++;
    }
    for (int i = 1; i < M/2; ++i) {
        if(sumMod[i] < sumMod[M-i]){
            swap(sumMod[i],sumMod[M-i]);
            bucket[i].swap(bucket[M-i]);
        }
    }
    ll count = 0;
    count += sumMod[0]/2;
    //OutputVec(sumMod);
    for (int i = 1; i < (M + 1)/2; ++i) {
        if(sumMod[i] > sumMod[M-i] + 1){
            auto beg = bucket[i].begin();
            auto end = bucket[i].end();
            for (auto iter = beg; iter != end; ++iter) {
                if(sumMod[i] <= sumMod[M-i] + 1){
                    break;
                }
                while(iter->second >= 2){
                    iter->second -= 2;
                    count++;
                    sumMod[i]-=2;
                    if(sumMod[i] <= sumMod[M-i] + 1){
                        break;
                    }
                }
            }
        }
        //cout <<M - i <<"," <<sumMod[M-i] << endl;
        count += sumMod[M-i];
    }
    if(M % 2 == 0){
        count += sumMod[M/2]/2;
    }
    cout << count << endl;

}

