int N, M, X[100010];
const int MAX_X = 100000;

void solve() {
	Vec< int > cnt(MAX_X + 1, 0);
	for_(i,0,N) cnt[X[i]]++;

	Vec< queue< int > > vque(M + 1);
	Vec< int > cnt_odd(M + 1);
	for_rev(x,MAX_X,1) if (cnt[x] > 0) {
		if (cnt[x] % 2) {
			vque[x % M].push(cnt[x] - 1);
			++cnt_odd[x % M];
		} else {
			vque[x % M].push(cnt[x]);
		}
	}

	int ans = 0;
	for_(x,0,M) {
		int a = x, b = (M - a) % M;

		if (a == b) {
			ans += cnt_odd[a] / 2;
		} else {
			ans += min(cnt_odd[a], cnt_odd[b]);
		}

		while (!vque[x].empty()) {
			int top = vque[x].front(); vque[x].pop();
			ans += top / 2;
		}
	}

	cout << ans << endl;
}

