int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(0);
	int n, m; cin >> n >> m;
	int x;
	unordered_map<int, int> cnt;
	vector<vector<int>> num(100001);
	rep(i, 0, n) {
		cin >> x;
		cnt[x]++;
	}
	for (auto e : cnt) {
		num[e.first % m].push_back(e.second);
	}

	int ans = 0;

	rep(i, 0, m / 2 + 1) {
		int k = (m - i) % m;
		sort(num[i].begin(), num[i].end());
		sort(num[k].begin(), num[k].end());
		ll a = accumulate(num[i].begin(), num[i].end(), 0);
		ll b = accumulate(num[k].begin(), num[k].end(), 0);
		if (i == k) {
			ans += a / 2;
			continue;
		}
		ans += min(a, b);
		if (a > b) {
			ll t = b;
			int j = 0;
			while (t > 0 && j < num[i].size()) {
				ll d = min((ll)num[i][j], t);
				t -= d;
				num[i][j] -= d;
				if (t == 0) {
					ans += num[i][j] / 2;
				}
				++j;
			}
		}
		else {
			ll t = a;
			int j = 0;
			while (t > 0 && j < num[k].size()) {
				ll d = min((ll)num[k][j], t);
				t -= d;
				num[k][j] -= d;
				if (t == 0) {
					ans += num[k][j] / 2;
				}
				++j;
			}
		}
	}
	cout << ans << endl;

	return 0;
}

