using ll = long long;


void solve(long long N, long long M, std::vector<long long> X){
    map<int, int> mp;
    for(int i = 0;i < N;i++){
        mp[X[i]]++;
    }
    vector<vector<pair<int, int>>> v(M);
    for(auto a : mp){
        v[a.first%M].push_back(make_pair(a.second, a.first));
    }
    for(int i = 0;i < M;i++)
        sort(v[i].begin(), v[i].end());

    ll ans = 0;
    for(int i = 1;i <= M/2;i++){
        int idx = 0;
        if(i == M - i)continue;

        for(auto&& a : v[i]){
            if(idx == v[M-i].size())continue;
            while(1){
                if(a.first == 0)break;
                if(v[M-i][idx].first == 0){
                    idx++;
                    if(v[M-i].size() == idx)break;
                }else{
                    //cout<<a.second<<" "<<v[M-i][idx].second<<endl;
                    ans++;
                    v[M-i][idx].first--;
                    a.first--;
                }
            }
        }
    }
    for(int i = 0;i < M;i++){
        for(auto&& a : v[i]){
            if(a.first / 2 > 0)ans += a.first / 2;
            //for(int j = 0;j < a.first / 2 ;j++)cout<<a.second<<" "<<a.second<<endl;
            //cout<<a.second<<" "<<a.first % 2<<endl;
            a.first %= 2;
        }
    }

    if(M % 2 == 0){
        ll cnt = 0;
        for(auto a : v[M/2])cnt += a.first;
        ans += cnt / 2;
    }
    ll cnt = 0;
    for(auto a : v[0])cnt += a.first;
    ans += cnt / 2;

    cout<<ans<<endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    long long M;
    scanf("%lld",&M);
    std::vector<long long> X(N);
    for(int i = 0 ; i < N ; i++){
        scanf("%lld",&X[i]);
    }
    solve(N, M, std::move(X));
    return 0;
}

