int main()
{
   int N,M; cin>>N>>M;
   vector<int> x(N);
   for(int i=0;i<N;i++) cin>>x[i];
   sort(x.begin(),x.end());

   vector<int> cnt(M),cntPair(M);
   for(int i=0;i<N;){
      int i0=i++;
      while(i<N and x[i]==x[i0]) i++;
      cnt[x[i0]%M]+=i-i0;
      cntPair[x[i0]%M]+=(i-i0)/2;
   }
   // for(int i=0;i<M;i++) cout<<cnt[i]<<' '; cout<<endl;
   // for(int i=0;i<M;i++) cout<<cntPair[i]<<' '; cout<<endl;

   int ans=cnt[0]/2;
   for(int i=1;i<=(M-1)/2;i++){
      int x=i,y=M-x;
      // cout<<x<<' '<<y<<endl;
      int ma=0;
      for(int j=0;j<=min(cnt[x],cnt[y]);j++){
         int cnt_pair=j;
         int X=cnt[x]-j;
         int Y=cnt[y]-j;
         if(X>=2*cntPair[x]) cnt_pair+=cntPair[x];
         else cnt_pair+=X/2;
         if(Y>=2*cntPair[y]) cnt_pair+=cntPair[y];
         else cnt_pair+=Y/2;
         ma=max(ma,cnt_pair);
      }
      ans+=ma;
   }
   if(M%2==0) ans+=cnt[M/2]/2;
   cout<<ans<<endl;
   return 0;
}

