inline int match(vector<int> a, vector<int> b) {
    if (len(a) < len(b)) {
        swap(a, b);
    }
    int can = len(b);
    int left = (len(a) - len(b)) / 2;
    map<int, int> c;
    for (int i : a) {
        c[i]++;
    }
    for (auto i : c) {
        int cnt = min(left, i.sc / 2);
        left -= cnt;
        can += cnt;
    }
    return can;
}

