#define rep(i,n) for(int i=0,_i=(n);i<_i;++i)
#define all(f,c,...) (([&](decltype((c)) cccc) { return (f)(begin(cccc), end(cccc), ## __VA_ARGS__); })(c))
int main() {
  int N, M;
  ins(N, M);

  vi X(N);
  rep(i, N)
    cin >> X[i];
  all(sort, X);

  vector<int> m(M, 0), p(M, 0);
  int ans = 0;
  map<int, int> count;
  rep(i, N)
    ++count[X[i]];

  for (const auto& e:count) {
    int X = e.second;
    int r = (M - e.first % M) % M,
        r2 = e.first % M;
    if (m[r] >= X) {
      ans += X;
      m[r] -= X;
      X = 0;
      continue;
    }
    ans += m[r];
    X -= m[r];
    m[r] = 0;
    if (p[r] >= X) {
      int n = p[r] - X;
      ans += X;
      p[r] = n - (n%2);
      m[r] = n % 2;
    } else {
      // p[r]枚すべて使ってペアをつくる
      ans += p[r]/2;
      X -= p[r];
      p[r] = 0;
      p[r2] += X-(X%2);
      m[r2] += X % 2;
    }
  }
  rep(i, M)
    ans += p[i] / 2;
  cout << ans << endl;

  return 0;
}

