            ans+=min(modPairMap[i],modMap[i]-modMap[M-i])/2;
        }else{
            ans+=min(modPairMap[M-i],modMap[M-i]-modMap[i])/2;
        }
    }
    cout<<ans<<endl;
    return 0;
}

