constexpr int X_MAX = 100'000;

int pairing( VI &A, int K )
{
	sort( ALL( A ) );

	int res = 0;
	VI B;
	REP( i, SZ( A ) )
	{
		if ( K && i + 1 < SZ( A ) && A[i] == A[ i + 1 ])
		{
			++i;
			++res;
			--K;
			continue;
		}

		B.PB( A[i] );
	}
	A = B;
	return res;
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int N, M;
	scanf( "%d%d!", &N, &M );

	VI X( N );
	for_each( ALL( X ), [=]( int &x ){ scanf( "%d", &x ); } );

	VI counts( X_MAX + 1 );
	for_each( ALL( X ), [&]( const int &x ){ ++counts[x]; } );

	VVI cards( M );
	FOR( x, X )
	{
		cards[ x % M ].PB( x );
	}

	int res = 0;
	REP( i, 1, ( M + 1 ) / 2 )
	{
		auto &a = cards[i], &b = cards[ M - i ];
		const int d = abs( SZ( a ) - SZ( b ) );
		res += pairing( SZ( a ) < SZ( b ) ? b : a, d / 2 );
	}

	res += SZ( cards[0] ) / 2;
	if ( M % 2 == 0 )
	{
		res += SZ( cards[ M / 2 ] ) / 2;
	}

	REP( i, 1, ( M + 1 ) / 2 )
	{
		res += min( SZ( cards[i] ), SZ( cards[ M - i ] ) );
	}

	printf( "%d\n", res );
	fflush( stdout );

	return 0;
}

