        auto &v = buf[j];
        for(auto it=u.begin();it!=u.end();it++){
          if(it->second%2==1){
            bool po = false;
            for(auto jt=v.begin();jt!=v.end();jt++){
              if(jt->second%2==1){
                it->second--;
                jt->second--;
                count++;
                update = po = true;
                if(jt->second==0){
                  v.erase(jt);
                }
                break;
              }
            }
            if(!po){
              for(auto jt=v.begin();jt!=v.end();jt++){
                it->second--;
                jt->second--;
                count++;
                update = po = true;
                if(jt->second==0){
                  v.erase(jt);
                }
                break;
              }
