    int ans = 0;
    rep(i, M) {
        for (auto &j : nums[i]) {
            if (j.second % 2) {
                for (auto &k : nums[M-i]) {
                    if (i != M-i && 0 < k.second) {
                        j.second--;
                        k.second--;
                        ans++;
                        break;
                    }
