                        j.second--;
                        k.second--;
                        ans++;
                        break;
                    }
                }
            }
        }
    }

    for (auto &i : nums) {
        for (auto &j : i) {
            ans += j.second / 2;
        }
    }

    cout << ans << endl;
}

