	{
		for (size_t j = 0; j < 310; j++)
		{
			d[i][j] = INF;
		}
	}

	priority_queue < vector<ll>, vector < vector <ll>>, greater<vector<ll>>> q;
	q.push({0,0,st});
	while (!q.empty())
	{
		auto p = q.top();
		ll co = p[0];
		ll ti = p[1];
		ll cu = p[2];
		q.pop();

		if (d[cu][co] <= ti) continue;
		d[cu][co] = ti;

		for (auto v : es[cu])
		{
			ll to = v[0];
			ll y = v[1];
			ll m = v[2];
			if (y + co > c) continue;
			if (d[to][y + co] > ti + m) {
				q.push({ y + co,ti + m,to });
			}
		}
	}

	ll res = INF;
	for (size_t i = 0; i <= c; i++)
	{
		res = min(d[n][i], res);
	}
	return res;
}

