    rep(i, N) cin >> X[i];

    sort(all(X));

    vv<int> cnt_modM(M);

    for (int i = 0, j; i < N; i = j) {
        for (j = i + 1; j < N && X[j] == X[i]; ++j);
        cnt_modM[X[i] % M].push_back(j - i);
    }

    int ans = 0;

    // 0(mod. M)
    ans += accumulate(all(cnt_modM[0]), 0) / 2;

    // M/2 (mod. M) M=2n
    if (M % 2 == 0) {
        ans += accumulate(all(cnt_modM[M / 2]), 0) / 2;
    }

    rep(i, 1, (M + 1) / 2) {
        int cnt0 = accumulate(all(cnt_modM[i]), 0);
        int cnt1 = accumulate(all(cnt_modM[M - i]), 0);

        if (cnt0 > cnt1) {
            int selfpair = 0;
            for (int c : cnt_modM[i]) {
                selfpair += c / 2;
            }
            ans += cnt1 + min(selfpair, (cnt0 - cnt1) / 2);
        }
        else {
            int selfpair = 0;
            for (int c : cnt_modM[M - i]) {
                selfpair += c / 2;
            }
            ans += cnt0 + min(selfpair, (cnt1 - cnt0) / 2);
        }
    }

