void solve() {
    int n, m;
    cin >> n >> m;
    vector<int> x(n);
    for (int i=0; i<n; ++i) {
        cin >> x.at(i);
    }

    sort(x.begin(), x.end());
    vector<priority_queue<int, vector<int>, greater<int>>> modM(m);
    int cnt = 0;
    for (int i=0; i<n; ++i) {
        if (i > 0 && x.at(i) != x.at(i-1)) {
            modM.at(x.at(i-1)%m).push(cnt);
            cnt = 1;
        } else {
            ++cnt;
        }
    }
    modM.at(x.back()%m).push(cnt);
    int res = 0;
    while (!modM.at(0).empty()) {
        int cur = modM.at(0).top(); modM.at(0).pop();
        if (cur > 1) {
            ++res;
            if (cur-2 > 0) modM.at(0).push(cur-2);
        } else if (!modM.at(0).empty()) {
            int nx = modM.at(0).top(); modM.at(0).pop();
            ++res;
            if (nx-1 > 0) modM.at(0).push(nx-1);
        }
    }
    if (m%2 == 0) {
        while (!modM.at(m/2).empty()) {
            int cur = modM.at(m/2).top(); modM.at(m/2).pop();
            if (cur > 1) {
                ++res;
                if (cur-2 > 0) modM.at(m/2).push(cur-2);
            } else if (!modM.at(m/2).empty()) {
                int nx = modM.at(m/2).top(); modM.at(m/2).pop();
                ++res;
                if (nx-1 > 0) modM.at(m/2).push(nx-1);
            }
        }
    }
    for (int i=1; i<=m/2; ++i) {
        int i0 = i, i1= m-i;
        if (i0 == i1) continue;
        while (!modM.at(i0).empty() && !modM.at(i1).empty()) {
            int cur0 = modM.at(i0).top(); modM.at(i0).pop();
            int cur1 = modM.at(i1).top(); modM.at(i1).pop();
            ++res;
            if (cur0 > 1) modM.at(i0).push(cur0-1);
            if (cur1 > 1) modM.at(i1).push(cur1-1);
        }
    }
    for (int i=0; i<m; ++i) {
        if (!modM.at(i).empty()) {
            while (!modM.at(i).empty()) {
                int cur = modM.at(i).top(); modM.at(i).pop();
                if (cur > 1) {
                    ++res;
                    if (cur-2 > 1) modM.at(i).push(cur-2);
                }
            }
        }
    }
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

