        }
      }
      A[X[i]%M].push_back(index);
      //cout << X[i] << " " << X[i]%M << " " << index << endl;
      i += index-1;
    }
    int ans = 0;
    for(int i=(M%2 == 0 ? 0 : 1); i<=(M%2 == 0 ? M/2 : (M-1)/2); i++){
