        }else{
          if(ki_a < ki_b){
            ans += ki_a;
            ki_b -= ki_a;
            ki_a = 0;
            sum_a -= ki_a;
            sum_b -= ki_a;
            ans += (sum_a+sum_b)/2;
          }else{
            ans += ki_b;
            ki_a -= ki_b;
            ki_b = 0;
            sum_a -= ki_b;
            sum_b -= ki_b;
            ans += (sum_a+sum_b)/2;
