template<typename T = int> inline vector<vector<T>> in(int n, int m) { vector<vector<T>> xs(n, vector<T>(m)); rep(i, n) rep(j, m) cin >> xs[i][j]; return xs; }

int main(void) {
    int n, m;
    cin >> n >> m;
    VI counts(100010);
    VI mods(m);
    rep(i, n) {
        int x = in();
        counts[x]++;
        mods[x % m]++;
    }

    int ans = 0;
    VI use(m);
    rep(i, m) {
        int j = (m - i) % m;
        if (j < i) break;
        if (i == j) {
            int k = mods[i] / 2;
            use[i] = k * 2;
            ans += k;
        } else {
            int k = min(mods[i], mods[j]);
            use[i] = k;
            use[j] = k;
            ans += k;
        }
    }

    rep(i, m) {
        for (int j = i; j < 100010; j += m) {
            if (!use[i]) break;
            if (counts[j] && counts[j] % 2) {
                --counts[j];
                --use[i];
            }
        }

        for (int j = i; j < 100010; j += m) {
            if (!use[i]) break;
            if (counts[j]) {
                int r = min(use[i], counts[j]);
                use[i] -= r;
                counts[j] -= r;
            }
        }
    }

    for (auto x : counts) ans += x / 2;


    cout << ans << endl;

    return 0;
}

