      if(lsum - YY <= 0) ans += XX;
      else ans += XX - R;
    }
    l++;
    r--;
    // cout << "ans = "<<ans << endl;
  }
  if(l == r) {
    f(m/2);
  }
  f(0);

  cout << ans << endl;

}

