        if(x == 0 || x * 2 == M){
            ans += c[x] / 2;
            continue;
        }
        int y = M - x;
        if(c[x] > c[y]){
            swap(c[x], c[y]);
            swap(d[x], d[y]);
        }
        ans += c[x] + min(d[y], (c[y] - c[x]) / 2);
    }
    printf("%d\n", ans);
    return 0;
}

