			int tmp = 0;
			if (as[i].back() > as[m - i].back()) {
				for (int j = 0; j < (int)a[i].size(); j++) {
					tmp += a[i][j] / 2;
					a[i][j] %= 2;
				}
				ans += min(tmp, as[i].back() - c);

			} else if (as[i].back() < as[m - i].back()) {
				for (int j = 0; j < (int)a[m - i].size(); j++) {
					tmp += a[m - i][j] / 2;
					a[m - i][j] %= 2;
				}
				ans += min(tmp, as[m - i].back() - c);
			}
		}
	} else {
		for (int i = 1; i < m / 2; i++) {
			int c = min(as[i].back(), as[m - i].back());
			ans += c;
			if (c == 0) continue;
			int tmp = 0;
			if (as[i].back() > as[m - i].back()) {
				for (int j = 0; j < (int)a[i].size(); j++) {
					tmp += a[i][j] / 2;
					a[i][j] %= 2;
				}
				ans += min(tmp, as[i].back() - c);

			} else if (as[i].back() < as[m - i].back()) {
				for (int j = 0; j < (int)a[m - i].size(); j++) {
					tmp += a[m - i][j] / 2;
					a[m - i][j] %= 2;
				}
				ans += min(tmp, as[m - i].back() - c);
			}
		}
		ans += as[m / 2].back() / 2;
	}
	cout << ans << endl;
	return 0;
}

