ll modpow(ll a, ll n, ll mod) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

int get_cnt(int la, int totala, int lb, int totalb){

  if(la > lb){
    swap(la, lb);
    swap(totala, totalb);
  }

  if(lb <= totala){
    return (totala + totalb)/2;
  }else{
    return totala + (totalb-lb)/2;
  }
}

