	map<int, int> X;
	for (int i = 0; i < N; i++) {
		int x;
		cin >> x;
		X[x]++;
	}

	vector<vector<queue<int>>> rem(M, vector<queue<int>>(2));
	for (const auto &x : X) {
		rem[x.first % M][x.second & 1].emplace(x.second);
	}

	int ans = 0;
	for (int i = 1; i < (M + 1) / 2; i++) {

		while (!rem[i][1].empty() && !rem[M - i][1].empty()) {

			int a = rem[i][1].front();
			int b = rem[M - i][1].front();
			rem[i][1].pop();
			rem[M - i][1].pop();

			if (a > b) {
				ans += b;
				rem[i][0].emplace(a - b);
			}	
			else if (a < b) {
				ans += a;
				rem[M - i][0].emplace(b - a);
			}
			else ans += a;

		}

		while (rem[i][1].size() >= 2 && !rem[M - i][0].empty()) {

			int a1 = rem[i][1].front();
			rem[i][1].pop();
			int a2 = rem[i][1].front();
			rem[i][1].pop();
			int b = rem[M - i][0].front();
			rem[M - i][0].pop();

			ans += 2;
			if(a1 != 1) rem[i][0].emplace(a1 - 1);
			if(a2 != 1) rem[i][0].emplace(a2 - 1);
			if (b != 2) rem[M - i][0].emplace(b - 2);

		}

		while (rem[M - i][1].size() >= 2 && !rem[i][0].empty()) {

			int a1 = rem[M - i][1].front();
			rem[M - i][1].pop();
			int a2 = rem[M - i][1].front();
			rem[M - i][1].pop();
			int b = rem[i][0].front();
			rem[i][0].pop();

			ans += 2;
			if (a1 != 1) rem[M - i][0].emplace(a1 - 1);
			if (a2 != 1) rem[M - i][0].emplace(a2 - 1);
			if (b != 2) rem[i][0].emplace(b - 2);

		}

		while (!rem[i][0].empty()) {
			ans += rem[i][0].front() / 2;
			rem[i][0].pop();
		}	
		while (!rem[i][1].empty()) {
			ans += rem[i][1].front() / 2;
			rem[i][1].pop();
		}		
		while (!rem[M - i][0].empty()) {
			ans += rem[M - i][0].front() / 2;
			rem[M - i][0].pop();
		}		
		while (!rem[M - i][1].empty()) {
			ans += rem[M - i][1].front() / 2;
			rem[M - i][1].pop();
		}

	}

	while (rem[0][1].size() >= 2) {

		int a1 = rem[0][1].front();
		rem[0][1].pop();
		int a2 = rem[0][1].front();
		rem[0][1].pop();

		ans += 1;
		if (a1 != 1) rem[0][0].emplace(a1 - 1);
		if (a2 != 1) rem[0][0].emplace(a2 - 1);

	}

	while (!rem[0][0].empty()) {
		ans += rem[0][0].front() / 2;
		rem[0][0].pop();
	}
	while (!rem[0][1].empty()) {
		ans += rem[0][1].front() / 2;
		rem[0][1].pop();
	}

	if (M % 2 == 0) {
		while (rem[M/2][1].size() >= 2) {

			int a1 = rem[M/2][1].front();
			rem[M/2][1].pop();
			int a2 = rem[M/2][1].front();
			rem[M/2][1].pop();

			ans += 1;
			if (a1 != 1) rem[M/2][0].emplace(a1 - 1);
			if (a2 != 1) rem[M/2][0].emplace(a2 - 1);

		}

		while (!rem[M/2][0].empty()) {
			ans += rem[M/2][0].front() / 2;
			rem[M/2][0].pop();
		}
		while (!rem[M/2][1].empty()) {
			ans += rem[M/2][1].front() / 2;
			rem[M/2][1].pop();
		}
	}

	cout << ans << "\n";

	return 0;
}

