int N, K;
map<int, vector<int>> mp;

int cat(vector<int> v) {
	map<int, int> q;
	for (int i : v) ++q[i];

	int cnt = 0;
	for (auto p : q) {
		cnt += p.second / 2;
	}
	return cnt;
}

int sub(vector<int> a, vector<int> b) {
	if (a.size() < b.size()) return sub(b, a);
	int s = cat(a);
	int p = b.size();
	return min<int>((a.size() + b.size()) / 2, s + p);
}

int main() {
	cin >> N >> K;
	REP(i, 0, N) {
		int a;
		cin >> a;
		mp[a % K].push_back(a);
	}

	int sum = 0;
	REP(i, 0, K / 2 + 1) {
		int a = i % K;
		int b = (K - i) % K;
		if (a == b) {
			sum += mp[a].size() / 2;
		} else {
			sum += sub(mp[a], mp[b]);
		}
	}
	cout << sum << endl;

	return 0;
}

