            int s1 = 0;
            auto& m1 = nums[i];
            for(auto& p : m1){ s1 += p.second; }
            ans += s1 / 2;
        }else{
            if(i > (m - i) % m){ break; }
            if(!nums.count(i) || !nums.count((m - i) % m)){ continue; }
            auto& m1 = nums[i];
            auto& m2 = nums[(m - i) % m];
            int s1 = 0, s2 = 0;
            for(auto& p : m1){ s1 += p.second; }
            for(auto& p : m2){ s2 += p.second; }
            ans += min(s1, s2);
            if(s1 == s2){ continue; }
            if(s1 < s2){
                swap(s1, s2);
                swap(m1, m2);
            }
            vector<int> v;
            for(auto& p : m1){ v.push_back(p.second); }
            sort(v.begin(), v.end());
