            // println(v);
            // sort(v.begin(), v.end(), [](int a, int b){return (a % 2) < (b % 2); });
            for(int& i : v){
                if(i % 2 == 1){
                    s2--;
                    i--;
                    if(s2 == 0){
                        break;
                    }
                }
            }
            sort(v.begin(), v.end());
            for(int& i : v){
                int d = min(i, s2);
                s2 -= d;
                i -= d;
            }
            for(int& i : v){
                // cnt += i;
                ans += i / 2;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

