    } else if (m % 2 == 0 && i == m/2) {
      cnt += mods[m/2] / 2;
    } else {
      int l, s;
      if (mods[i] > mods[m-i]) {
        l = i;
        s = m - i;
      } else {
        l = m - i;
        s = i;
      }
      cnt += mods[s];
      cnt += min((mods[l] - mods[s]) / 2, num_pairs[l]);
    }
  }
  cout<<cnt<<endl;
}

