class BipartiteMatching {
  int V;
  vector<vector<int>> g;
  vector<int> match;
  vector<bool> used;
  bool dfs(int v) {
    used[v] = true;
    for (int u: g[v]) {
      int w = match[u];
      if (w < 0 || (!used[w] && dfs(w))) {
        match[v] = u; match[u] = v;
        return true;
      }
    }
    return false;
  }
public:
  BipartiteMatching (int v) : V(v), g(v), match(v), used(v) {}
  void add_edge(int u, int v) {
    g[u].push_back(v);
    g[v].push_back(u);
  }
  int maximum_matching(void) {
    int res = 0;
    fill (ALL(match), -1);
    REP(v, V) {
      if (match[v] < 0) {
        fill (ALL(used), 0);
        if (dfs(v)) res++;
      }
    }
    return res;
  }
};

int main(){
  int N, M;
  cin >> N >> M;
  vector<int> X(N);
  REP(i,N) cin >> X[i];
  sort(ALL(X));

  vector<vector<int>> mod(M);
  REP(i,N) mod[X[i] % M].push_back(i);

  BipartiteMatching bm(N);
  REP(i,N) {
    auto itr = equal_range(ALL(X), X[i]);
    for(int j = itr.first - X.begin(); j < itr.second - X.begin(); ++j) {
      if(j <= i) continue;
      bm.add_edge(i, j);
      //cout << i << " " << j << endl;
    }
    for(int e: mod[(M - X[i] % M) % M]) {
      if(e <= i) continue;
      if(X[e] == X[i]) continue;
      bm.add_edge(i, e);
      //cout << i << " " << e << endl;
    }
  }
  int res = bm.maximum_matching();
  cout << res << endl;
  return 0;
}

