int Sub(const vi& a,const vi& b){
	map<int,int> c,d;
	int ret=0,e=0,f=0,p=a.size(),q=b.size();
	for(auto v:a)
		c[v]++;
	for(auto kv:c)
		if(kv.second%2==1)
			e++;
	for(auto v:b)
		d[v]++;
	for(auto kv:d)
		if(kv.second%2==1)
			f++;
	p-=e;
	q-=f;
	if(e<f){
		swap(e,f);
		swap(p,q);
	}
	ret+=f;
	e-=f;
	f=0;
	int k=min(e,q);
	ret+=k;
	q-=k;
	ret+=p/2+q/2;
	return ret;
}

