      if(A[0] == 0 || B[0] == 0) break;
      res++;
      A[0]--;
      B[0]--;
      A.push_back(A[0]);
      A.pop_front();
      B.push_back(B[0]);
      B.pop_front();
    }
    while(!A.empty()) res += A[0] / 2, A.pop_front();
    while(!B.empty()) res += B[0] / 2, B.pop_front();
    return res;
  };

  int ans = 0;
  for(int i=0;i<M;i++){
    int a = i;
    int b = (M - i) % M;
    if(a <= b) ans += calc(a, b);
  }

  cout<<ans<<endl;

  return 0;
}

