    VI counts(10010);
    rep(i, n) {
        int x = in();
        counts[x]++;
    }

    // qs[mod] {count, x}
    vector<priority_queue<PII, VPII, greater<PII>>> qs(m);
    // q2 {count, mod}
    priority_queue<PII, VPII, greater<PII>> q2;

    rep(i, 10010) if (counts[i]) {
        int count = counts[i];
        int mod = i % m;
        qs[mod].push(MP(count, i));
        q2.push(MP(count, mod));
    }

    int ans = 0;

    while (q2.size()) {
        PII q = q2.top();
        q2.pop();
        int i = q.snd % m;
        int j = (m - i + m) % m;

        if (!qs[i].size() || !qs[j].size()) continue;
        if (i == j && qs[i].size() < 2) continue;

        PII a = qs[i].top();
        if (a.fst != q.fst) continue;

        PII b = qs[j].top();
        qs[i].pop();
        qs[j].pop();

        --a.fst;
        --b.fst;
        ++ans;

        if (a.fst) {
            qs[i].push(a);
            q2.push(MP(a.fst, i));
        }
        if (b.fst) {
            qs[j].push(b);
            q2.push(MP(b.fst, j));
        }
    }

    rep(i, m) {
        while (qs[i].size()) {
            PII a = qs[i].top();
            qs[i].pop();
            ans += a.fst / 2;
        }
    }

    cout << ans << endl;

    return 0;
}

