int solve(int p, int q) //p<q
{
	priority_queue<pii> q1, q2;

	map<int,int> m1, m2;
	for (int x:vec[p]) {
		++m1[x];
	}
	for (int x:vec[q]) {
		++m2[x];
	}

	for (const pii pr:m1) {
		q1.push(mp(pr.se & 1, pr.se));
	}

	for (const pii pr:m2) {
		q2.push(mp(pr.se & 1, pr.se));
	}

	int res = 0;

	while (q1.size()>0&&q2.size()>0) {
		pii p1 = q1.top(); q1.pop();
		pii p2 = q2.top(); q2.pop();
		++res;
		p1.fi ^= 1;
		p2.fi ^= 1;
		p1.se--;
		p2.se--;
		if (p1.se) {
			q1.push(p1);
		}
		if (p2.se) {
			q2.push(p2);
		}		
	}

	while (!q1.empty()) {
		pii p1 = q1.top(); q1.pop();
		res += p1.se / 2;
	}

	while (!q2.empty()) {
		pii p2 = q2.top(); q2.pop();
		res += p2.se / 2;
	}

	return res;
}

