    {
        if (i * 2 == m)
        {
            ans += mods[i] / 2;
            used[i] = mods[i];
        }
        else
        {
            int y = min(mods[i], mods[m - i]);
            ans += y;
            used[i] = used[m - i] = y;
        }
    }
    for (int i = 1; i < m; i++)
    {
        int z = (mods[i] - used[i]) / 2;
        ans += min(z, pairs[i]);
    }
