const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll N, M;
vector<ll> X;
void solve(){
  vector<ll> E[100010];
  rep(i, N) E[X[i] % M].pb(X[i]);
  rep(i, M){
    vector<ll> EX = E[i];
    sort(EX.begin(), EX.end());
    vector<ll> EY = EX;
    EX.erase(unique(EX.begin(), EX.end()), EX.end());
    revrep(i, EY.size()){
      if(i == 0){
        EY[i] = -1;
        continue;
      }
      if(EY[i] != EY[i-1]){
        EY[i] = -1;
      }
    }
    rep(i, EY.size()){
      if(EY[i] != -1){
        EX.pb(EY[i]);
      }
    }
    E[i] = EX;
  }
  ll ans = 0;
  ans += E[0].size() / 2;
  if(M % 2 == 0){
    ans += E[M/2].size() / 2;
  }
  for(ll i = 1; i <= (M-1) / 2; i++){
    ll a = i;
    ll b = M - i;
    ll al = E[a].size();
    ll bl = E[b].size();
    ans += min(al, bl);
    if(al < bl){
      for(ll j = b; j < bl - 1; j++){
        if(E[b][j] == E[b][j+1]){
          ans++;
          j++;
        }
      }
    }else{
      for(ll j = a; j < al - 1; j++){
        if(E[a][j] == E[a][j+1]){
          ans++;
          j++;
        }
      }
    }
  }
  cout << ans << endl;
}

int main(){
  cin >> N >> M;
  X.resize(N);
  rep(i, N) cin >> X[i];
  solve();
}

