void _main() {
    int N, M;
    cin >> N >> M;
    vector<int> X(N), cnt(100010, 0);
    REP (i, N) {
        cin >> X[i];
        cnt[X[i]]++;
    }
    vector<vector<int>> cntM(M, vector<int>());
    REP (i, 100010) if (cnt[i] > 0) {
        cntM[i % M].push_back(cnt[i]);
    }
    REP (i, M) sort(cntM[i].begin(), cntM[i].end());
    int ans = accumulate(cntM[0].begin(), cntM[0].end(), 0LL) / 2;
    if (M >= 2 && M % 2 == 0) ans += accumulate(cntM[M / 2].begin(), cntM[M / 2].end(), 0LL) / 2;
    FOR (i, 1, (M + 1) / 2) {
        int suma = 0, sumb = 0;
        REP (j, cntM[i].size()) suma += cntM[i][j];
        REP (j, cntM[M - i].size()) sumb += cntM[M - i][j];
        int a = i, b = M - i;
        if (suma > sumb) {
            swap(a, b);
            swap(suma, sumb);
        }
        int tmp = 0, odd = 0;
        REP (j, cntM[b].size()) {
            if (cntM[b][j] % 2 == 1) {
                odd++;
                cntM[b][j]--;
            }
        }
        if (odd >= suma) {
            ans += suma;
            REP (j, cntM[b].size()) ans += cntM[b][j] / 2;
        } else {
            suma -= odd;
            ans += suma;
            REP (j, cntM[b].size()) {
                if (tmp < 0) {
                    ans += cntM[b][j] / 2;
                } else if (tmp + cntM[b][j] >= suma) {
                    ans += (cntM[b][j] - (suma - tmp)) / 2;
                    tmp = -1;
                } else {
                    tmp += cntM[b][j];
                }
            }
        }
    }
    cout << ans << endl;
}

