int main()
{
	int n, m;
	scanf("%d %d", &n, &m);

	vector<int> arr(n);
	vector<int> mod(m);
	map<int, int> count;

	for (int i = 0; i < n; i++)
	{
		scanf("%d", &arr[i]);

		mod[arr[i] % m]++;
		count[arr[i]]++;
	}	

	vector<vector<int>> modset(m);

	for (auto& c : count)
		modset[c.first % m].push_back(c.second);

	int ans = 0;

	for (int i = 0; i <= m - i; i++)
	{
		if (i == 0 || i == m - i)
		{
			ans += mod[i] / 2;
			continue;
		}

		ans += min(mod[i], mod[m - i]);

		//남는 짜투리 같은 것끼리 매칭하는 경우 확인
		auto& mset = (mod[i] > mod[m - i]) ? modset[i] : modset[m - i];
		sort(all(mset));

		int r = min(mod[i], mod[m - i]);

		for (auto& m : mset)
		{
			if (m > r)
			{
				m -= r;
				r = 0;
			}
			else
			{
				r -= m;
				m = 0;
			}

			ans += m / 2;
		}
	}

	printf("%d\n", ans);

	return 0;
}

