using namespace std;

const int N = 100 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n, m;
int a[N];

bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> a[i];

    return true;
}

void solve() {
    auto ans = 0;
    map<int, int> f, g, h;

    for (int i = 0; i < n; ++i)
        ++(a[i] % m == 0 ? ans : f[a[i]]);

    ans /= 2;

    for (auto p : f) {
        ans += p.second / 2;

        if (p.second >= 2)
            h[p.first % m] += p.second / 2;

        if (p.second & 1)
            ++g[p.first % m];
    }

    for (int k = 1; k + k <= m; ++k)
        if (k + k < m) {
            auto res = 0;

            for (int t = 0; t <= min(g[k], g[m - k]); ++t)
                res = max(res, t + min(h[m - k], (g[k] - t) / 2) + min(h[k], (g[m - k] - t) / 2));

            ans += res;
        } else {
            ans += g[k] / 2;
        }

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

