ll sumVll(vll &v) {
	ll ans = 0;
	for (ll n : v) {
		ans += n;
	}
	return ans;
}

void solve() {
	ll N;
	cin >> N;
	ll M;
	cin >> M;
	vector<ll> A(N);
	map<ll, ll> mp;
	rep(i, N) {
		cin >> A[i];
		mp[A[i]]++;
	}

	ll modZero = 0;
	ll modHalfM = 0;
	vvll count(M, vll(0));
	auto begin = mp.begin(), end = mp.end();
	for (auto iter = begin; iter != end; iter++) {
		// iter->first: key, iter->second: value
		ll num = iter->first;
		ll mod = num % M;
		if (mod == 0) {
			modZero += iter->second;
		}
		else if (M % 2 == 0 && mod == M / 2) {
			modHalfM += iter->second;
		}
		else {
			count[mod].push_back(iter->second);
		}
	}

	ll result = modZero / 2 + modHalfM / 2;

	reps(i, 1, M / 2) {
		vll groupA = count[i];
		vll groupB = count[M - i];

		ll sumA = sumVll(groupA);
		ll sumB = sumVll(groupB);

		if (sumA < sumB) {
			swap(sumA, sumB);
			swap(groupA, groupB);
		}

		result += sumB;

		ll pair = 0;
		ll single = 0;
		for (ll n : groupA) {
			if (n % 2 > 0) {
				single++;
				pair += (n - 1) / 2;
			}
			else {
				pair += n / 2;
			}
		}

		ll last = sumB;
		last -= single;
		if (last > 0) {
			ll eracePair = (last + 2 - 1) / 2;
			pair -= eracePair;
		}
		result += pair;
	}

	cout << result << endl;
}

