template<class Type>
Type solve(Type res = Type()){
    int N,M; cin >> N >> M;
    vector<ll> X(N); for(auto& in:X) cin >> in;
    map<ll,ll> mp;
    for(auto& v:X) mp[v%M]++;

    for(ll l = 0; l < M;l++){
        ll r = M-l;

        ll cnt1 = mp[l],cnt2 = mp[r];

        if(l == 0){
            res += cnt1/2;
            continue;
        }
        if(l == r){
            res += cnt1/2;
            continue;
        }

        if(cnt1 > cnt2) swap(cnt1,cnt2);

        ll T = 0;
        for(ll x = 0; x <= cnt1; x++){
            T = max(T,x + (cnt1-x)/2 + (cnt2-x)/2);
        }
        res += T;
    }
    res /= 2;
    return res;
}
