vector< P > G[100001];

int main(){
  scanf("%d %d",&N,&M);
  for(int i=0;i<N;i++){
    scanf("%d",&X[i]);
    Y[ X[i] ]++;
  }
  for(int i=1;i<=100000;i++){
    if(Y[i]==0)continue;
    G[ i%M ].push_back( P( Y[i], i ) );
  }

  for(int i=0;i<M;i++){
    sort(G[i].begin(),G[i].end());
    reverse(G[i].begin(),G[i].end());
  }

  int ans=0;
  for(int i=1;i<M;i++){
    int pos=i;
    int target=M-i;
    if(target<=pos)break;
    while(1){
      if(G[target].empty() || G[pos].empty())break;
      ans++;
      P pa=G[target].back();
      P pb=G[pos].back();
      pa.first--;
      pb.first--;
      G[target].pop_back();
      if(pa.first>0)G[target].push_back(pa);
      G[pos].pop_back();
      if(pb.first>0)G[pos].push_back(pb);
    }
  }

  int count=0, zcnt=0;
  for(int i=1;i<M;i++){
    for(int j=0;j<(int)G[i].size();j++){
      P p=G[i][j];
      ans+=p.first/2;
      count+= (p.first%2);
    }
  }


  for(int i=0;i<(int)G[0].size();i++)
    zcnt+=G[0][i].first;

  int tmp =min(count,zcnt);
  ans+=tmp;
  zcnt-=tmp;
  ans+=zcnt/2;

  cout<<ans<<endl;
  return 0;
}

