    for (auto it : mp) {
        int idx = it.first % m;
        md[idx % m] += it.second;
        cnt[idx] += it.second / 2;
    }
    int ans = 0;
    rep(i, 0, (m + 1) / 2) {
        if (i == 0 || (m % 2 == 0 && i == m / 2 - 1)) {
            ans += md[i] / 2;
        } else {
            ans += min(md[i], md[m - i]);
            int amari = abs(md[i] - md[m - i]);
            if (md[i] > md[m - i]) {
                ans += min(cnt[i], amari / 2);
            } else {
                ans += min(cnt[m - i], amari / 2);
            }
        }
    }
    if (m % 2 == 0) {
        ans += md[m / 2] / 2;
    }
    cout << ans << "\n";
}

