struct Edge {
    ll to, rev;
    long double cap;
    Edge(ll _to, long double _cap, ll _rev) {
        to = _to;
        cap = _cap;
        rev = _rev;
    }
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

void add_edge(Graph &G, ll from, ll to, long double cap, bool revFlag,
              long double revCap) {
    G[from].push_back(Edge(to, cap, (ll)G[to].size()));
    if(revFlag)
        G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve() {
    ll n, m;
    cin >> n >> m;
    vec<ll> x(n);
    map<ll, ll> mp;
    vec<ll> con(m, 0);
    vec<ll> pairs(m, 0);
    REP(i, n) {
        cin >> x[i];
        con[x[i] % m]++;
        mp[x[i]]++;
    }
    for(auto i : mp) {
        pairs[i.first % m] += i.second / 2;
    }

    ll ans = 0;
    REP(i, m) {
        int j = (m - i) % m;
        if(i > j)
            break;
        else if(i == j) {
            ans += con[i] / 2;
        } else {
            ll t = min(con[i], con[j]);
            ans += t;
            ans += min((con[i] - t) / 2, pairs[i]);
            ans += min((con[j] - t) / 2, pairs[j]);
        }
    }
    cout << ans << en;
}

