const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll N, M;
vector<ll> X;
void solve(){
  vector<ll> E[100010];
  rep(i, N) E[X[i] % M].pb(X[i]);

  rep(t, M){
    sort(E[t].begin(), E[t].end());
    map<ll, ll> cnt;
    rep(i, E[t].size()){
      cnt[E[t][i]]++;
    }
    vector<ll> EX, EY;
    revrep(i, E[t].size()){
      if(i == 0 || (i != 0 && E[t][i-1] != E[t][i])){
        if(cnt[E[t][i]] % 2){
          EX.pb(E[t][i]);
        }else{
          EY.pb(E[t][i]);
        }
      }else{
        EY.pb(E[t][i]);
      }
    }
    sort(EX.begin(), EX.end());
    sort(EY.begin(), EY.end());
    E[t].resize(0);
    rep(i, EX.size()){
      E[t].pb(EX[i]);
    }
    rep(i, EY.size()){
      E[t].pb(EY[i]);
    }
  }
  ll ans = 0;
  ans += E[0].size() / 2;
  if(M % 2 == 0){
    ans += E[M/2].size() / 2;
  }
  for(ll i = 1; i <= (M-1) / 2; i++){
    ll a = i;
    ll b = M - i;
    ll al = E[a].size();
    ll bl = E[b].size();
    ans += min(al, bl);
    if(al < bl){
      for(ll j = al; j < bl - 1; j++){
        if(E[b][j] == E[b][j+1]){
          ans++;
          j++;
        }
      }
    }else{
      for(ll j = bl; j < al - 1; j++){
        if(E[a][j] == E[a][j+1]){
          ans++;
          j++;
        }
      }
    }
  }
  cout << ans << endl;
}

