            ll srem = mo[i] - j, lrem = mo[M - i] - j;
            tmp = max(tmp, j + min(srem / 2, snum[i]) + min(lrem / 2, snum[M - i]));
        }
        ans += tmp;
    }
    cout << ans << "\n";
}

