    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    map<int, vec<int>> y;
    each (i, x) y[i % m].push_back(freq[i]);

    each (i, x) i %= m;
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());

    map<int, int> z;
    each (i, y) each (j, i.second) z[i.first] += j;

    int r = (z[0] / 2);
    z.erase(0);
    y.erase(0);
    if (m % 2 == 0) {
      r += (z[m / 2] / 2);
      z.erase(m / 2);
      y.erase(m / 2);
    }

    // cout << y << endl;
    // cout << z << endl;
    // cout << x << endl;

    each (_i, x) {
      if (_i == 0 || _i * 2 == m) continue;
      int i = _i;
      int j = m - _i;
      unless (z[i] < z[j]) swap(i, j);
      int p = (z[j] - z[i]) / 2;
      r += z[i];
      // cout << make_pair(i, j) << ", " << make_pair(z[i], z[j]) << ' ' << p << endl;
      z[j] -= z[i];
      z.erase(i);
      y.erase(i);
      each (k, y[j]) {
        int mn = min(p, k / 2);
        p -= mn;
        r += mn;
        z[j] -= mn * 2;
        k -= mn * 2;
      }
    }

    cout << r << endl;
  }

  return 0;
}

