                for(int k = 0; m * k + j <= 100000; ++k) {
                    int z = m * k + j;
                    int c = mp[z];
                    if(cnt == 0) break;
                    if(c >= 2) {
                        int d = c / 2;
                        if(cnt >= d) {
                            ans += d; cnt -= d;
                        } else {
                            ans += (d - cnt); cnt = 0;
                        }
                    }
                    if(cnt == 0) break;
