template<typename T> vector< pair< T, int > > groupby(const vector< T > &vec) {
    vector< pair< T, int > > ret;
    int piv = -1;
    for (auto &e: vec) {
        if (piv == -1 or ret[piv].first != e) ++piv, ret.emplace_back(make_pair(e, 1));
        else ++(ret[piv].second);
    }
    return ret;
}

