signed main() {

    SS(int, N, M);
    SV(int, X, N);
    SORT(X);
    auto gb = groupby(X);

    vector<int> alone(M, 0), dup(M, 0);
    EACH(e, gb) {
        int val, qua;
        tie(val, qua) = e;
          dup[val % M] += qua >> 1;
        alone[val % M] += qua &  1;
    }

    int res = dup[0] + (alone[0] >> 1);
    if (M % 2 == 0) res += dup[M / 2] + (alone[M / 2] >> 1);
    REP(i, 1, M / 2 + 1) {
        int j = M - i;
        if (i == j) continue;
        int mn = min(alone[i], alone[j]);
        res += mn;
        alone[i] -= mn;
        alone[j] -= mn;
    }
    REP(i, 1, M) {
        if (M % 2 == 0 and i == M / 2) continue;
        if (alone[i] > 0) {
            int mn = min(alone[i] >> 1, dup[M - i]);
            res += mn << 1;
            alone[i] -= mn * 2;
            dup[M - i] -= mn;
        }
        res += dup[M - i];
    }
    // print(alone);
    // print(dup);
    print(res);

}

