		}
		else{
			if (s[i] > s[j]){
				swap(i,j);
			}
			while (s[i]+1 < s[j]){
				auto it = mp[j].rbegin();
				if (*it==1)break;
				int a=*it;
				mp[j].erase(mp[j].find(a));
				s[j]-=2;
				if(a)mp[j].insert(a-2);
				ans ++;
			}
			ans += min(s[i],s[j]);
			s[i] = s[j] = 0;
			mp[i].clear();
			mp[j].clear();
		}
	}

	cout<<ans<<endl;



