		sum[a[i] % M]++;
	}	
	for(int i = 0;i <= M / 2;i++)
	{
		if((i == 0) || ((M % 2 == 0) && (i == M / 2))) ans += sum[i] / 2;
		else
		{
			int j = i;
			if(sum[i] < sum[M - i]) j = M - i;
