const int N=5e5+5;
int cnt[N],c[N],sum[N],n,m,res;
int main(){
	scanf("%d%d",&n,&m);
	for(R int i=1,x;i<=n;++i)scanf("%d",&x),++c[x],++cnt[x%m];
	fp(i,1,1e5)sum[i%m]+=c[i]>>1;
	for(R int i=1,x;i<m-i;++i){
		x=min(cnt[i],cnt[m-i]);
		res+=x,cnt[i]-=x,cnt[m-i]-=x;
	}
