int cnt[100005];
int data[100005];
int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout<<fixed<<setprecision(20);
    ll N,M,ans = 0;
    cin >> N >> M;
    map<ll,ll> mp;
    rep(i,N){
        int a;
        cin >> a;
        mp[a]++;
        a%=M;
        cnt[a]++;
    }
    for(int i=0;i<=M;i++){
        data[i] = cnt[i];
    }
    /*
    for(int i=0;i<=M;i++){
        cout << i << " num = " << cnt[i] << endl;
    }
    */
    for(int i=0;i<=M;i++){
        if(i==0){
            ans += cnt[0]/2;
            cnt[0] = 0;
            continue;
        }
        if(i==M-i){
            ans += cnt[i]/2;
            cnt[i] = 0;
            continue;
        }
        //iについてペアとなるのはM-i;
        int t = min(cnt[i],cnt[M-i]);
        ans += t;
        cnt[i] -= t;
        cnt[M-i] -= t;
        //cout << cnt[i] << " " << cnt[M-i] << endl;
        //この操作によって、とりあえずペアは作り終えた
        //後は残った数同士で同じ値があったらペアを作る
        //cout << "i = " << i << " " << cnt[i] << endl;
    }

    for(auto x:mp){
        //x.first は値
        //x.secondはその値がいくつ最初存在したかを表す。
        //現在いくつ使われたかを調べる
        //cnt[now%M]には現在の値が後何回使えるかが入っている
        int now = x.first;
        int num = x.second;
        //cout << "now = " << now << " num = " << num << " now left num = " << cnt[now%M] << endl;
        if(cnt[now%M]>=2 && num >=2){
            int t = min(cnt[now%M]/2,num/2);
            ans += t;
            cnt[now%M]-=t;
        }
    }
    /*for(int i=0;i<=M;i++){
        cout << i << " num = " << cnt[i] << endl;
    }
    */
    cout << ans << endl;
}

