using ldb = long double;

int main() {
	int N, M; cin >> N >> M;
	vector<int> cnt(M), pac(M);
	map<int, int> mp;
	for (int i = 0; i < N; i++) {
		int x; cin >> x;
		cnt[x % M]++;
		mp[x]++;
	}

	for (auto p : mp) {
		pac[p.first % M] += p.second / 2;
	}


	ll ans = 0;
	for (int i = 0; i <= M / 2; i++) {
		if (i == 0) ans += cnt[0] / 2;
		else if (i < M / 2) {
			int low = min(cnt[i], cnt[M - i]), up = max(cnt[i], cnt[M - i]);
			ans += low;
			ans += min((up - low) / 2, pac[up]);
		}
		else if (i == M / 2) {
			if (M % 2 == 0)ans += cnt[i] / 2;
			else {
				int low = min(cnt[i], cnt[M - i]), up = max(cnt[i], cnt[M - i]);
				ans += low;
				ans += min((up - low) / 2, pac[up]);
			}
		}
		//cout <<"i="<<i<< " ans=" << ans << endl;
	}

	cout << ans << endl;
}

