int main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);
  int n,m;
  cin>>n>>m;
  vector<int> a(n);
  rep(i,n) cin>>a[i];
  vv<int> vs(m);
  for(int x:a) vs[x%m].pb(x);
  int re=vs[0].size()/2;
  //cout<<vs[0]<<endl;
  reps(i,1,m){
    if(m-i<=i) break;
    vector<int> &v=vs[i];
    vector<int> &w=vs[m-i];
    //cout<<v<<w<<same(w)<<endl;
    if(v.size()>w.size()) swap(v,w);
    re+=v.size()+max<int>((w.size()-v.size())/2,same(w));
  }
  if(m%2){
    //cout<<vs[m/2]<<endl;
    re+=vs[m/2].size()/2;
  }
  cout<<re<<endl;
  return 0;
}

