int modM_solo[100008];
int modM_pair[100008];
int getmin(int a,int b) {
	if(a>b) return b;
	return a;
}
int add(int a,int b,int c,int d) {
	int ret=getmin(b,d);
	b-=ret;
	d-=ret;
	if(b>0) {
		int temp=getmin(b,c*2);
		ret+=temp+a+(c*2-temp)/2;
	} else {
		int temp=getmin(d,a*2);
		ret+=temp+c+(a*2-temp)/2;
	}
	return ret;
}
