//--------------------------------------------------------------------

void solve() {
    i64 N = RD();
    i64 M = RD();

    static i64 cnts[100'001] {};
    REP(_, N) {
        i64 a = RD();
        ++cnts[a];
    }

    // M で割った余りごとの枚数リスト
    vector<vector<i64>> v(M);
    REP(a, SIZE(cnts)) {
        i64 r = a % M;
        i64 k = cnts[a];
        if(k > 0)
            v[r].emplace_back(k);
    }
    DBG(v);

    i64 ans = 0;

    FOR(i, 1, (M+1)/2) {
        i64 r1 = i;
        i64 r2 = M-i;
        i64 s1 = ALL(accumulate, v[r1], 0LL);
        i64 s2 = ALL(accumulate, v[r2], 0LL);
        if(s1 < s2) {
            swap(r1, r2);
            swap(s1, s2);
        }

        i64 cur = 0;
        i64 remain = s2;
        // 奇数枚を優先して倍数ペアを作る
        REP(j, SIZE(v[r1])) {
            if(remain == 0) break;
            if(v[r1][j]%2 != 0) {
                ++cur;
                --remain;
                --v[r1][j];
            }
        }
        // 作れるだけ倍数ペアを作る
        REP(j, SIZE(v[r1])) {
            if(remain == 0) break;
            i64 k = min(remain, v[r1][j]);
            cur += k;
            remain -= k;
            v[r1][j] -= k;
        }
        ASSERT(remain == 0);  // s1 >= s2 なので
        // 残ったものでequalペアを作る
        REP(j, SIZE(v[r1])) {
            cur += v[r1][j] / 2;
        }

        ans += cur;
    }

    // r=0 および M が偶数の場合の r=M/2 は例外処理
    // 単に総数を2で切り捨て除算したものが最大ペア数
    ans += ALL(accumulate, v[0], 0LL) / 2;
    if(M%2 == 0)
        ans += ALL(accumulate, v[M/2], 0LL) / 2;

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

