void solve() {
  int N, M;
  cin >> N >> M;
  vector<vector<int>> vec(M);
  REP(i,N) {
    int X; cin >> X;
    vec[X % M].push_back(X);
  }
  REP(i,M) sort(ALL(vec[i]));
  vector<int> one(M), two(M);
  REP(i,M) {
    const int n = vec[i].size();
    REP(j,n) {
      if (j < n - 1 && vec[i][j] == vec[i][j+1]) {
        ++j;
        ++two[i];
      }
      else ++one[i];
    }
  }
  int res = 0;
  REP(i,(M+2)/2) {
    if (i * 2 == M) {
      res += two[i] + one[i] / 2;
    }
    else if (i == 0) {
      res += two[i] + one[i] / 2;
    }
    else {
      const int a = min(one[i], one[M-i]);
      one[i] -= a; one[M-i] -= a; res += a;
      const int b = min(one[i], two[M-i] * 2);
      one[i] -= b; two[M-i] -= (b+1)/2; res += b;
      const int c = min(two[i] * 2, one[M-i]);
      two[i] -= (c+1)/2; one[M-i] -= c; res += c;
      res += two[i] + two[M-i];
    }
    // cout << res << endl;
  }
  cout << res << endl;
  return;
}

#include<bits/stdc++.h>
using namespace std;

int main() {
    int64_t N, M;
    cin >> N >> M;
    vector<int64_t> X(N);
    for (int64_t& x : X) {
        cin >> x;
    }

    const int64_t max_value = *max_element(X.begin(), X.end());

    vector<int64_t> num(max_value + 1, 0);
    for (int64_t x : X) {
        num[x]++;
    }

    //card[i][j] := カードの値をMで割ったあまりがiで、カード数を2で割った余りがｊであるもの
    vector<vector<stack<int64_t>>> card(M, vector<stack<int64_t>>(2));
    for (int64_t i = 0; i <= max_value; i++) {
        if (num[i] == 0) {
            continue;
        }
        card[i % M][num[i] % 2].push(num[i]);
    }

    //マッチングを考えていく
    int64_t ans = 0;
    while (true) {
        bool change = false;
        for (int64_t i = 0; i < M; i++) {
            //奇数番目のものは奇数番目のもの同士でくっつければ良い
            while (!card[i][1].empty()) {
                int64_t top = card[i][1].top();
                card[i][1].pop();

                int64_t pair = (M - i) % M;

                //card[M - i][1]に要素があればそれと結合
                if (!card[pair][1].empty()) {
                    int64_t inv = card[pair][1].top();
                    card[pair][1].pop();
                    ans++;
                    change = true;

                    if (inv != 1) {
                        card[pair][0].push(inv - 1);
                    }
                } else if (!card[pair][0].empty()) {
                    //偶数側から貰ってくる
                    int64_t inv = card[pair][0].top();
                    card[pair][0].pop();
                    ans++;
                    change = true;

                    //一つ減るので奇数側に追加
                    card[pair][0].push(inv - 1);
                }

                //一つ減るので偶数側に追加(1だったら消滅)
                if (top != 1) {
                    card[i][0].push(top - 1);
                }
            }
        }
        if (!change) {
            break;
        }
    }

    //同じカード同士で結合
    for (int64_t i = 0; i < M; i++) {
        for (int64_t j = 0; j < 2; j++) {
            while (!card[i][j].empty()) {
                ans += card[i][j].top() / 2;
                card[i][j].pop();
            }
        }
    }

    cout << ans << endl;
}

