int solve(multiset<int> a, multiset<int> b){
  int aod = 0, bod = 0;
  for(auto aa: a) {
    //cout <<"a" <<  aa ;
    if(aa % 2 == 1) aod++;
  }
  for(auto bb: b){
    //cout <<"b" <<  bb;
    if(bb % 2 == 1) bod++;
  }
//  cout <<endl;

  if(aod > bod){
    swap(aod, bod); swap(a, b);
  }
  //aod <= bod

  int bipaired = aod;

  multiset<int> ca, cb, ccb;
  for(auto aa : a){
    ca.insert(aa/2*2);
  }

  int suma = 0;
  for(auto aa: ca){
    suma += aa;
  }//cout << endl;

  int tmpb = bipaired;
  //cout <<"B"; for(auto bb:b)cout <<bb <<","; cout << endl;
  for(auto& bb : b){
    if(tmpb > 0 && bb%2==1) {
      cb.insert(bb-1);
      tmpb--;
    }else{
      cb.insert(bb);
    }
  }
  //cout <<"CB"; for(auto bb:cb)cout <<bb <<","; cout << endl;

  int bpar = 0;
  //cout << suma << endl;
  for(auto& bb : cb){
    if(suma > 0 && bb%2==1) {
      ccb.insert(bb-1);
      suma--;
      bpar ++;
    }else{
      ccb.insert(bb);
    }
  }

  //cout <<"CCB"; for(auto bb:ccb)cout <<bb <<","; cout << endl;

  int res = 0;
  for(auto bb: ccb){
    res += bb / 2;
  }

  //cout << bipaired << "," << suma << "B" << bpar << endl;
  //cout << "R" << res << endl;

  return bipaired + (suma / 2) + res + bpar;
}
