int solve(const VI& a, const VI& b) {
  if (a.size() < b.size()) {
    return solve(b, a);
  }
  // |a| >= |b|
  int s = b.size();
  int rem = a.size() - s;
  int idpair = 0;
  int cur = -1;
  REP(i, 0, a.size()) {
    if (a[i] == cur) {
      idpair++;
      cur = -1;
    } else {
      cur = a[i];
    }
  }
  return rem <= 2 * idpair ? s + rem / 2 : s + idpair;
}

