			ans += cnt[i] / 2;
			cnt[i] %= 2;
		} else {
			const int common = min(cnt[i], cnt[m - i]);
			ans += common;
			cnt[i] -= common;
			cnt[m - i] -= common;
		}
	}

	printf("%d\n", ans);

	return 0;
