#define MIN(a,b) ((a)<(b)?(a):(b))

int cmp(const void *a,const void *b){
  return *(int *)a-*(int *)b;
}

void run(void){
  int n,m;
  scanf("%d%d",&n,&m);
  int *x=(int *)calloc(n,sizeof(int));
  int i;
  for(i=0;i<n;i++) scanf("%d",x+i);
  int *cnt=(int *)calloc(m,sizeof(int));
  for(i=0;i<n;i++) if(x[i]) cnt[x[i]%m]++;
  int ans=cnt[0]/2;
  cnt[0]%=2;
  for(i=1;i<m-i;i++){
    int k=MIN(cnt[i],cnt[m-i]);
    ans+=k;
    cnt[i]-=k;
    cnt[m-i]-=k;
  }
  if(m%2==0){
    ans+=cnt[m/2]/2;
    cnt[m/2]%=2;
  }
  qsort(x,n,sizeof(int),cmp);
  i=0;
  while(i+1<n){
