import java.util.NoSuchElementException;

public class Main {
	private static void solve() {
		int n = nei();
		int m = nei();
		ArrayList<Integer> xs = new ArrayList<Integer>();
		for (int i = 0; i < n; i++) {
			xs.add(nei());
		}
		Collections.sort(xs, (a, b) -> a % m - b % m);
		int[] ns = new int[m];
		int[] ss = new int[m];
		boolean skp = false;
		for (int i = 0; i < n; i++) {
			int x = xs.get(i);
			int g = x % m;
			ns[g]++;
			if (!skp) {
				if (i < n - 1 && x == xs.get(i + 1)) {
					ss[g]++;
					skp = true;
				}
			} else
				skp = false;
		}
		int ans = 0;
		ans += ns[0] >> 1;
		if (m % 2 == 0) {
			int mid = m / 2;
			ans += ns[mid] >> 1;
			for (int i = 1; i < mid; i++) {
				int j = m - i;
				int maxp = min(ns[i], ns[j]);
				ans += maxp;
				ns[i] -= maxp;
				ns[j] -= maxp;
				while (ns[i] >= 2 && ss[i] > 0) {
					ns[i] -= 2;
					ss[i]--;
					ans++;
				}
				while (ns[j] >= 2 && ss[j] > 0) {
					ns[j] -= 2;
					ss[j]--;
					ans++;
				}
			}
		} else {
			int mid = (m + 1) >> 1;
			for (int i = 1; i < mid; i++) {
				int j = m - i;
				int maxp = min(ns[i], ns[j]);
				ans += maxp;
				ns[i] -= maxp;
				ns[j] -= maxp;
				while (ns[i] >= 2 && ss[i] > 0) {
					ns[i] -= 2;
					ss[i]--;
					ans++;
				}
				while (ns[j] >= 2 && ss[j] > 0) {
					ns[j] -= 2;
					ss[j]--;
					ans++;
				}
			}
		}
		out(ans);
	}

