	class Pair implements Comparable<Pair> {
		int value;
		int cnt;

		Pair(int value, int cnt) {
			this.value = value;
			this.cnt = cnt;
		}

		public int compareTo(Pair s) {
			return -(cnt % 2);
		}

		public String toString() {
			return "(" + value + ", " + cnt + ")";
		}
	}

	int MAX = 100100;
	public void solve() {
		int N = in.nextInt();
		int M = in.nextInt();
		int[] X = in.nextIntArray(N);

		int[] cnt1 = new int[MAX+10];
		for (int i = 0; i < N; i++) {
			cnt1[X[i]]++;
		}

		PriorityQueue<Pair>[] pq = new PriorityQueue[M];
		for (int i = 0; i < M; i++) {
			pq[i] = new PriorityQueue<>();
		}
		for (int i = 0; i < MAX + 10; i++) {
			if (cnt1[i] != 0) {
				pq[i%M].add(new Pair(i, cnt1[i]));
			}
		}

		int res = 0;
		for (int i = 0; i < M; i++) {
			int opp = (M - i) % M;
			if (pq[i].isEmpty()) continue;
			Pair p1 = pq[i].poll();
			if (pq[opp].isEmpty()) {
				pq[i].add(p1);
				continue;
			}

			Pair p2 = pq[opp].poll();
			if (p1.cnt % 2 == 0 && p2.cnt % 2 == 0) continue;

			p1.cnt--;
			p2.cnt--;
			if (p1.cnt != 0) pq[i].add(p1);
			if (p2.cnt != 0) pq[opp].add(p2);

			res++;
		}

		int[] cnt2 = new int[M];
		for (int i = 0; i < M; i++) {
			while (!pq[i].isEmpty()) {
				Pair next = pq[i].poll();
				cnt2[i] += next.cnt;
			}
			res += cnt2[i] / 2;
		}
		System.out.println(res);
	}

