		int[] mod=new int[m];
		HashMap<Integer,Integer> map=new HashMap<>();
		for(int i=0; i<n; i++){
			int tmp=sc.nextInt();
			int mt=tmp%m;
			x[tmp]++;
			mod[mt]=Math.max(x[tmp],mod[mt]);
