			this.value = value;
			this.cnt = cnt;
		}

		public int compareTo(Pair s) {
			if (cnt % 2 == s.cnt % 2) 
				return cnt - s.cnt;
			else if (cnt % 2 != 0)
				return -1;
			else 
				return 1;
		}

