public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int n = In.ni();
        int m = In.ni();
        int[] c = new int[m];
        int[] x = In.ni(n);
        RadixSort.sort(x);
        int[] s = new int[m];
        int t = 1;
        for (int i = 0; i < n; i++) {
            c[x[i] % m]++;
            if (i > 0) {
                if (x[i] == x[i - 1]) {
                    t++;
                } else {
                    s[x[i - 1] % m] += t >> 1;
                    t = 1;
                }
            }
        }
        s[x[n - 1] % m] += t >> 1;
        int a = 0;
        for (int i = 0, h = m >> 1; i <= h; i++) {
            if (i == m - i || i == 0) {
                a += c[i] >> 1;
            } else {
                if (c[i] < c[m - i]) {
                    a += c[i];
                    a += min((c[m - i] - c[i]) >> 1, s[m - i]);
                } else {
                    a += c[m - i];
                    a += min((c[i] - c[m - i]) >> 1, s[i]);
                }
            }
        }
        out.append(a);
    }
}


