import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.InputMismatchException;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class Main {
	InputStream is;

	int __t__ = 1;
	int __f__ = 0;
	int __FILE_DEBUG_FLAG__ = __f__;
	String __DEBUG_FILE_NAME__ = "src/D2";

	FastScanner in;
	PrintWriter out;

	class Pair implements Comparable<Pair> {
		int value;
		int cnt;

		Pair(int value, int cnt) {
			this.value = value;
			this.cnt = cnt;
		}

		public int compareTo(Pair s) {
			if (cnt % 2 == s.cnt % 2) 
				return cnt - s.cnt;
			else if (cnt % 2 != 0)
				return -1;
			else 
				return 1;
		}

		public String toString() {
			return "(" + value + ", " + cnt + ")";
		}
	}

	int MAX = 100100;
	public void solve() {
		int N = in.nextInt();
		int M = in.nextInt();
		int[] X = in.nextIntArray(N);

		int[] cnt1 = new int[MAX+10];
		for (int i = 0; i < N; i++) {
			cnt1[X[i]]++;
		}

		PriorityQueue<Pair>[] pq = new PriorityQueue[M];
		for (int i = 0; i < M; i++) {
			pq[i] = new PriorityQueue<>();
		}
		for (int i = 0; i < MAX + 10; i++) {
			if (cnt1[i] != 0) {
				pq[i%M].add(new Pair(i, cnt1[i]));
			}
		}

		int res = 0;
		for (int i = 0; i < M; i++) {
			while (!pq[i].isEmpty()) {
				int opp = (M - i) % M;
				Pair p1 = pq[i].poll();
				if (pq[opp].isEmpty()) {
					pq[i].add(p1);
					break;
				}

				Pair p2 = pq[opp].poll();
				if (p1.cnt % 2 == 0 && p2.cnt % 2 == 0) {
					pq[i].add(p1);
					pq[opp].add(p2);
					break;
				}

				p1.cnt--;
				p2.cnt--;
				if (p1.cnt != 0) pq[i].add(p1);
				if (p2.cnt != 0) pq[opp].add(p2);

				res++;
			}
		}

		for (int i = 0; i < M; i++) {
			while (!pq[i].isEmpty()) {
				Pair next = pq[i].poll();
				res += next.cnt / 2;
			}
		}
		System.out.println(res);
	}

	public void run() {
		if (__FILE_DEBUG_FLAG__ == __t__) {
			try {
				is = new FileInputStream(__DEBUG_FILE_NAME__);
			} catch (FileNotFoundException e) {
				e.printStackTrace();
			}
