public class Main {
  private static final int MAX_X = 100_000;

  private static int solve(int n, int m, int[] xs) {
    int[] count = new int[MAX_X + 1];
    for (int x : xs) {
      count[x]++;
    }
    int[] countMod = new int[m];
    int[] countModPair = new int[m];
    for (int i = 0; i <= MAX_X; i++) {
      countMod[i % m] += count[i];
      countModPair[i % m] += (count[i] / 2) * 2;
    }

    int answer = 0;
    answer += countMod[0] / 2;
    for (int i = 1; i <= m/2; i++) {
      int j = m - i;
      if (i != j) {
        if (countMod[i] >= countMod[j]) {
          answer += countMod[j];
          answer += Math.min(countMod[i] - countMod[j], countModPair[i]) / 2;
        } else {
          answer += countMod[i];
          answer += Math.min(countMod[j] - countMod[i], countModPair[j]) / 2;
        }
      } else {
        answer += countMod[i] / 2;
      }
    }
    return answer;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int m = reader.nextInt();
    int[] xs = reader.nextIntArray(n);
    out.println(solve(n, m, xs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

