	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception{
		Scanner io = new Scanner(System.in);
		//IO io = new IO(new FileInputStream("max.txt"));
		int n = io.nextInt();
		int m = io.nextInt();
		ArrayList<Integer>[] b = new ArrayList[m];
		for(int i=0;i<m;i++) {
			b[i] = new ArrayList<>();
		}
		for(int i=0;i<n;i++) {
			int x = io.nextInt();
			b[x % m].add(x);
		}
		for(int i=0;i<m;i++) {
			b[i].sort(null);
		}
		int ans = 0;
		int[] used = new int[m];
		for(int i=0;i<=m/2;i++) {
			if (i == 0 || i * 2 == m) {
				used[i]++;
				ans += b[i].size() / 2;
			}else{
				ArrayList<Integer> l1 = b[i];
				ArrayList<Integer> l2 = b[m-i];
				used[i]++;
				used[m-i]++;
				if (l1.size() < l2.size()) {
					ArrayList<Integer> temp = l1;
					l1 = l2;
					l2 = temp;
				}
				//l1 is larger
				int pair = 0;
				for(int j=0;j<l1.size()-1;j++) {
					if (l1.get(j) == l1.get(j+1)) {
						pair++;
						j++;
					}
				}
				ans += Math.min((l1.size() - l2.size()) / 2, pair) + l2.size();
			}
		}
		for(int i=0;i<m;i++) {
			if (used[i] != 1) {
				throw new RuntimeException();
			}
		}
		System.out.println(ans);
	}

