			b[x % m].add(x);
		}
		for(int i=0;i<m;i++) {
			b[i].sort(null);
		}
		int ans = 0;
		for(int i=0;i<=m/2;i++) {
			if (i == 0 || i * 2 == m) {
				ans += b[i].size() / 2;
			}else{
				ArrayList<Integer> l1 = b[i];
				ArrayList<Integer> l2 = b[m-i];
				if (l1.size() < l2.size()) {
					ArrayList<Integer> temp = l1;
					l1 = l2;
					l2 = temp;
				}
				//l1 is larger
				HashMap<Integer, Integer> hm = new HashMap<>();
				for(Integer x: l1) {
					Integer count = hm.get(x);
					if (count == null) {
						count = 0;
					}
					hm.put(x, count + 1);
				}
				int pair = 0;
				for(Integer x: hm.values()) {
					pair += x / 2;
				}
				ans += Math.min((l1.size() - l2.size()) / 2, pair) + l2.size();
			}
		}
		if (ans > n / 2) {
			throw new RuntimeException();
		}
		System.out.println(ans);
	}

}

class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() { this(System.in);}
	public IO(InputStream source) { super(System.out); this.in = source;}
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private static boolean isNewLine(int c) { return c == '\n' || c == '\r';}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
	public boolean hasNextLine() { while(hasNextByte() && isNewLine(buffer[ptr])) ptr++; return hasNextByte();}
	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while(isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}
	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}
	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public int[] nextIntArray(int n) { int[] a = new int[n]; for(int i=0;i<n;i++) a[i] = nextInt(); return a;}
	public long[] nextLongArray(int n) { long[] a = new long[n]; for(int i=0;i<n;i++) a[i] = nextLong(); return a;}
	public double[] nextDoubleArray(int n) { double[] a = new double[n]; for(int i=0;i<n;i++) a[i] = nextDouble(); return a;}
	public void nextIntArrays(int[]... a) { for(int i=0;i<a[0].length;i++) for(int j=0;j<a.length;j++) a[j][i] = nextInt();}
	public int[][] nextIntMatrix(int n,int m) { int[][] a = new int[n][]; for(int i=0;i<n;i++) a[i] = nextIntArray(m); return a;}
	public char[][] nextCharMap(int n,int m) { char[][] a = new char[n][]; for(int i=0;i<n;i++) a[i] = nextCharArray(m); return a;}
	public void close() { super.close(); try {in.close();} catch (IOException e) {}}
}

import java.io.*;
import  java.util.*;

import static java.lang.System.in;

class Main{
    static HashMap<Integer,Integer>[] rec;
    static int[] count;
    static int n,m;
    public static void main(String[] args)throws IOException{
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt(); m = sc.nextInt();
        count = new int[m];
        rec = new HashMap[m];
        for(int i=0;i<m;i++) rec[i]=new HashMap<>();
        for(int i=0;i<n;i++){
            int x = sc.nextInt();
            int pos = x%m;
            count[pos]++;
            rec[pos].put(x,rec[pos].getOrDefault(x,0)+1);
        }
        int ans = 0;
        for(int i=1;i<=(m-1)/2;i++){
            ans += help(i);
        }
        ans += count[0]/2;
        if(m%2==0) ans += count[m/2]/2;
        System.out.println(ans);
    }
    static int help(int i){
        int j = m-i;
        if(count[i]==count[j]) return count[i];
        int remain = Math.abs(count[i]-count[j]);
        HashMap<Integer,Integer> map = count[i]<count[j]?rec[j]:rec[i];
        int ans = Math.min(count[i],count[j]);
        for(int w:map.keySet()){
            if(remain==0) break;
            int cur = Math.min(remain,map.get(w))/2;
            ans += cur;
            remain -= cur*2;
        }
        return ans;
    }
}

import java.util.*;
import java.io.PrintWriter;
public class Main{
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int m=sc.nextInt();
		int[] x=new int[100001];
		int[] mod=new int[m];
		HashMap<Integer,Integer> map=new HashMap<>();
		for(int i=0; i<n; i++){
			int tmp=sc.nextInt();
			int mt=tmp%m;
			x[tmp]++;
			mod[mt]=Math.max(x[tmp],mod[mt]);
			if(map.containsKey(mt)){
				map.put(mt,map.get(mt)+1);
			}else{
				map.put(mt,1);
			}
		}
		long ans=0;
		if(map.containsKey(0)){
			ans=map.get(0)/2;
		}
		for(int i=1; i<=(m-1)/2; i++){
			if(!map.containsKey(i) || !map.containsKey(m-i)){
				continue;
			}
			long ii=map.get(i);
			long mi=map.get(m-i);
			ans+=Math.min(ii,mi);
			if(ii>mi){
				ans+=Math.min((ii-mi)/2,mod[i]/2);
			}else{
				ans+=Math.min((mi-ii)/2,mod[m-i]/2);
			}
		}
		if(m%2==0 && map.containsKey(m/2)){
			ans+=map.get(m/2)/2;
		}
		System.out.println(ans);
	}
}

