    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        int[] count = new int[m];
        int[] pair = new int[m];
        boolean[] has = new boolean[100001];
        for (int i = 0; i < n; i++) {
            int x = in.nextInt();
            if (has[x]) {
                pair[x % m]++;
            }
            has[x] = !has[x];
            count[x % m]++;
        }
        long ans = 0;
        for (int i = 0; i <= m / 2; i++) {
            if (i * 2 == m || i == 0) {
                ans += count[i] / 2;
            } else {
                int j = count[i] < count[m - i] ? i : m - i;
                int k = count[i] < count[m - i] ? m - i : i;
                ans += count[j] + Math.min((count[k] - count[j]) / 2, pair[k]);
            }
        }
        out.println(ans);
    }

