public class Main {

	static final Reader in = new Reader();
	static final PrintWriter out = new PrintWriter(System.out,false);
	static boolean debug = false;

	static void solve(){
		int n = in.nextInt();
		int m = in.nextInt();
		int[] x = new int[n];
		int[] c = new int[100001];
		int[] cnt = new int[m];
		int[] pcnt = new int[m];

		for (int i=0; i<n; i++) {
			x[i] = in.nextInt();
			cnt[x[i]%m]++;
			c[x[i]]++;
		}

		for (int i=0; i<n; i++) {
			pcnt[x[i]%m] += c[x[i]]/2;
		}

		int ans = 0;

		// dump(cnt);dump(pcnt);

		for (int i=1; i<(m+1)/2; i++) {
			int p = Math.min(cnt[i], cnt[m-i]);
			ans += p;
			ans += Math.min((cnt[i] - p)/2, pcnt[i]);
			ans += Math.min((cnt[m-i] - p)/2, pcnt[i]);
		}
		if (m%2 == 0) {
			int p = pcnt[m/2];
			ans += p;
		}

		out.println(ans);
	}

