  where T : IEquatable<T>
    {
        var ret = new List<Pair<T, int>> { new Pair<T, int>(list[0], 1) };
        for (var i = 1; i < list.Count; i++)
            if (ret.Last().v1.Equals(list[i]))
                ret[ret.Count - 1].v2++;
            else ret.Add(new Pair<T, int>(list[i], 1));
        return ret;
    }
