public class Solver
{
	public void Solve()
	{
		int MAX = 100000;
		int N = GetInt();
		int M = GetInt();
		int[] X = GetInts(N);

		int[] grpcnt = new int[M];
		int[] cnt = new int[MAX + 1];
		for(int i = 0; i < N; i++)
		{
			grpcnt[X[i] % M]++;
			cnt[X[i]]++;
		}

		int ans = grpcnt[0] / 2;
		if(M % 2 == 0)
			ans += grpcnt[M/2] / 2;

		for(int i = 1; i < (M + 1)/2; i++)
		{
			int a = i;
			int b = M - i;
			if(grpcnt[a] < grpcnt[b])
				swap(ref a, ref b);

			ans += grpcnt[b];

			int rest = grpcnt[a] - grpcnt[b];
			for(int j = a; j <= MAX; j += a)
			{
				int diff = Math.Min(rest, cnt[j]) / 2;
				ans += diff;
				rest -= diff * 2;
				if(rest < 2)
					break;
			}
		}

		Console.WriteLine(ans);
	}

	private void swap(ref int x, ref int y)
	{
		int tmp = x;
		x = y;
		y = tmp;
	}
}


