                B[j] = ss[M - i][j];
            if (B.Length > A.Length)
            {
                int[] temp = B;
                B = A;
                A = temp;
            }
#if TEST2
            Console.WriteLine("TEST2");
            foreach (var a in A)
                Console.Write("{0} ", a);
            Console.WriteLine();
            foreach (var b in B)
                Console.Write("{0} ", b);
            Console.WriteLine();
#endif
            ans += B.Length;
            int c = 0;
            int t = 1;
            for (int j = 1; j < A.Length; j++)
            {
                if (A[j] != A[j - 1])
                {
                    c += t / 2;
                    t = 1;
                }
                else
                    t++;
            }
            ans += Math.Min((A.Length - B.Length) / 2, c);
        }
#if TEST1 || TEST2
        Console.WriteLine("ANS");
#endif
        Console.WriteLine(ans);
    }
}

