        // 使用する変数をここに書く
        // string S;
        // int a;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int[] x = sc.nextInt(n);
            int ans = 0;
            int[] lsmod = new int[m];
            int[] lsmodSame = new int[m];
            HashMap<int, int> map = new HashMap<int, int>();
            for (int i = 0; i < n; i++)
            {
                lsmod[x[i] % m]++;
                map[x[i]]++;
            }
            foreach (var i in map)
            {
                if (i.Value > 1)
                {
                    lsmodSame[i.Key % m] += (i.Value / 2);
                }
            }
            for (int modA = 0; modA < m; modA++)
            {
                int modB = (m - modA) % m;
                int tmp = Math.Min(lsmod[modA], lsmod[modB]);
                if (lsmod[modA] > lsmod[modB])
                {
                    tmp += Math.Min((lsmod[modA] - lsmod[modB]) / 2, lsmodSame[modA])*2;
                }
                else
                {
                    tmp += Math.Min((lsmod[modB] - lsmod[modA]) / 2, lsmodSame[modB])*2;

                }
                ans += tmp;
            }

            Console.WriteLine(ans / 2);
        }
    }
