    public void Solve()
    {
        int num, m;
        Input.Make(out num, out m);
        var xs = Input.ar;Array.Sort(xs);
        var ct = new int[m];
        var md = new int[m];
        for (var i = 0; i < num; i++)
            md[xs[i] % m]++;
        foreach (var x in RLEncoding(xs))
            ct[x.v1 % m] += x.v2 / 2;
        var res = 0L;
        for(var i=1;i<(m+1)/2;i++)
        {
            var c = Min(md[i], md[m - i]);
            md[i] -= c;md[m - i] -= c;
            res += c;
        }
        if (m % 2 == 0)
            res += md[m / 2] / 2;
        res += md[0] / 2;
        for (var i = 1; i < m; i++)
            res += Min(ct[i], md[i] / 2);
        WriteLine(res);
    }
    public static List<Pair<T, int>> RLEncoding<T>(IList<T> list)
  where T : IEquatable<T>
    {
        var ret = new List<Pair<T, int>> { new Pair<T, int>(list[0], 1) };
        for (var i = 1; i < list.Count; i++)
            if (ret.Last().v1.Equals(list[i]))
                ret[ret.Count - 1].v2++;
            else ret.Add(new Pair<T, int>(list[i], 1));
        return ret;
    }
}

