{
    public static string Result(double d) => d.ToString("0.####################", System.Globalization.CultureInfo.InvariantCulture);
    #endregion
    public static string Result(bool b) => b ? "Yes" : "No";
    private object Calc()
    {
        N = cr;
        M = cr;
        X = cr.Repeat(N);
        var gc = X.GroupCount();
        int res = 0;
        var ones = NewArray(M, () => new Dictionary<int, int>());
        var zeros = NewArray(M, () => new Dictionary<int, int>());

        {
            var m0 = 0;
            var m2 = 0;
            foreach (var (n, c) in gc)
            {
                var mod = n % M;
                if (mod == 0)
                    m0 += c;
                else if (mod * 2 == M)
                    m2 += c;
                else if (c % 2 != 0)
                    ones[mod][n] = c;
                else
                    zeros[mod][n] = c;
            }
            res += (m0 >> 1) + (m2 >> 1);
        }

        for (int mm = 1; mm < ((M + 1) >> 1); mm++)
        {
            var m = mm;
            var n = M - m;
            var l = ones[m];
            var s = ones[n];
            if (s.Count > l.Count)
            {
                (l, s) = (s, l);
                (n, m) = (m, n);
            }
            res += s.Count;
            foreach (var p in s)
                if (p.Value > 1)
                    zeros[n].Add(p.Key, p.Value - 1);

            var e = l.GetEnumerator();
            var ix = s.Count;
            while (--ix >= 0)
            {
                e.MoveNext();
                var p = e.Current;
                if (p.Value > 1)
                    zeros[m].Add(p.Key, p.Value - 1);
            }
            while (e.MoveNext())
            {
                var p = e.Current;
                if (e.MoveNext())
                {
                    var p2 = e.Current;
                    if (zeros[n].Count > 0)
                    {
                        var c = zeros[n].First();
                        res += 2;
                        if (c.Value > 2)
                            zeros[n][c.Key] = c.Value - 2;
                        else
                            zeros[n].Remove(c.Key);
                    }
                    if (p.Value > 1)
                        zeros[m].Add(p.Key, p.Value - 1);
                    if (p2.Value > 1)
                        zeros[m].Add(p2.Key, p2.Value - 1);
                }
                else
                {
                    if (p.Value > 1)
                        zeros[m].Add(p.Key, p.Value - 1);
                    break;
                }
            }

            foreach (var v in zeros[m].Values)
                res += v >> 1;
            foreach (var v in zeros[n].Values)
                res += v >> 1;
        }

        return res;
    }
    int N;
    int M;
    int[] X;
