	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		//public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		int N, M;
		int[] X;
		void Read()
		{
			sc.Read(out N, out M);
			if (M % 2==0) throw new Exception();
			X = sc.ReadMany<int>();
		}
		void SolveOne()
		{
			var s = new int[M];
			var p = new int[M];
			Array.Sort(X);
			for (var i = 0; i < N;)
			{
				var j = i + 1;
				while (j < N && X[j] == X[i]) j++;
				var m = X[i] % M;
				s[m] += (j - i) % 2;
				p[m] += (j - i) / 2;
				i = j;
			}
			var ans = (p[0] * 2 + s[0]) / 2;
			if (M % 2 == 0) ans += (p[M / 2] * 2 + s[M / 2]) / 2;
			for (var m = 1; m < M - m; m++)
			{
				var n = M - m;
				var x = Min(p[m], s[n] / 2);
				ans += 2 * x;
				p[m] -= x;
				s[n] -= 2 * x;
				x = Min(p[n], s[m] / 2);
				ans += 2 * x;
				p[n] -= x;
				s[m] -= 2 * x;
				ans += p[m] + p[n] + Min(s[m], s[n]);
			}
			pr.WriteLine(ans);
		}
	}
