		int[] X;
		void Read()
		{
			sc.Read(out N, out M);
			X = sc.ReadMany<int>();
		}
		void SolveOne()
		{
			if (M < 100) throw new Exception();
			var s = new int[M];
			var p = new int[M];
			Array.Sort(X);
			for (var i = 0; i < N;)
			{
				var j = 1;
				while (i + j < N && X[i + j] == X[i]) j++;
				var m = X[i] % M;
				s[m] += j % 2;
				p[m] += j / 2;
				i += j;
			}
			var ans = (p[0] * 2 + s[0]) / 2;
			if (M % 2 == 0) ans += (p[M / 2] * 2 + s[M / 2]) / 2;
			for (var m = 1; m < M - m; m++)
			{
				var n = M - m;
				var x = Min(p[m], s[n] / 2);
				ans += 2 * x;
				p[m] -= x;
				s[n] -= 2 * x;
				x = Min(p[n], s[m] / 2);
				ans += 2 * x;
				p[n] -= x;
				s[m] -= 2 * x;
				ans += p[m] + p[n] + Min(s[m], s[n]);
			}
			pr.WriteLine(ans);
		}
	}
