class SegmentTree3 : ISegmentTree
{
	public const long Unit = Func.InfL;
	public readonly Func<long, long, long> Operator = Math.Min;
	int N2;
	long[] seg, unif;
	public SegmentTree3(int N) : this(new long[N]) { }
