namespace codefestival_2016_final_d
{
	class Program
	{
		static void Main(string[] args)
		{
			int[] x = Console.ReadLine().Split().Select(int.Parse).ToArray();
			int[] a = Console.ReadLine().Split().Select(int.Parse).ToArray();
			int[] remain = new int[x[1]];
			Dictionary<int, int>[] cards = new Dictionary<int, int>[x[1]];
			for (int i = 0; i < x[1]; i++) cards[i] = new Dictionary<int, int>();
			for (int i = 0; i < x[0]; i++)
			{
				int n = a[i] % x[1];
				remain[n]++;
				if (!cards[n].ContainsKey(a[i])) cards[n][a[i]] = 0;
				cards[n][a[i]]++;
			}
			int ret = 0;
			for (int i = 0; i < x[1]; i++)
			{
				int min = 0;
				if (i == 0 || i == x[1] - i)
				{
					min = remain[i] / 2;
				}
				else
				{
					min = Math.Min(remain[i], remain[x[1] - i]);
				}
				ret += min;
				remain[i] -= min; remain[(x[1] - i) % x[1]] -= min;
				int same = 0;
				foreach (var card in cards[i])
				{
					same += card.Value / 2;
				}
				ret += Math.Min(remain[i] / 2, same);
				remain[i] -= Math.Min(remain[i] / 2, same) * 2;
			}
			Console.WriteLine(ret);
		}
	}
}

