public class Program
{
    private int N, M;
    private int[] X;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        X = sc.IntArray();
        var count = new int[100001];
        var countModM = new int[M];
        foreach (int i in X)
        {
            count[i]++;
            countModM[i % M]++;
        }


        // mod Mでいくつ同じ数字のペアが作れるか
        var countPair = new int[M];

        for (int i = 0; i <= 100000; i++)
        {
            countPair[i % M] += count[i] / 2;
        }

        int ans = 0;

        ans += countModM[0] / 2;
        if (M % 2 == 0)
        {
            ans += countModM[M / 2] / 2;
        }

        for (int i = 1; i * 2 < M; i++)
        {
            int min = Math.Min(countModM[i], countModM[M - i]);
            ans += min;
            countModM[i] -= min;
            countModM[M - i] -= min;
            ans += Math.Min(countPair[i], countModM[i] / 2);
            ans += Math.Min(countPair[M - i], countModM[M - i] / 2);
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

