		{
			sc.Read(out N, out M);
			X = sc.ReadMany<int>();
		}
		void SolveOne()
		{
			//if (M < 100) throw new Exception();
			var s = new int[M];
			var p = new int[M];
			Array.Sort(X);
			for (var i = 0; i < N;)
			{
				var j = 1;
				while (i + j < N && X[i + j] == X[i]) j++;
				var m = X[i] % M;
				s[m] += j % 2;
				p[m] += j / 2;
				i += j;
			}
			var ans = (p[0] * 2L + s[0]) / 2;
			if (M % 2 == 0) ans += (p[M / 2] * 2L + s[M / 2]) / 2;
			for (var i = 1; i < M - i; i++)
			{
				var m = i;
				var n = M - i;
				var zn = s[n] + 2 * p[n];
				var zm = s[m] + 2 * p[m];
				if (zn < zm)
				{
					Swap(ref m, ref n);
					Swap(ref zm, ref zn);
				}
				while (p[n] > 0 && zm <= zn - 2)
				{
					ans++;
					p[n]--;
					zn -= 2;
				}
				ans += zm;
				/*var n = M - m;
