        PriorityQueue<int>[] ss = new PriorityQueue<int>[M];
        ss = ss.Select(s => new PriorityQueue<int>(0, p)).ToArray();
        foreach (var x in X)
            ss[x % M].Push(x);

        //答えの計算
        long ans = 0;
        ans += ss[0].Count / 2; //余りが0のグループと、
        if (M % 2 == 0) //余りがM / 2のグループは別処理
            ans += ss[M / 2].Count / 2;
        for (int i = 1; i <= (M / 2) - (M % 2 == 0 ? 1 : 0); i++)
        {
            int[] A = new int[ss[i].Count];
            int[] B = new int[ss[M - i].Count];
            for (int j = 0; j < ss[i].Count; j++)
            {
                A[j] = ss[i].Top;
                ss[i].Pop();
            }
            for (int j = 0; j < ss[M - i].Count; j++)
            {
                B[j] = ss[M - i].Top;
                ss[M - i].Pop();
            }
            if (B.Length > A.Length)
            {
                int[] temp = B;
                B = A;
                A = temp;
            }
            int c = 0;
            int t = 1;
