            {
                if (A[j] != A[j - 1])
                {
                    c += t / 2;
                    t = 1;
                }
                else
                    t++;
            }
            c += t / 2;
            ans += B.Length + Math.Min((A.Length - B.Length) / 2, c);
        }
        Console.WriteLine(ans);
    }

