static class CodeJam
{
    static int Solve(int N, int M, int[] X)
    {
        var mod = new int[M];
        var dic = new Dictionary<int, int>();
        foreach (int x in X)
        {
            ++mod[x % M];
            if (!dic.ContainsKey(x)) { dic[x] = 0; }
            ++dic[x];
        }
        int cnt = mod[0] / 2;
        mod[0] %= 2;
        for (int i = 1; i * 2 < M; ++i)
        {
            int min = Math.Min(mod[i], mod[M - i]);
            cnt += min;
            mod[i] -= min;
            mod[M - i] -= min;
        }
        if (M % 2 == 0)
        {
            cnt += mod[M / 2] / 2;
            mod[M / 2] %= 2;
        }
        foreach (var pair in dic)
        {
            int m = pair.Key % M;
            int min = Math.Min(mod[m], pair.Value);
            int c = min / 2;
            cnt += c;
            mod[m] -= c * 2;
        }
        return cnt;
    }

    static void Main(string[] args)
    {
        int[] V = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int[] X = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        Console.WriteLine(Solve(V[0], V[1], X));
    }
}

