    class Solver
    {
        private long N;
        private long M;
        private List<long> X;

        public void Solve()
        {
            Cin(out N, out M);
            Cin(out X);

            X.Sort();

            // mod M, count
            long[] c = new long[M + 1];
            long[] s = new long[M + 1];

            long before = -1;
            for (int i = 0; i < N; i++)
            {
                c[X[i] % M]++;
                if (before == X[i])
                {
                    s[X[i] % M]++;
                    before = -1;
                    continue;
                }

                before = X[i];
            }

            long ans = c[0] / 2;

            if (M % 2 == 0)
            {
                ans += c[M / 2] / 2;
            }

            long max = (M + 1) / 2;
            for (long i = 1; i < max; i++)
            {
                long x = i;
                long y = M - i;
                // c[x] >= c[y]
                if (c[y] > c[x])
                {
                    var tmp = x;
                    x = y;
                    y = tmp;
                }


                ans += c[y];
                c[x] -= c[y];
                c[y] -= c[y];
                ans += Math.Min(s[x], c[x] / 2);
                ans += Math.Min(s[y], c[y] / 2);
            }

            Console.WriteLine(ans);
        }
    }
}

