    class Solver
    {
        private long N;
        private long M;
        private List<long> X;

        public void Solve()
        {
            Cin(out N, out M);
            Cin(out X);

            X.Sort();

            // mod M, count
            long[] c = new long[M + 1];
            long[] s = new long[M + 1];

            long before = -1;
            for (int i = 0; i < N; i++)
            {
                c[X[i] % M]++;
                if (before == X[i])
                {
                    s[X[i] % M]++;
                    before = -1;
                }

                before = X[i];
            }

            long ans = c[0] / 2;

            if (M % 2 == 0)
            {
                ans += c[M / 2] / 2;
            }

            long max = M % 2 == 0 ? M / 2 : M / 2 + 1;
            for (int i = 1; i < max; i++)
            {
                long more = c[i] >= c[M - i] ? i : M - i;
                long less = c[i] < c[M - i] ? i : M - i;
                ans += c[less];
                ans += Math.Min(s[more], (c[more] - c[less]) / 2);
            }

            Console.WriteLine(ans);
        }
    }
