		}
	}
	PrintDebug("%v\n", nums[:101])
	PrintDebug("%v\n", modNums[:101])
	PrintDebug("%v\n", modOddNums[:101])

	ans := modNums[0] / 2
	// i+j == m
	ub := m / 2
	if m%2 == 0 {
		ub--
	}
	for i := 1; i <= ub; i++ {
		j := m - i
		var minNum int // i, jで個数が少ない方の個数
		var lmod int   // i, jのうち個数が多いほう
		if modNums[i] < modNums[j] {
			minNum = modNums[i]
			lmod = j
		} else {
			minNum = modNums[j]
			lmod = i
		}
		// 小さい方を答えに加算
