func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	mm := map[int]int{}
	xm := map[int]int{}
	erase := map[int]int{}
	for i := 0; i < n; i++ {
		x := getNextInt(scanner)
		xm[x] = xm[x] + 1
		mm[x%m] = mm[x%m] + 1
	}
	ans := 0
	for v, c := range mm {
		if v == 0 || v == m-v {
			ans += c >> 1
			continue
		}
		if c <= mm[m-v] {
			ans += c
			mm[m-v] -= c
			mm[v] -= c
			continue
		}
		erase[v] = c - mm[m-v]
	}
	for x, c := range xm {
		p := minint(erase[x%m], c) >> 1
		ans += p
		erase[x%m] -= p << 1
	}

	fmt.Fprintln(writer, ans)
}

