	modPairNums [100000 + 5]int
	nums        [100000 + 5]int
)

func main() {
	n, m = ReadInt2()
	X = ReadIntSlice(n)

	for i := 0; i < n; i++ {
		x := X[i]
		modNums[x%m]++
		nums[x]++
	}
	// modごとに奇数個のものの和をカウントする
	for x := 1; x <= 100000; x++ {
		num := nums[x]
		modPairNums[x%m] += num / 2
	}

	ans := modNums[0] / 2
	for i := 1; i <= m/2; i++ {
		if m%2 == 0 && i == m/2 {
			continue
		}

		j := m - i
		var minNum int // i, jで個数が少ない方の個数
		var lmod int   // i, jのうち個数が多いほう
		if modNums[i] < modNums[j] {
			minNum = modNums[i]
			lmod = j
		} else {
			minNum = modNums[j]
			lmod = i
		}
		// 小さい方を答えに加算
		ans += minNum

		// lmodの中で組めるだけの同一ペアを作る
		// minNumは余らせる必要がある
		p := (modNums[lmod] - minNum) / 2
		ans += Min(p, modPairNums[lmod])
	}

	if m%2 == 0 {
		ans += modNums[m/2] / 2
	}

	fmt.Println(ans)
}

// Min returns the min integer among input set.
// This function needs at least 1 argument (no argument causes panic).
func Min(integers ...int) int {
	m := integers[0]
	for i, integer := range integers {
		if i == 0 {
			continue
		}
		if m > integer {
			m = integer
		}
	}
	return m
}

