        int c;
        for (int j; j < NS[i].length; ++j) {
            if (NS[i].length > j+1 && NS[i][j] == NS[i][j+1]) {
                ++c;
                ++j;
            }
        }
        ans += min(c, R[i]/2);
    }
    writeln(ans);
}

