def calc_two(d1, d2):
    res = 0
    # print(d1, d2)
    if len(d1) == 0:
        for v in d2.values():
            res += v // 2
        return res
    elif len(d2) == 0:
        for v in d1.values():
            res += v // 2
        return res
    vs1 = list(d1.values())
    vs1.sort()
    vs2 = list(d2.values())
    vs2.sort()
    # print(vs1, vs2)
    N1 = len(vs1)
    N2 = len(vs2)
    i = 0
    j = 0
    while i < N1 and j < N2:
        if vs1[i] < vs2[j]:
            res += vs1[i]
            vs2[j] -= vs1[i]
            i += 1
        elif vs1[i] > vs2[j]:
            res += vs2[j]
            vs1[i] -= vs2[j]
