    M = [deque() for _ in range(m)]
    for i in range(n):
        for j in range(len(cnt_list[i])):
            for _ in range(i + 1):
                M[cnt_list[i][j] % m].append(cnt_list[i][j])

    res = 0
    unused = defaultdict(int)
    for i in range(m):
        if i == 0 or (m % 2 == 0 and m // 2 == i):
            while len(M[i]) >= 2:
                M[i].popleft()
                M[i].popleft()
                res += 1
        else:
            while M[i] and M[m - i]:
                M[i].popleft()
                M[m - i].popleft()
                res += 1
            while M[i]:
                num = M[i].popleft()
                if unused.get(num, -1) == -1:
                    unused[num] += 1
                else:
                    res += 1
                    unused[num] -= 1
    print(res)


