def solve():
    n, m = LI()
    x = LI()
    d = defaultdict(int)
    l = [defaultdict(int) for _ in range(m)]
    for a in x: d[a % m] += 1; l[a % m][a] += 1
    ans = 0
    for a in range(m // 2 + 1):
        if a == m - a or a == 0:
            ans += d[a] >> 1
        else:
            tmp = min(d[a], d[m - a])
            ans += tmp
            if d[a] < d[m - a]:
                tmp = d[m - a] - d[a]
                for key, value in l[m - a].items():
                    if tmp < 2:
                        break
                    if value >= 2:
                        t = min(tmp, value >> 1)
                        ans += t
                        tmp -= t
            else:
