fn solve() {
    let (n,m) = get!(usize, usize);
    let x = get!([usize]);
    let mut vec = vec![BTreeMap::new(); m];
    for e in x {
        *vec[e%m].entry(e).or_insert(0) += 1;
    }
    let mut vec = vec.into_iter().map(|e| {
        let mut heap = BinaryHeap::new();
        let mut size = 0;
        for (k,v) in e {
            heap.push(v);
            size += v;
        }
        (size,heap)
    }).collect::<Vec<_>>();

    let mut res = 0usize;
    for i in 0..m/2+1 {
        let mut count = 0;
        if i == 0 || i == m-i {
            while let Some(num) = vec[i].1.pop() {
                count += num;
            }
            count /= 2;
        } else {
            let mut t = vec[i].clone();
            let mut s = vec[m-i].clone();
            if t.0 > s.0 {
                std::mem::swap(&mut t,&mut s);
            }
            let mx = s.0 - t.0;
            let mut c = 0;
            while 2*c < mx && s.1.len() > 0 {
                let num = s.1.pop().unwrap();
                if 2*c+num > mx {
                    c += (mx-2*c)/2;
                    break;
                }
                c += num/2;
            }
            count += c+t.0;
        }
        res += count;
    }
    println!("{}",res);
}

