        }
        let m1 = i;
        let m2 = (M-i)%M;
        let a = p[m1]+abu[m1];
        let b = p[m2]+abu[m2];
        let c = cmp::min(a,b);
        if c>=abu[m1]{
            p[m1] -= cmp::min(p[m1], c-abu[m1]);
            abu[m1] = 0;
        }
        else{
            abu[m1]-=c;
        }
        if c>=abu[m2]{
            p[m2] -= cmp::min(p[m2], c-abu[m2]);
            abu[m2] = 0;
        }
        else{
            abu[m2]-=c;
        }
        res += c;
        res += p[m1]/2;
        res += p[m2]/2;
    }
    //println!("{}", res);
    res += (p[0]+abu[0])/2;
    if M%2 == 0{
        res += (p[M/2]+abu[M/2])/2;
    }
    println!("{}", res);

}


