    d: i64,
}

#[allow(dead_code)]
impl <K: Eq + Hash> Counter<K> {
    fn new() -> Counter<K> {
        Counter {cnt: HashMap::new(), d: 0}
    }
    fn dec(&mut self, key: K, delta: i64) {
        if let Some(r) = self.get_mut(&key) {
            *r -= delta;
            if self.cnt[&key] <= 0 {
                self.remove(&key);
            }
        }
    }
}

#[allow(dead_code)]
impl <K: Eq + Hash> Deref for Counter<K> {
    type Target = HashMap<K, i64>;
    fn deref(&self) -> &Self::Target {
