    let (n, m) = (v[0], v[1]);
    let mut x = read_vec::<usize>();
    x.sort();
    let mut i = 0;
    let mut pairs = HashMap::new();
    let mut paired_idx = HashSet::new();
    while i + 1 < n {
        if x[i] == x[i + 1] {
            *pairs.entry(x[i] % m).or_insert(0) += 1;
            paired_idx.insert(i);
            paired_idx.insert(i + 1);
            i += 2;
            continue;
        }
        i += 1;
    }
    debug!(paired_idx);

    let mut mod_dict = vec![0; m];
    for i in 0..n {
        if paired_idx.contains(&i) {
            continue;
        }
        mod_dict[x[i] % m] += 1;
    }

    let mut ans = paired_idx.len() / 2;
    debug!(ans, mod_dict);
    for i in 0..m {
        if i == m - i || i == 0 {
            ans += mod_dict[i] / 2;
            mod_dict[i] -= (mod_dict[i] / 2) * 2;
            continue;
        }
        let pairable = min(mod_dict[i], mod_dict[m - i]);
        ans += pairable;
        mod_dict[i] -= pairable;
        mod_dict[m - i] -= pairable;
    }
    debug!(ans, mod_dict);

    for &same_key in pairs.keys() {
        if same_key == 0 || same_key == m - same_key {
