fn dijkstra(s:usize, g:&Vec<Vec<(usize, i64)>>)->(Vec<usize>, Vec<i64>){
    let mut d = vec![INF;g.len()];
    let mut prev = vec![g.len();g.len()];
    d[s] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, s));
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut v = top.1;
        let mut l = top.0 * -1;
        if l > d[v]{
            continue;
        }
        for i in 0..g[v].len(){
            let nl = l + g[v][i].1;
            let n = g[v][i].0;
            if d[n] > nl{
                prev[n] = v;
                d[n] = nl;
                h.push((nl*-1, n));
            }
        }
    }
    (prev, d)
}
fn dijkstra2(X:usize, Y:usize, g:&Vec<Vec<char>>, xx:i64)->Vec<Vec<i64>>{
    let mut d = vec![vec![INF;g[0].len()];g.len()];
    d[X][Y] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, X as i64, Y as i64));
    let dx = vec![0,0,-1, 1];
    let dy = vec![1, -1, 0, 0];
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut x = top.1;
        let mut y = top.2;
        let mut l = top.0 * -1;
        if l > d[x as usize][y as usize]{
            continue;
        }
        for i in 0..4{
            let mut nx = dx[i]+x;
            let mut ny = dy[i]+y;
            if 0<=nx && nx<g.len() as i64 && 0<=ny && ny<g[0].len() as i64{
                let mut nx = nx as usize;
                let mut ny = ny as usize;
                let nl = l + if g[nx][ny] == '#'{xx}else{1};
                if d[nx][ny]>nl{
                    d[nx][ny] = nl;
                    h.push((nl*-1, nx as i64, ny as i64));
                }
            }

        }
    }
    d
}
fn solve(){
    //let sssss = std::io::stdin();
    //let mut sc = Scanner { stdin: sssss.lock() };
    input!{
        N:usize,
        M:usize,
        x:[usize;N],
    }
    let mut x = x.clone();
    x.sort();
    let mut p = vec![0;M+2];
    let mut abu = p.clone();
    let mut bef = 0;
    let mut c = 0;
    for i in 0..N{
        if bef == x[i]{
            c+=1;
        }
        else{
            p[bef%M]+=(c/2)*2;
            abu[bef%M]+=c%2;
            bef = x[i];
            c = 1;
        }
    }
    p[bef%M]+=c/2;
    abu[bef%M]+=c%2;
    let mut res = 0;
    //println!("{:?}", p);
    //println!("{:?}", abu);
    for i in (1..M).rev(){
        if M%2 == 0 &&  i == M/2{
            continue;
        }
        let m1 = i;
        let m2 = (M-i)%M;
        let a = p[m1]+abu[m1];
        let b = p[m2]+abu[m2];
        let c = cmp::min(a,b);
        if c>=abu[m1]{
            p[m1] -= c-abu[m1];
            abu[m1] = 0;
        }
        else{
            abu[m1]-=c;
        }
        if c>=abu[m2]{
            p[m2] -= c-abu[m2];
            abu[m2] = 0;
        }
        else{
            abu[m2]-=c;
        }
        res += c;
        res += p[m1]/2;
        res += p[m2]/2;
    }
    //println!("{}", res);
    res += (p[0]+abu[0])/2;
    if M%2 == 0{
        res += (p[M/2]+abu[M/2])/2;
    }
    println!("{}", res);

}


