            let st = vec![xcnt_modm[i], xcnt_modm[m - i]];
            if st[0] < st[1] {
                let delta = st[1] - st[0];
                ret += st[0] + min(delta / 2, xcnt_pair_modm[m - i]);
            } else {
                let delta = st[0] - st[1];
                ret += st[1] + min(delta / 2, xcnt_pair_modm[i]);
            }
        }
    }
    println!("{}", ret);
}

