            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}

#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve() {
    let (n,m) = get!(usize, usize);
    let x = get!([usize]);
    let mut vec = vec![BTreeMap::new(); m];
    for e in x {
        *vec[e%m].entry(e).or_insert(0) += 1;
    }
    debug!(vec);
    let mut vec = vec.into_iter().map(|e| {
        let mut heap = BinaryHeap::new();
        for (k,v) in e {
            heap.push(Rev(v));
        }
        heap
    }).collect::<Vec<_>>();

    let mut res = 0;
    for i in 0..m/2+1 {
        let mut count = 0;
        if i == 0 || i == m-i {
            while let Some(Rev(num)) = vec[i].pop() {
                count += num;
            }
            count /= 2;
        } else {
            while vec[i].len() > 0 && vec[m-i].len() > 0 {
                let Rev(val1) = vec[i].pop().unwrap();
                let Rev(val2) = vec[m-i].pop().unwrap();
                if val1 > 1 {
                    vec[i].push(Rev(val1-1));
                }
                if val2 > 1 {
                    vec[m-i].push(Rev(val2-1));
                }
                count += 1;
            }
        }
        res += count;
    }
    for i in 0..m {
        while let Some(Rev(num)) = vec[i].pop() {
            res += num/2;
        }
    }
    println!("{}",res);
}

