use std::cmp::min;
fn main() {
    input! { n, m, x: [usize; n] };
    let xmax = *x.iter().max().unwrap();
    let mut rem = vec![0; m];
    let mut cnt = vec![0; xmax + 1];
    let mut sm = vec![0; m];
    for &xi in x.iter() {
        rem[xi % m] += 1;
        cnt[xi] += 1;
    }
    for i in 1..xmax + 1 {
        sm[i % m] += cnt[i] / 2;
    }
    let mut ans = 0;
    for i in 0..m / 2 + 1 {
        let j = (m - i) % m;
        if i == j {
            ans += rem[i] / 2;
        } else if rem[i] < rem[j] {
            ans += rem[i] + min(sm[j] * 2, rem[j] - rem[i]) / 2;
        } else {
            ans += rem[j] + min(sm[i] * 2, rem[i] - rem[j]) / 2;
        }
    }
    println!("{}", ans);
}

